        xml_lmt_tax_excl_amt_node                               dbms_xmldom.DOMNode;
        xml_lmt_tax_excl_amt_text_node                          dbms_xmldom.DOMNode;

        xml_lmt_tax_incl_amt_element                            dbms_xmldom.DOMElement;
        xml_lmt_tax_incl_amt_node                               dbms_xmldom.DOMNode;
        xml_lmt_tax_incl_amt_text_node                          dbms_xmldom.DOMNode;

        xml_lmt_payable_amt_element                             dbms_xmldom.DOMElement;
        xml_lmt_payable_amt_node                                dbms_xmldom.DOMNode;
        xml_lmt_payable_amt_text_node                           dbms_xmldom.DOMNode;

