        xml_inv_line_item_buyer_item_ident_node                 dbms_xmldom.DOMNode;

        xml_inv_line_item_buyer_item_ident_id_node              dbms_xmldom.DOMNode;
        xml_inv_line_item_buyer_item_ident_id_text_node         dbms_xmldom.DOMNode;


        xml_inv_line_item_seller_item_ident_node                dbms_xmldom.DOMNode;

        xml_inv_line_item_seller_item_ident_id_node             dbms_xmldom.DOMNode;
