        xml_inv_line_classified_tax_cat_node                    dbms_xmldom.DOMNode;

        xml_inv_line_class_tax_cat_id_node                      dbms_xmldom.DOMNode;
        xml_inv_line_class_tax_cat_id_text_node                 dbms_xmldom.DOMNode;

