                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxCategory')));

                xml_tax_category_id_node                                := dbms_xmldom.appendChild(xml_tax_category_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                xml_tax_category_id_text_node                           := dbms_xmldom.appendChild(xml_tax_category_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxTotal_TaxSubtotal_TaxCategory_ID)));

                xml_tax_category_percent_node                           := dbms_xmldom.appendChild(xml_tax_category_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Percent')));
                xml_tax_category_percent_text_node                      := dbms_xmldom.appendChild(xml_tax_category_percent_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxTotal_TaxSubtotal_TaxCategory_Percent)));

                IF UPPER(TRIM(v_TaxTotal_TaxSubtotal_TaxCategory_ID)) <> 'S' THEN

                    xml_tax_category_exemption_code_node                := dbms_xmldom.appendChild(xml_tax_category_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxExemptionReasonCode')));
                    xml_tax_category_exemption_code_text_node           := dbms_xmldom.appendChild(xml_tax_category_exemption_code_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonCode)));

                    xml_tax_category_exemption_text_node                := dbms_xmldom.appendChild(xml_tax_category_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxExemptionReason')));
                    xml_tax_category_exemption_text_text_node           := dbms_xmldom.appendChild(xml_tax_category_exemption_text_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonText)));

                END IF;

                -----------------------------------------------------------
                -- Tax Scheme
                -----------------------------------------------------------
                xml_tax_scheme_node                                     := dbms_xmldom.appendChild(xml_tax_category_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxScheme')));

                xml_tax_scheme_id_node                                  := dbms_xmldom.appendChild(xml_tax_scheme_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                xml_tax_scheme_id_text_node                             := dbms_xmldom.appendChild(xml_tax_scheme_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID)));

                -----------------------------------------------------------
                -- Tax Total RON
                -----------------------------------------------------------
                -- Only show this section if the CurrencyID attribute in the TaxTotal > Tax Amount node above is not RON

                IF UPPER(TRIM(v_TaxTotal_TaxAmount__CurrencyID)) <> 'RON' THEN

                    xml_tax_total_ron_node                              := dbms_xmldom.appendChild(xml_invoice_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxTotal')));

                    xml_tax_amount_ron_element                          := dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxAmount');
                    dbms_xmldom.setAttribute(xml_tax_amount_ron_element, 'currencyID', v_TaxTotal_TaxAmount__Local__CurrencyID);

                    xml_tax_amount_ron_node                             := dbms_xmldom.appendChild(xml_tax_total_ron_node,
                                                                            dbms_xmldom.makeNode(xml_tax_amount_ron_element));
                    xml_tax_amount_ron_text_node                        := dbms_xmldom.appendChild(xml_tax_amount_ron_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxTotal_TaxAmount__Local)));
                END IF;

                -----------------------------------------------------------
                -- Legal Monetary Total
                -----------------------------------------------------------
                xml_legal_monetary_total_node                           := dbms_xmldom.appendChild(xml_invoice_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:LegalMonetaryTotal')));

                xml_lmt_line_ext_amt_element                            := dbms_xmldom.createElement(xml_domdoc, 'cbc:LineExtensionAmount');
                dbms_xmldom.setAttribute(xml_lmt_line_ext_amt_element, 'currencyID', v_LegalMonetaryTotal_LineExtensionAmount__CurrencyID);

                xml_lmt_line_ext_amt_node                               := dbms_xmldom.appendChild(xml_legal_monetary_total_node,
                                                                            dbms_xmldom.makeNode(xml_lmt_line_ext_amt_element));
                xml_lmt_line_ext_amt_text_node                          := dbms_xmldom.appendChild(xml_lmt_line_ext_amt_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_LineExtensionAmount)));

                xml_lmt_tax_excl_amt_element                            := dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxExclusiveAmount');
                dbms_xmldom.setAttribute(xml_lmt_tax_excl_amt_element, 'currencyID', v_LegalMonetaryTotal_TaxExclusiveAmount__CurrencyID);

                xml_lmt_tax_excl_amt_node                               := dbms_xmldom.appendChild(xml_legal_monetary_total_node,
                                                                            dbms_xmldom.makeNode(xml_lmt_tax_excl_amt_element));
                xml_lmt_tax_excl_amt_text_node                          := dbms_xmldom.appendChild(xml_lmt_tax_excl_amt_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_TaxExclusiveAmount)));

                xml_lmt_tax_incl_amt_element                            := dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxInclusiveAmount');
                dbms_xmldom.setAttribute(xml_lmt_tax_incl_amt_element, 'currencyID', v_LegalMonetaryTotal_TaxInclusiveAmount__CurrencyID);

                xml_lmt_tax_incl_amt_node                               := dbms_xmldom.appendChild(xml_legal_monetary_total_node,
                                                                            dbms_xmldom.makeNode(xml_lmt_tax_incl_amt_element));
                xml_lmt_tax_incl_amt_text_node                          := dbms_xmldom.appendChild(xml_lmt_tax_incl_amt_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_TaxInclusiveAmount)));

                xml_lmt_payable_amt_element                             := dbms_xmldom.createElement(xml_domdoc, 'cbc:PayableAmount');
                dbms_xmldom.setAttribute(xml_lmt_payable_amt_element, 'currencyID', v_LegalMonetaryTotal_PayableAmount__CurrencyID);

                xml_lmt_payable_amt_node                               := dbms_xmldom.appendChild(xml_legal_monetary_total_node,
                                                                            dbms_xmldom.makeNode(xml_lmt_payable_amt_element));
                xml_lmt_payable_amt_text_node                           := dbms_xmldom.appendChild(xml_lmt_payable_amt_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_PayableAmount)));

                OPEN c_detail;

                LOOP

                    FETCH
                        c_detail
                    INTO
                         v_DetailTaskID
                        ,v_InvoiceLine_ID
                        ,v_InvoiceLine_InvoiceQuantity
                        ,v_InvoiceLine_InvoiceQuantity__UnitCode
                        ,v_InvoiceLine_LineExtentionAmount
                        ,v_InvoiceLine_LineExtentionAmount__CurrencyID
                        ,v_InvoiceLine_OrderLineRef_LineID
                        ,v_InvoiceLine_Item_Name
                        ,v_InvoiceLine_Item_BuyerItemID
                        ,v_InvoiceLine_Item_SellerItemID
                        ,v_InvoiceLine_Item_OriginCountryCode
                        ,v_InvoiceLine_Item_ClassifiedTaxCategory_ID
                        ,v_InvoiceLine_Item_ClassifiedTaxCategory_Percent
                        ,v_InvoiceLine_Item_ClassifiedTaxCategory_TaxScheme_ID
                        ,v_InvoiceLine_Price_PriceAmount
                        ,v_InvoiceLine_Price_PriceAmount__CurrencyID;

                    EXIT WHEN c_detail%NOTFOUND;

                    -----------------------------------------------------------
                    -- Invoice Line
                    -----------------------------------------------------------
                    xml_invoice_line_node                                   := dbms_xmldom.appendChild(xml_invoice_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:InvoiceLine')));

                    xml_inv_line_id_node                                    := dbms_xmldom.appendChild(xml_invoice_line_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_inv_line_id_text_node                               := dbms_xmldom.appendChild(xml_inv_line_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_ID )));

                    xml_inv_line_inv_qty_element                            := dbms_xmldom.createElement(xml_domdoc, 'cbc:InvoicedQuantity ');
                    dbms_xmldom.setAttribute(xml_inv_line_inv_qty_element, 'unitCode', v_InvoiceLine_InvoiceQuantity__UnitCode);
                    xml_inv_line_inv_qty_node                               := dbms_xmldom.appendChild(xml_invoice_line_node,
                                                                                dbms_xmldom.makeNode(xml_inv_line_inv_qty_element));
                    xml_inv_line_inv_qty_text_node                          := dbms_xmldom.appendChild(xml_inv_line_inv_qty_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_InvoiceQuantity)));

                    xml_inv_line_line_ext_amt_element                       := dbms_xmldom.createElement(xml_domdoc, 'cbc:LineExtensionAmount');
                    dbms_xmldom.setAttribute(xml_inv_line_line_ext_amt_element, 'currencyID', v_InvoiceLine_LineExtentionAmount__CurrencyID);
                    xml_inv_line_line_ext_amt_node                          := dbms_xmldom.appendChild(xml_invoice_line_node,
                                                                                dbms_xmldom.makeNode(xml_inv_line_line_ext_amt_element));
                    xml_inv_line_line_ext_amt_text_node                     := dbms_xmldom.appendChild(xml_inv_line_line_ext_amt_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_LineExtentionAmount)));

                    -----------------------------------------------------------
                    -- Order Line Reference
                    -----------------------------------------------------------
                    -- Do not display wrapper or LineID nodes if LineID is blank/null
                    IF TRIM(v_InvoiceLine_OrderLineRef_LineID) IS NOT NULL THEN

                        xml_inv_line_order_line_ref_node                        := dbms_xmldom.appendChild(xml_invoice_line_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:OrderLineReference')));

                        xml_inv_line_order_line_ref_line_id_node                := dbms_xmldom.appendChild(xml_inv_line_order_line_ref_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:LineID')));
                        xml_inv_line_order_line_ref_line_id_text_node           := dbms_xmldom.appendChild(xml_inv_line_order_line_ref_line_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_OrderLineRef_LineID )));
                    END IF;

                    -----------------------------------------------------------
                    -- Item
                    -----------------------------------------------------------
                    xml_inv_line_item_node                                  := dbms_xmldom.appendChild(xml_invoice_line_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Item')));

                    xml_inv_line_item_name_node                             := dbms_xmldom.appendChild(xml_inv_line_item_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Name')));
                    xml_inv_line_item_name_text_node                        := dbms_xmldom.appendChild(xml_inv_line_item_name_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Item_Name)));

                    -- Do not display nodes if value is blank/null
                    IF TRIM(v_InvoiceLine_Item_BuyerItemId) IS NOT NULL THEN

                        xml_inv_line_item_buyer_item_ident_node                 := dbms_xmldom.appendChild(xml_inv_line_item_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:BuyersItemIdentification')));

                        xml_inv_line_item_buyer_item_ident_id_node              := dbms_xmldom.appendChild(xml_inv_line_item_buyer_item_ident_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                        xml_inv_line_item_buyer_item_ident_id_text_node         := dbms_xmldom.appendChild(xml_inv_line_item_buyer_item_ident_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Item_BuyerItemId)));
                    END IF;

                    -- Do not display nodes if value is blank/null
                    IF TRIM(v_InvoiceLine_Item_SellerItemId) IS NOT NULL THEN

                        xml_inv_line_item_seller_item_ident_node                := dbms_xmldom.appendChild(xml_inv_line_item_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:SellersItemIdentification')));

                        xml_inv_line_item_seller_item_ident_id_node             := dbms_xmldom.appendChild(xml_inv_line_item_seller_item_ident_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                        xml_inv_line_item_seller_item_ident_id_text_node        := dbms_xmldom.appendChild(xml_inv_line_item_seller_item_ident_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Item_SellerItemId)));
                    END IF;


--                    xml_inv_line_item_origin_country_node                   := dbms_xmldom.appendChild(xml_inv_line_item_node,
--                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:OriginCountry')));
--
--                    xml_inv_line_item_origin_country_code_node              := dbms_xmldom.appendChild(xml_inv_line_item_origin_country_node,
--                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IdentificationCode')));
--                    xml_inv_line_item_origin_country_code_text_node         := dbms_xmldom.appendChild(xml_inv_line_item_origin_country_code_node,
--                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Item_OriginCountryCode)));

                    -----------------------------------------------------------
                    -- Classified Tax Category
                    -----------------------------------------------------------
                    xml_inv_line_classified_tax_cat_node                    := dbms_xmldom.appendChild(xml_inv_line_item_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:ClassifiedTaxCategory')));

                    xml_inv_line_class_tax_cat_id_node                      := dbms_xmldom.appendChild(xml_inv_line_classified_tax_cat_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_inv_line_class_tax_cat_id_text_node                 := dbms_xmldom.appendChild(xml_inv_line_class_tax_cat_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Item_ClassifiedTaxCategory_ID)));

                    xml_inv_line_class_tax_id_percent_node                  := dbms_xmldom.appendChild(xml_inv_line_classified_tax_cat_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Percent')));
                    xml_inv_line_class_tax_id_percent_text_node             := dbms_xmldom.appendChild(xml_inv_line_class_tax_id_percent_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Item_ClassifiedTaxCategory_Percent)));

                    -----------------------------------------------------------
                    -- Invoice Line Tax Scheme
                    -----------------------------------------------------------
                    xml_inv_line_tax_scheme_node                            := dbms_xmldom.appendChild(xml_inv_line_classified_tax_cat_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxScheme')));

                    xml_inv_line_tax_scheme_id_node                         := dbms_xmldom.appendChild(xml_inv_line_tax_scheme_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_inv_line_tax_scheme_id_text_node                    := dbms_xmldom.appendChild(xml_inv_line_tax_scheme_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Item_ClassifiedTaxCategory_TaxScheme_ID)));

                    -----------------------------------------------------------
                    -- Invoice Line Price
                    -----------------------------------------------------------
                    xml_inv_line_price_node                                 := dbms_xmldom.appendChild(xml_invoice_line_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Price')));

                    xml_inv_line_price_amt_element                          := dbms_xmldom.createElement(xml_domdoc, 'cbc:PriceAmount');
                    dbms_xmldom.setAttribute(xml_inv_line_price_amt_element, 'currencyID', v_InvoiceLine_Price_PriceAmount__CurrencyID);
                    xml_inv_line_price_amt_node                             := dbms_xmldom.appendChild(xml_inv_line_price_node,
                                                                                dbms_xmldom.makeNode(xml_inv_line_price_amt_element));
                    xml_inv_line_price_amt_text_node                        := dbms_xmldom.appendChild(xml_inv_line_price_amt_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Price_PriceAmount)));

                END LOOP;

                CLOSE c_detail;

            END LOOP;

            CLOSE c_header;

            xml_xmltype     := dbms_xmldom.getXmlType(xml_domdoc);
            dbms_xmldom.freeDocument(xml_domdoc);

            IF v_records_found = TRUE THEN

                o_xml_clob      := xml_xmltype.getClobVal;

            ELSE

                o_xml_clob      := TO_CLOB('No Data Found');

            END IF;

        EXCEPTION
            WHEN OTHERS THEN

                v_err_nbr := SQLCODE;
                v_err_msg := v_err_job_name || ' - '||SQLERRM;

                ------------------------------------------------------
                -- Rollback changes
                ------------------------------------------------------
                ROLLBACK;

                ------------------------------------------------------
                -- Insert record into PL/SQL logging table
                ------------------------------------------------------
                INSERT INTO
                    commobj.joberr
                    (
                        job_name,
                        err#,
                        err_msg,
                        TIMESTAMP
                    )
                    VALUES
                    (
                        v_err_job_name,
                        v_err_nbr,
                        v_err_msg,
                        SYSDATE
                    );

                COMMIT;

                o_return_message := 'FAILURE: ' || SQLERRM;

    END USP_RO_INVOICE_XML_SELECT;





    /***********************************************************************************************************
    ***********************************************************************************************************/
    -- USP_RO_CREDIT_NOTE_XML_SELECT
    /***********************************************************************************************************
    ***********************************************************************************************************/

    -- Create Batched Credit Note XML document to send to Avalara

    PROCEDURE USP_RO_CREDIT_NOTE_XML_SELECT
    (
         o_xml_clob         OUT    NOCOPY CLOB
        ,o_return_message   OUT    VARCHAR2
    )
    IS
        ------------------------------------------------------
        -- Declare Exception Variables
        ------------------------------------------------------
        v_err_job_name          VARCHAR2(30)        := 'USP_CREDIT_NOTE_XML_SELECT';
        v_err_nbr               VARCHAR2(10)        := ' ';
        v_err_msg               VARCHAR2(2000)      := ' ';

        ------------------------------------------------------
        -- Declare Audit Variables
        ------------------------------------------------------
        v_pid                   VARCHAR2(10)        := SUBSTR('PKG_E_INVOICING',5,10);
        v_jobn                  VARCHAR2(10)        := '';
        v_user                  VARCHAR2(10)        := 'BIZTALK';
        v_upmj                  NUMBER(6)           := 0;
        v_upmt                  NUMBER(6)           := 0;

        ------------------------------------------------------
        -- Declare Other Variables
        ------------------------------------------------------
        v_records_found         BOOLEAN             := FALSE;

        ---------------------------------------------------
        -- Declare Header Cursor Variables
        ---------------------------------------------------
        v_HeaderTaskID                                                  VARCHAR2(36 BYTE)   :=  '';
        v_CustomizationID                                               VARCHAR2(200 BYTE)  :=  '';
        v_CreditNote_ID                                                 NUMBER              :=  0;
        v_IssueDate                                                     VARCHAR2(50 BYTE)   :=  '';
        v_DueDate                                                       VARCHAR2(50 BYTE)   :=  '';
        v_InvoiceTypeCode                                               VARCHAR2(50 BYTE)   :=  '';
        v_DocumentCurrencyCode                                          VARCHAR2(3 BYTE)    :=  '';
        v_TaxCurrencyCode                                               VARCHAR2(3 BYTE)    :=  '';
        v_OrderReference_ID                                             VARCHAR2(25 BYTE)   :=  '';
        v_SalesOrder_ID                                                 NUMBER              :=  0;
        v_InvoiceDocumentRef_ID                                         NUMBER              :=  0;
        v_InvoiceDocumentRef_IssueDate                                  VARCHAR2(50 BYTE)   :=  '';
        v_ASP_Party_PostalAddress_StreetName                            VARCHAR2(200 BYTE)  :=  '';
        v_ASP_Party_PostalAddress_CityName                              VARCHAR2(25 BYTE)   :=  '';
        v_ASP_Party_PostalAddress_PostalZone                            VARCHAR2(12 BYTE)   :=  '';
        v_ASP_Party_PostalAddress_CountrySubentity                      VARCHAR2(10 BYTE)   :=  '';
        v_ASP_Party_PostalAddress_Country_IdentificationCode            VARCHAR2(3 BYTE)    :=  '';
        v_ASP_Party_PartyTaxScheme_CompanyID                            VARCHAR2(20 BYTE)   :=  '';
        v_ASP_Party_PartyTaxScheme_TaxScheme_ID                         VARCHAR2(50 BYTE)   :=  '';
        v_ASP_Party_PartyLegalEntity_RegistrationName                   VARCHAR2(40 BYTE)   :=  '';
        v_ASP_Party_PartyLegalEntity_CompanyID                          VARCHAR2(50 BYTE)   :=  '';
        v_ACP_Party_PostalAddress_StreetName                            VARCHAR2(200 BYTE)  :=  '';
        v_ACP_Party_PostalAddress_CityName                              VARCHAR2(25 BYTE)   :=  '';
        v_ACP_Party_PostalAddress_PostalZone                            VARCHAR2(12 BYTE)   :=  '';
        v_ACP_Party_PostalAddress_CountrySubentity                      VARCHAR2(10 BYTE)   :=  '';
        v_ACP_Party_PostalAddress_Country_IdentificationCode            VARCHAR2(3 BYTE)    :=  '';
        v_ACP_Party_PartyTaxScheme_CompanyID                            VARCHAR2(25 BYTE)   :=  '';
        v_ACP_Party_PartyTaxScheme_TaxScheme_ID                         VARCHAR2(50 BYTE)   :=  '';
        v_ACP_Party_PartyLegalEntity_RegistrationName                   VARCHAR2(40 BYTE)   :=  '';
        v_Delivery_DeliveryLocation_Address_StreetName                  VARCHAR2(200 BYTE)  :=  '';
        v_Delivery_DeliveryLocation_Address_CityName                    VARCHAR2(25 BYTE)   :=  '';
        v_Delivery_DeliveryLocation_Address_PostalZone                  VARCHAR2(12 BYTE)   :=  '';
        v_Delivery_DeliveryLocation_Address_CountrySubentity            VARCHAR2(10 BYTE)   :=  '';
        v_Delivery_DeliveryLocation_Address_Country_IndentificationCode VARCHAR2(3 BYTE)    :=  '';
        v_Delivery_DeliveryParty_PartyName_Name                         VARCHAR2(40 BYTE)   :=  '';
        v_PaymentMeans_PaymentMeansCode                                 VARCHAR2(50 BYTE)   :=  '';
        v_PaymentTerms_Note                                             VARCHAR2(30 BYTE)   :=  '';
        v_TaxTotal_TaxAmount                                            NUMBER              :=  0;
        v_TaxTotal_TaxAmount__CurrencyID                                VARCHAR2(3 BYTE)    :=  '';
        v_TaxTotal_TaxSubtotal_TaxableAmount                            NUMBER              :=  0;
        v_TaxTotal_TaxSubtotal_TaxableAmount__CurrencyID                VARCHAR2(3 BYTE)    :=  '';
        v_TaxTotal_TaxSubtotal_TaxAmount                                NUMBER              :=  0;
        v_TaxTotal_TaxSubtotal_TaxAmount__CurrencyID                    VARCHAR2(3 BYTE)    :=  '';
        v_TaxTotal_TaxSubtotal_TaxCategory_ID                           VARCHAR2(2 BYTE)    :=  '';
        v_TaxTotal_TaxSubtotal_TaxCategory_Percent                      NUMBER              :=  0;
        v_TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonCode       VARCHAR2(100 BYTE)  :=  '';
        v_TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonText       VARCHAR2(200 BYTE)  :=  '';
        v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID                 VARCHAR2(50 BYTE)   :=  '';
        v_TaxTotal_TaxAmount__Local                                     NUMBER              :=  0;
        v_TaxTotal_TaxAmount__Local__CurrencyID                         VARCHAR2(3 BYTE)    :=  '';
        v_LegalMonetaryTotal_LineExtensionAmount                        NUMBER              :=  0;
