        -----------------------------------------------------------
        -- Declare Cursor Variables
        -----------------------------------------------------------
        CURSOR c_header IS
            SELECT DISTINCT
                 TRIM(f550301h.ehtaskid)                                                    AS HeaderTaskID
                ,'urn:cen.eu:en16931:2017#compliant#urn:efactura.mfinante.ro:CIUS-RO:1.0.1' AS CustomizationID
                ,AR_Detail.rpdoc                                                            AS Invoice_ID
                ,TO_CHAR(TO_DATE(TO_CHAR(
                    AR_Detail.rpdivj+1900000),
                    'YYYYDDD'),'yyyy-mm-dd')                                                AS IssueDate
                ,TO_CHAR(TO_DATE(TO_CHAR(
                    AR_Detail.rpddj+1900000),
                    'YYYYDDD'),'yyyy-mm-dd')                                                AS DueDate
                ,CASE
                    WHEN
                        SO_Detail.sddct     IN ('RI','RL')
                    THEN
                        '380'
                    WHEN
                        SO_Detail.sddct     IN ('RM')
                    THEN
                        '381'
                    WHEN
                        SO_Detail.sddct     IS NULL
                        AND AR_Detail.rpdct = 'RM'
                    THEN
                        '381'
                    WHEN
                        SO_Detail.sddct     IS NULL
                        AND AR_Detail.rpdct IN ('RI','RL')
                    THEN
                        '751'
                END                                                                         AS InvoiceTypeCode
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS DocumentCurrencyCode
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                        AND AR_Detail.rpcrcd = 'RON'
                    THEN
                        ''
                    WHEN
                        AR_Detail.rpcrrm = 'D'
                        AND AR_Detail.rpbcrc = 'RON'
                    THEN
                        ''
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS TaxCurrencyCode
                ,TRIM(AR_Detail.rpvr01)                                                     AS OrderReference_ID
                ,AR_Detail.rpsdoc                                                           AS SalesOrder_ID
                ,SO_Detail.sdodoc                                                           AS InvoiceDocumentRef_ID
                    ,TO_CHAR(TO_DATE(TO_CHAR(
                        PrecedingInvoice.rpdivj+1900000),
                        'YYYYDDD'),'yyyy-mm-dd')                                            AS InvoiceDocumentRef_IssueDate
                ,TRIM(CONCAT(TRIM(Seller_Detail.aladd1),
                    CONCAT(TRIM(Seller_Detail.aladd2),
                    CONCAT(TRIM(Seller_Detail.aladd3),
                    TRIM(Seller_Detail.aladd4)))))                                          AS ASP_Party_PostalAddress_StreetName
                ,TRIM(Seller_Detail.alcty1)                                                 AS ASP_Party_PostalAddress_CityName
                ,TRIM(Seller_Detail.aladdz)                                                 AS ASP_Party_PostalAddress_PostalZone
                ,
                (
                    SELECT
                        TRIM(f0005.drky)
                    FROM
                        prodctl.f0005 f0005
                    WHERE
                        TRIM(f0005.drsy) = '00'
                        AND TRIM(f0005.drrt) = 'CT'
                        AND UPPER(TRIM(f0005.DRDL01)) = UPPER(TRIM(Seller_Detail.alcoun))
                )                                                                           AS ASP_Party_PostalAddress_CountrySubentity
                ,TRIM(Seller_Detail.alctr)                                                  AS ASP_Party_PostalAddress_Country_IdentificationCode
                ,REPLACE(Seller_Detail.abtax,' ','')                                        AS ASP_Party_PartyTaxScheme_CompanyID
                ,'VAT'                                                                      AS ASP_Party_PartyTaxScheme_TaxScheme_ID
                ,'PLEXUS SERVICES RO S.R.L.'                                                AS ASP_Party_PartyLegalEntity_RegistrationName
                ,'J05/261/2019'                                                             AS ASP_Party_PartyLegalEntity_CompanyID
                ,TRIM(CONCAT(TRIM(Buyer_Detail.aladd1),
                    CONCAT(TRIM(Buyer_Detail.aladd2),
                    CONCAT(TRIM(Buyer_Detail.aladd3),
                    TRIM(Buyer_Detail.aladd4)))))                                           AS ACP_Party_PostalAddress_StreetName
                ,TRIM(Buyer_Detail.alcty1)                                                  AS ACP_Party_PostalAddress_CityName
                ,TRIM(Buyer_Detail.aladdz)                                                  AS ACP_Party_PostalAddress_PostalZone
                ,
                (
                    SELECT
                        TRIM(f0005.drky)
                    FROM
                        prodctl.f0005 f0005
                    WHERE
                        TRIM(f0005.drsy) = '00'
                        AND TRIM(f0005.drrt) = 'CT'
                        AND UPPER(TRIM(f0005.DRDL01)) = UPPER(TRIM(Buyer_Detail.alcoun))
                )                                                                           AS ACP_Party_PostalAddress_CountrySubentity
                ,TRIM(Buyer_Detail.alctr)                                                   AS ACP_Party_PostalAddress_Country_IdentificationCode
                ,TRIM(Buyer_Detail.abtax)                                                   AS ACP_Party_PartyTaxScheme_CompanyID
                ,'VAT'                                                                      AS ACP_Party_PartyTaxScheme_TaxScheme_ID
                ,TRIM(Buyer_Detail.wwmlnm)                                                  AS ACP_Party_PartyLegalEntity_RegistrationName
                ,CASE
                    WHEN
                        SO_Detail.sdnxtr IS NULL
                    THEN
                        TRIM(CONCAT(TRIM(Buyer_Detail.aladd1),
                            CONCAT(TRIM(Buyer_Detail.aladd2),
                            CONCAT(TRIM(Buyer_Detail.aladd3),
                            TRIM(Buyer_Detail.aladd4)))))
                    ELSE
                        TRIM(CONCAT(TRIM(Shipper_Detail.aladd1),
                            CONCAT(TRIM(Shipper_Detail.aladd2),
                            CONCAT(TRIM(Shipper_Detail.aladd3),
                            TRIM(Shipper_Detail.aladd4)))))
                END                                                                         AS Delivery_DeliveryLocation_Address_StreetName
                ,CASE
                    WHEN
                        SO_Detail.sdnxtr IS NULL
                    THEN
                        TRIM(Buyer_Detail.alcty1)
                    ELSE
                        TRIM(Shipper_Detail.alcty1)
                END                                                                         AS Delivery_DeliveryLocation_Address_CityName
                ,CASE
                    WHEN
                        SO_Detail.sdnxtr IS NULL
                    THEN
                        TRIM(Buyer_Detail.aladdz)
                    ELSE
                        TRIM(Shipper_Detail.aladdz)
                END                                                                         AS Delivery_DeliveryLocation_Address_PostalZone
                ,CASE
                    WHEN
                        SO_Detail.sdnxtr IS NULL
                    THEN
                        (
                            SELECT
                                TRIM(f0005.drky)
                            FROM
                                prodctl.f0005 f0005
                            WHERE
                                TRIM(f0005.drsy) = '00'
                                AND TRIM(f0005.drrt) = 'CT'
                                AND UPPER(TRIM(f0005.DRDL01)) = UPPER(TRIM(Buyer_Detail.alcoun))
                        )
                    ELSE
                        (
                            SELECT
                                TRIM(f0005.drky)
                            FROM
                                prodctl.f0005 f0005
                            WHERE
                                TRIM(f0005.drsy) = '00'
                                AND TRIM(f0005.drrt) = 'CT'
                                AND UPPER(TRIM(f0005.DRDL01)) = UPPER(TRIM(Shipper_Detail.alcoun))
                        )
                END                                                                         AS Delivery_DeliveryLocation_Address_CountrySubentity
                ,CASE
                    WHEN
                        SO_Detail.sdnxtr IS NULL
                    THEN
                        TRIM(Buyer_Detail.alctr)
                    ELSE
                        TRIM(Shipper_Detail.alctr)
                END                                                                         AS Delivery_DeliveryLocation_Address_Country_IndentificationCode
                ,CASE
                    WHEN
                        SO_Detail.sdnxtr IS NULL
                    THEN
                        TRIM(Buyer_Detail.wwmlnm)
                    ELSE
                        TRIM(Shipper_Detail.wwmlnm)
                END                                                                         AS Delivery_DeliveryParty_PartyName_Name
                ,'2'                                                                        AS PaymentMeans_PaymentMeansCode
                ,TRIM(f0014.pnptd)                                                          AS PaymentTerms_Note
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpctam * .01
                    ELSE
                        AR_Detail.rpstam * .01
                END)                                                                        AS TaxTotal_TaxAmount
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS TaxTotal_TaxAmount__CurrencyID
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpctxa * .01
                    ELSE
                        AR_Detail.rpatxa * .01
                END)                                                                        AS TaxTotal_TaxSubtotal_TaxableAmount
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS TaxTotal_TaxSubtotal_TaxableAmount__CurrencyID
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpctam * .01
                    ELSE
                        AR_Detail.rpstam * .01
                END)                                                                        AS TaxTotal_TaxSubtotal_TaxAmount
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS TaxTotal_TaxSubtotal_TaxAmount__CurrencyID
                ,CASE
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS03', 'ROS10','ROS03A')
                    THEN
                        'AE'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS09', 'ROS08E')
                    THEN
                        'E'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS11')
                    THEN
                        'O'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS05', 'ROS06')
                    THEN
                        'G'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS07', 'ROS12')
                    THEN
                        'IC'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS08T')
                    THEN
                        '151'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS01', 'ROS02', 'ROS04','ROS01A','ROS02A')
                    THEN
                        'S'
                    ELSE
                        'S'
                END                                                                         AS TaxTotal_TaxSubtotal_TaxCategory_ID
                ,Tax_Rate.tatxr1 * .001                                                     AS TaxTotal_TaxSubtotal_TaxCategory_Percent
                ,CASE
                    WHEN
                        TRIM(Tax_Rate.tatxa1) IN ('ROS03', 'ROS10','ROS03A')
                    THEN
                        'VATEX-EU-AE'
                    WHEN
                        TRIM(Tax_Rate.tatxa1) IN ('ROS11')
                    THEN
                        'VATEX-EU-O'
                    WHEN
                        TRIM(Tax_Rate.tatxa1) IN ('ROS09', 'ROS08E')
                    THEN
                        'VATEX-EU-79-C'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS05', 'ROS06')
                    THEN
                        'VATEX-EU-G'
                    WHEN
                        TRIM(AR_Detail.rptxa1)  IN ('ROS07', 'ROS12')
                    THEN
                        'VATEX-EU-IC'
                    WHEN
                        TRIM(AR_Detail.rptxa1)  IN ('ROS08T')
                    THEN
                        'VATEX-EU-151'
                    ELSE
                        ''
                END                                                                         AS TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonCode
                ,CASE
                    WHEN
                        TRIM(Tax_Rate.tatxa1) IN ('ROS03', 'ROS10','ROS03A')
                    THEN
                        'Reverse'
                    WHEN
                        TRIM(Tax_Rate.tatxa1) IN ('ROS11')
                    THEN
                        'Not subject to VAT'
                    WHEN
                        TRIM(Tax_Rate.tatxa1) IN ('ROS09', 'ROS08E')
                    THEN
                        'Exempt based on article 79, point c of Council Directive 2006/112/EC'
                    WHEN
                        TRIM(AR_Detail.rptxa1)  IN ('ROS05', 'ROS06')
                    THEN
                        'Free export item, VAT not charged'
                    WHEN
                        TRIM(AR_Detail.rptxa1)  IN ('ROS07', 'ROS12')
                    THEN
                        'Intra-Community supply'
                    WHEN
                        TRIM(AR_Detail.rptxa1)  IN ('ROS08T')
                    THEN
                        'Exempt based on article 151 of Council Directive 2006/112/EC'
                    ELSE
                        ''
                END                                                                         AS TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonText
                ,'VAT'                                                                      AS TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpstam * .01
                    ELSE
                        0
                END)                                                                        AS v_TaxTotal_TaxAmount__Local
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpbcrc)
                    ELSE
                        NULL
                END                                                                         AS TaxTotal_TaxAmount_Local__ID
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpctxa * .01
                    ELSE
                        AR_Detail.rpatxa * .01
                END)                                                                        AS LegalMonetaryTotal_LineExtensionAmount
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS LegalMonetaryTotal_LineExtensionAmount__CurrencyID
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpctxa * .01
                    ELSE
                        AR_Detail.rpatxa * .01
                END)                                                                        AS LegalMonetaryTotal_TaxExclusiveAmount
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS LegalMonetaryTotal_TaxExclusiveAmount__CurrencyID
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpacr * .01
                    ELSE
                        AR_Detail.rpag * .01
                END)                                                                        AS LegalMonetaryTotal_TaxInclusiveAmount
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS LegalMonetaryTotal_TaxInclusiveAmount__CurrencyID
                ,ABS(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpacr * .01
                    ELSE
                        AR_Detail.rpag * .01
                END)                                                                        AS LegalMonetaryTotal_PayableAmount
                ,CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                                         AS LegalMonetaryTotal_PayableAmount__CurrencyID
            FROM
                proddta.f03B11 AR_Detail
                LEFT JOIN proddta.f0014 f0014
                    ON AR_Detail.rpptc = f0014.pnptc
                LEFT JOIN
                (
                    SELECT
                         f0101.aban8
                        ,f0101.abeftb
                        ,f0101.abtax
                        ,f0116.alan8
                        ,f0116.aleftb
                        ,f0116.aladd1
                        ,f0116.aladd2
                        ,f0116.aladd3
                        ,f0116.aladd4
                        ,f0116.alcty1
                        ,f0116.aladdz
                        ,f0116.alcoun
                        ,f0116.alctr
                        ,f0111.wwan8
                        ,f0111.wwidln
                        ,f0111.wwmlnm
                    FROM
                        proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111 f0111
                            ON  f0101.aban8     = f0111.wwan8
                            AND f0111.wwidln    = 0
                ) Seller_Detail
                    ON Seller_Detail.aban8 = AR_Detail.rpkco
                LEFT JOIN
                (
                    SELECT
                         f0101.aban8
                        ,f0101.abeftb
                        ,f0101.abtax
                        ,f0116.alan8
                        ,f0116.aleftb
                        ,f0116.aladd1
                        ,f0116.aladd2
                        ,f0116.aladd3
                        ,f0116.aladd4
                        ,f0116.alcty1
                        ,f0116.aladdz
                        ,f0116.alcoun
                        ,f0116.alctr
                        ,f0111.wwan8
                        ,f0111.wwidln
                        ,f0111.wwmlnm
                    FROM
                        proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111 f0111
                            ON f0101.aban8      = f0111.wwan8
                            AND f0111.wwidln    = 0
                ) Buyer_Detail
                    ON Buyer_Detail.aban8 = AR_Detail.rppyr
                INNER JOIN
                (
                    SELECT
                         f4211.sddct
                        ,f4211.sddoco
                        ,f4211.sddcto
                        ,f4211.sdkcoo
                        ,f4211.sddoc
                        ,f4211.sdlnid
                        ,f4211.sditm
                        ,f4211.sdshan
                        ,f4211.sdlttr
                        ,f4211.sdnxtr
                        ,f4211.sdcrcd
                        ,f4211.sduprc
                        ,f4211.sdfup
                        ,f4211.sddsc2
                        ,f4211.sddsc1
                        ,f4211.sdaexp
                        ,f4211.sdfea
                        ,f4211.sduom
                        ,f4211.sduorg
                        ,f4211.sdokc
                        ,f4211.sdodct
                        ,f4211.sdodoc
                        ,f4211.sdvr02
                        ,f4211.sdlitm
                    FROM
                        proddta.f4211 f4211
                    UNION ALL
                    SELECT
                         f42119.sddct
                        ,f42119.sddoco
                        ,f42119.sddcto
                        ,f42119.sdkcoo
                        ,f42119.sddoc
                        ,f42119.sdlnid
                        ,f42119.sditm
                        ,f42119.sdshan
                        ,f42119.sdlttr
                        ,f42119.sdnxtr
                        ,f42119.sdcrcd
                        ,f42119.sduprc
                        ,f42119.sdfup
                        ,f42119.sddsc2
                        ,f42119.sddsc1
                        ,f42119.sdaexp
                        ,f42119.sdfea
                        ,f42119.sduom
                        ,f42119.sduorg
                        ,f42119.sdokc
                        ,f42119.sdodct
                        ,f42119.sdodoc
                        ,f42119.sdvr02
                        ,f42119.sdlitm
                    FROM
                        proddta.f42119 f42119
                ) SO_Detail
                    ON  AR_Detail.rpdct     = SO_Detail.sddct
                    AND AR_Detail.rpsdoc    = SO_Detail.sddoco
                    AND AR_Detail.rpsdct    = SO_Detail.sddcto
                    AND AR_Detail.rpskco    = SO_Detail.sdkcoo
                    AND AR_Detail.rpdoc     = SO_Detail.sddoc
                LEFT JOIN proddta.f4201 SO_Header
                    ON  SO_Detail.sddoco = SO_Header.shdoco
                    AND SO_Detail.sddcto = SO_Header.shdcto
                    AND SO_Detail.sdkcoo = SO_Header.shkcoo
                LEFT JOIN
                (
                    SELECT
                         f4008.taefdj
                        ,f4008.tata1
                        ,f4008.tatxa1
                        ,f4008.tatxr1
                    FROM
                        proddta.f4008 f4008
                    WHERE
                        TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 <= f4008.taefdj
                        AND TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 >= f4008.taeftj
                        AND f4008.tata1 = 1010303
                ) Tax_Rate
                    ON Tax_Rate.tatxa1 = AR_Detail.rptxa1
                LEFT JOIN proddta.f4101 f4101
                        ON f4101.imitm = SO_Detail.sditm
                LEFT JOIN
                (
                    SELECT
                         f0101.aban8
                        ,f0101.abeftb
                        ,f0101.abtax
                        ,f0116.alan8
                        ,f0116.aleftb
                        ,f0116.aladd1
                        ,f0116.aladd2
                        ,f0116.aladd3
                        ,f0116.aladd4
                        ,f0116.alcty1
                        ,f0116.aladdz
                        ,f0116.alcoun
                        ,f0116.alctr
                        ,f0111.wwan8
                        ,f0111.wwidln
                        ,f0111.wwmlnm
                    FROM
                        proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111
                            ON  f0101.aban8     = f0111.wwan8
                            AND f0111.wwidln    = 0
                ) Shipper_Detail
                    ON Shipper_Detail.aban8 = SO_Detail.sdshan
                LEFT JOIN proddta.f4006 DeliverDetail
                    ON  SO_Detail.sddoco = DeliverDetail.oadoco
                    AND SO_Detail.sddcto = DeliverDetail.oadcto
                    AND SO_Detail.sdkcoo = DeliverDetail.oakcoo
                    AND DeliverDetail.oaanty= '2'
                LEFT JOIN proddta.f03b11 PrecedingInvoice
                    ON  PrecedingInvoice.rpdoc = SO_Detail.sdodoc
                    AND PrecedingInvoice.rpdct = SO_Detail.sdodct
                    AND PrecedingInvoice.rpkco = SO_Detail.sdokc
                INNER JOIN proddta.f550301d f550301d
                    ON  f550301d.eddoc  = AR_Detail.rpdoc
                    AND f550301d.eddct  = AR_Detail.rpdct
                    AND f550301d.edkco  = AR_Detail.rpkco
                    AND f550301d.edsfx  = AR_Detail.rpsfx
                    AND f550301d.eddoco = SO_Detail.sddoco
                    AND f550301d.eddcto = SO_Detail.sddcto
                    AND f550301d.edkcoo = SO_Detail.sdkcoo
                    AND f550301d.edlnid = SO_Detail.sdlnid
                INNER JOIN proddta.f550301h f550301h
                    ON f550301h.ehdl01 = f550301d.eddl01
            WHERE
                AR_Detail.rpkco IN ('00047','00113')
                AND AR_Detail.rppyr NOT IN (30601299, 37816288, 30630723)
                -- This is to filter either records with sales update or records without SO
                AND
                (
                    (
                        SO_Detail.sdlttr != '980'
                        AND SO_Detail.sdnxtr = '999'
                    )
                    OR
                    (
                        SO_Detail.sdlttr IS NULL
                        AND SO_Detail.sdnxtr IS NULL
                    )
                )
                AND AR_Detail.rpdct     IN ('RM')
                AND
                (
                    Buyer_Detail.alctr  = 'RO'
                    OR Buyer_Detail.ABTAX LIKE ('RO%')
                )
                AND f550301h.ehev01 = 'C'
                AND f550301h.ehev02 = 'R'
                AND
                (
                    f550301h.ehedsp = 'N'
                    OR
                    (
                        ehedsp IN ('I', 'P')
                        AND
                        (
                            24 *
                            (
                                SYSDATE
                                -
                                TO_DATE
                                (
                                    TO_CHAR(TO_DATE(TO_CHAR(f550301h.ehupmj+1900000),'YYYYDDD'),'yyyy-mm-dd')
                                    || ' ' || LPAD(TO_CHAR(f550301h.ehupmt), 6, '0' ),
                                    'yyyy-mm-dd hh24miss'
                                )
                            )
                            >= 24
                        )
                    )
                )
            FETCH FIRST 10 ROWS ONLY;

        CURSOR c_detail IS
            SELECT
                TRIM(f550301d.edtaskid)                                     AS DetailTaskID
                ,CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                    THEN
                        TO_CHAR(SO_Detail.sdlnid/1000)
                    ELSE
                        TRIM(AR_Detail.rpsfx)
                END                                                         AS CreditNoteLine_ID
                ,ABS(CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                    THEN
                        SO_Detail.sduorg
                    WHEN
                        AR_Detail.rpu IS NULL
                        OR AR_Detail.rpu = 0
                    THEN
                        1
                    ELSE
                        AR_Detail.rpu
                END)                                                         AS CreditNoteLine_InvoiceQuantity
                ,CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Detail.sduom = 'KG'
                    THEN
                        'KGM'
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Detail.sduom = 'MM'
                    THEN
                        'MMT'
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Detail.sduom NOT IN ('KG','MM')
                        AND TRIM(SO_Detail.sduom) IS NOT NULL
                    THEN
                        TRIM(SO_Detail.sduom)
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND TRIM(SO_Detail.sduom) IS NULL
                    THEN
                        'EA'
                    WHEN
                        TRIM(AR_Detail.rpum) IS NULL
                    THEN
                        'EA'
                    ELSE
                        TRIM(AR_Detail.rpum)
                END                                                         AS CreditNoteLine_InvoiceQuantity__UnitCode
                ,ABS(CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Detail.sdfea  <> 0
                    THEN
                        SO_Detail.sdfea * .01
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Detail.sdfea = 0
                    THEN
                        SO_Detail.sdaexp * .01
                    WHEN
                        (
                            SO_Detail.sdlnid = 0
                            OR SO_Detail.sdlnid IS NULL
                        )
                        AND AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpctxa * .01
                    ELSE
                        AR_Detail.rpatxa * .01
                END)                                                         AS CreditNoteLine_LineExtentionAmount
                ,CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                    THEN
                        TRIM(SO_Detail.sdcrcd)
                    WHEN
                        (
                            SO_Detail.sdlnid = 0
                            OR SO_Detail.sdlnid IS NULL
                        )
                        AND AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                         AS CreditNoteLine_LineExtentionAmount__CurrencyID
                ,TRIM(SO_Detail.sdvr02)                                     AS CreditNoteLine_OrderLineRef_LineID
                ,CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                    THEN
                        TRIM(SO_Detail.sddsc1) || ' '
                        || TRIM(SO_Detail.sddsc2)
                    WHEN
                        (
                            SO_Detail.sdlnid = 0
                            OR SO_Detail.sdlnid IS NULL
                        )
                    THEN
                        TRIM(AR_Detail.rprmk)
                END                                                         AS CreditNoteLine_Item_Name
                ,TRIM(f4101.imdraw)                                         AS CreditNoteLine_Item_BuyerItemID
                ,TRIM(SO_Detail.sdlitm)                                     AS CreditNoteLine_Item_SellerItemID
                ,TRIM(Seller_Detail.alctr)                                  AS CreditNoteLine_Item_OriginCountryCode
                ,CASE
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS03', 'ROS10','ROS03A')
                    THEN
                        'AE'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS09', 'ROS08E')
                    THEN
                        'E'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS11')
                    THEN
                        'O'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS05', 'ROS06')
                    THEN
                        'G'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS07', 'ROS12')
                    THEN
                        'IC'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS08T')
                    THEN
                        '151'
                    WHEN
                        TRIM(AR_Detail.rptxa1) IN ('ROS01', 'ROS02', 'ROS04','ROS01A','ROS02A')
                    THEN
                        'S'
                    ELSE
                        'S'
                END                                                         AS CreditNoteLine_Item_ClassifiedTaxCategory_ID
                ,Tax_Rate.tatxr1 * .001                                     AS CreditNoteLine_Item_ClassifiedTaxCategory_Percent
                ,'VAT'                                                      AS CreditNoteLine_Item_ClassifiedTaxCategory_TaxScheme_ID
                ,ABS(CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Detail.sdfup <> 0
                    THEN
                        SO_Detail.sdfup * .0001
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Detail.sdfup = 0
                    THEN
                        SO_Detail.sduprc * .0001
                    WHEN
                        (
                            SO_Detail.sdlnid = 0
                            OR SO_Detail.sdlnid IS NULL
                        )
                        AND AR_Detail.rpcrrm = 'F'
                    THEN
                        AR_Detail.rpctxn * .01
                    ELSE
                        AR_Detail.rpatxa * .01
                END)                                                         AS CreditNoteLine_Price_PriceAmount
                ,CASE
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Header.shcrrm = 'F'
                    THEN
                        TRIM(SO_Detail.sdcrcd)
                    WHEN
                        SO_Detail.sdlnid > 0
                        AND SO_Header.shcrrm != 'F'
                    THEN
                        TRIM(SO_Detail.sdcrcd)
                    WHEN
                        (
                            SO_Detail.sdlnid = 0
                            OR SO_Detail.sdlnid IS NULL
                        )
                        AND AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                END                                                         AS CreditNoteLine_Price_PriceAmount__CurrencyID
            FROM
                proddta.f03B11 AR_Detail
                LEFT JOIN proddta.f0014 f0014
                    ON AR_Detail.rpptc = f0014.pnptc
                LEFT JOIN
                (
                    SELECT
                         f0101.aban8
                        ,f0101.abeftb
                        ,f0101.abtax
                        ,f0116.alan8
                        ,f0116.aleftb
                        ,f0116.aladd1
                        ,f0116.aladd2
                        ,f0116.aladd3
                        ,f0116.aladd4
                        ,f0116.alcty1
                        ,f0116.aladdz
                        ,f0116.alcoun
                        ,f0116.alctr
                        ,f0111.wwan8
                        ,f0111.wwidln
                        ,f0111.wwmlnm
                    FROM
                        proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111 f0111
                            ON  f0101.aban8     = f0111.wwan8
                            AND f0111.wwidln    = 0
                ) Seller_Detail
                    ON Seller_Detail.aban8 = AR_Detail.rpkco
                LEFT JOIN
                (
                    SELECT
                         f0101.aban8
                        ,f0101.abeftb
                        ,f0101.abtax
                        ,f0116.alan8
                        ,f0116.aleftb
                        ,f0116.aladd1
                        ,f0116.aladd2
                        ,f0116.aladd3
                        ,f0116.aladd4
                        ,f0116.alcty1
                        ,f0116.aladdz
                        ,f0116.alcoun
                        ,f0116.alctr
                        ,f0111.wwan8
                        ,f0111.wwidln
                        ,f0111.wwmlnm
                    FROM
                        proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111 f0111
                            ON f0101.aban8      = f0111.wwan8
                            AND f0111.wwidln    = 0
                ) Buyer_Detail
                    ON Buyer_Detail.aban8 = AR_Detail.rppyr
                INNER JOIN
                (
                    SELECT
                         f4211.sddct
                        ,f4211.sddoco
                        ,f4211.sddcto
                        ,f4211.sdkcoo
                        ,f4211.sddoc
                        ,f4211.sdlnid
                        ,f4211.sditm
                        ,f4211.sdshan
                        ,f4211.sdlttr
                        ,f4211.sdnxtr
                        ,f4211.sdcrcd
                        ,f4211.sduprc
                        ,f4211.sdfup
                        ,f4211.sddsc2
                        ,f4211.sddsc1
                        ,f4211.sdaexp
                        ,f4211.sdfea
                        ,f4211.sduom
                        ,f4211.sduorg
                        ,f4211.sdokc
                        ,f4211.sdodct
                        ,f4211.sdodoc
                        ,f4211.sdvr02
                        ,f4211.sdlitm
                    FROM
                        proddta.f4211 f4211
                    UNION ALL
                    SELECT
                         f42119.sddct
                        ,f42119.sddoco
                        ,f42119.sddcto
                        ,f42119.sdkcoo
                        ,f42119.sddoc
                        ,f42119.sdlnid
                        ,f42119.sditm
                        ,f42119.sdshan
                        ,f42119.sdlttr
                        ,f42119.sdnxtr
                        ,f42119.sdcrcd
                        ,f42119.sduprc
                        ,f42119.sdfup
                        ,f42119.sddsc2
                        ,f42119.sddsc1
                        ,f42119.sdaexp
                        ,f42119.sdfea
                        ,f42119.sduom
                        ,f42119.sduorg
                        ,f42119.sdokc
                        ,f42119.sdodct
                        ,f42119.sdodoc
                        ,f42119.sdvr02
                        ,f42119.sdlitm
                    FROM
                        proddta.f42119 f42119
                ) SO_Detail
                    ON  AR_Detail.rpdct     = SO_Detail.sddct
                    AND AR_Detail.rpsdoc    = SO_Detail.sddoco
                    AND AR_Detail.rpsdct    = SO_Detail.sddcto
                    AND AR_Detail.rpskco    = SO_Detail.sdkcoo
                    AND AR_Detail.rpdoc     = SO_Detail.sddoc
                LEFT JOIN proddta.f4201 SO_Header
                    ON  SO_Detail.sddoco = SO_Header.shdoco
                    AND SO_Detail.sddcto = SO_Header.shdcto
                    AND SO_Detail.sdkcoo = SO_Header.shkcoo
                LEFT JOIN
                (
                    SELECT
                         f4008.taefdj
                        ,f4008.tata1
                        ,f4008.tatxa1
                        ,f4008.tatxr1
                    FROM
                        proddta.f4008 f4008
                    WHERE
                        TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 <= f4008.taefdj
                        AND TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 >= f4008.taeftj
                        AND f4008.tata1 = 1010303
                ) Tax_Rate
                    ON Tax_Rate.tatxa1 = AR_Detail.rptxa1
                LEFT JOIN proddta.f4101 f4101
                        ON f4101.imitm = SO_Detail.sditm
                LEFT JOIN
                (
                    SELECT
                         f0101.aban8
                        ,f0101.abeftb
                        ,f0101.abtax
                        ,f0116.alan8
                        ,f0116.aleftb
                        ,f0116.aladd1
                        ,f0116.aladd2
                        ,f0116.aladd3
                        ,f0116.aladd4
                        ,f0116.alcty1
                        ,f0116.aladdz
                        ,f0116.alcoun
                        ,f0116.alctr
                        ,f0111.wwan8
                        ,f0111.wwidln
                        ,f0111.wwmlnm
                    FROM
                        proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111
                            ON  f0101.aban8     = f0111.wwan8
                            AND f0111.wwidln    = 0
                ) Shipper_Detail
                    ON Shipper_Detail.aban8 = SO_Detail.sdshan
                LEFT JOIN proddta.f4006 DeliverDetail
                    ON  SO_Detail.sddoco = DeliverDetail.oadoco
                    AND SO_Detail.sddcto = DeliverDetail.oadcto
                    AND SO_Detail.sdkcoo = DeliverDetail.oakcoo
                    AND DeliverDetail.oaanty= '2'
                LEFT JOIN proddta.f03b11 PrecedingInvoice
                    ON  PrecedingInvoice.rpdoc = SO_Detail.sdodoc
                    AND PrecedingInvoice.rpdct = SO_Detail.sdodct
                    AND PrecedingInvoice.rpkco = SO_Detail.sdokc
                INNER JOIN proddta.f550301d f550301d
                    ON  f550301d.eddoc  = AR_Detail.rpdoc
                    AND f550301d.eddct  = AR_Detail.rpdct
                    AND f550301d.edkco  = AR_Detail.rpkco
                    AND f550301d.edsfx  = AR_Detail.rpsfx
                    AND f550301d.eddoco = SO_Detail.sddoco
                    AND f550301d.eddcto = SO_Detail.sddcto
                    AND f550301d.edkcoo = SO_Detail.sdkcoo
                    AND f550301d.edlnid = SO_Detail.sdlnid
                INNER JOIN proddta.f550301h f550301h
                    ON f550301h.ehdl01 = f550301d.eddl01
            WHERE
                AR_Detail.rpkco IN ('00047','00113')
                AND AR_Detail.rppyr NOT IN (30601299, 37816288, 30630723)
                -- This is to filter either records with sales update or records without SO
                AND
                (
                    (
                        SO_Detail.sdlttr != '980'
                        AND SO_Detail.sdnxtr = '999'
                    )
                    OR
                    (
                        SO_Detail.sdlttr IS NULL
                        AND SO_Detail.sdnxtr IS NULL
                    )
                )
                AND AR_Detail.rpdct     IN ('RM')
                AND
                (
                    Buyer_Detail.alctr = 'RO'
                    OR Buyer_Detail.ABTAX LIKE ('RO%')
                )
                AND AR_Detail.rpdoc = v_CreditNote_ID;



    BEGIN
        o_return_message    := 'SUCCESS';

        -- Create an empty XML document
        xml_domdoc      := dbms_xmldom.newDomDocument;

        -- Create a root node
        xml_root_node   := dbms_xmldom.makeNode(xml_domdoc);

        ------------------------------------------------------
        -- Get Audit Information
        ------------------------------------------------------
        SELECT
             UPPER(SUBSTR(SYS_CONTEXT('USERENV','HOST'), INSTR(SYS_CONTEXT('USERENV','HOST'), '\',1,1)+1,10))
            ,TO_NUMBER(TO_CHAR(SYSDATE,'yyyyddd')) - 1900000
            ,TO_NUMBER(TO_CHAR(SYSDATE,'hh24miss'))
        INTO
             v_jobn
            ,v_upmj
            ,v_upmt
        FROM
            dual;

        -----------------------------------------------------------
        -- Credit Notes Wrapper Node
        -----------------------------------------------------------
        xml_credit_notes_element                                := dbms_xmldom.createElement(xml_domdoc, 'ns0:CreditNotes');
        dbms_xmldom.setattribute(xml_credit_notes_element, 'xmlns:ns0', 'http://Plexus.Avalara.JDE_CreditNotes');

        xml_credit_notes_node                                    := dbms_xmldom.appendChild(xml_root_node, dbms_xmldom.makeNode(xml_credit_notes_element));

        OPEN c_header;

        LOOP

            FETCH
                c_header
            INTO
                 v_HeaderTaskID
                ,v_CustomizationID
                ,v_CreditNote_ID
                ,v_IssueDate
                ,v_DueDate
                ,v_InvoiceTypeCode
                ,v_DocumentCurrencyCode
                ,v_TaxCurrencyCode
                ,v_OrderReference_ID
                ,v_SalesOrder_ID
                ,v_InvoiceDocumentRef_ID
                ,v_InvoiceDocumentRef_IssueDate
                ,v_ASP_Party_PostalAddress_StreetName
                ,v_ASP_Party_PostalAddress_CityName
                ,v_ASP_Party_PostalAddress_PostalZone
                ,v_ASP_Party_PostalAddress_CountrySubentity
                ,v_ASP_Party_PostalAddress_Country_IdentificationCode
                ,v_ASP_Party_PartyTaxScheme_CompanyID
                ,v_ASP_Party_PartyTaxScheme_TaxScheme_ID
                ,v_ASP_Party_PartyLegalEntity_RegistrationName
                ,v_ASP_Party_PartyLegalEntity_CompanyID
                ,v_ACP_Party_PostalAddress_StreetName
                ,v_ACP_Party_PostalAddress_CityName
                ,v_ACP_Party_PostalAddress_PostalZone
                ,v_ACP_Party_PostalAddress_CountrySubentity
                ,v_ACP_Party_PostalAddress_Country_IdentificationCode
                ,v_ACP_Party_PartyTaxScheme_CompanyID
                ,v_ACP_Party_PartyTaxScheme_TaxScheme_ID
                ,v_ACP_Party_PartyLegalEntity_RegistrationName
                ,v_Delivery_DeliveryLocation_Address_StreetName
                ,v_Delivery_DeliveryLocation_Address_CityName
                ,v_Delivery_DeliveryLocation_Address_PostalZone
                ,v_Delivery_DeliveryLocation_Address_CountrySubentity
                ,v_Delivery_DeliveryLocation_Address_Country_IndentificationCode
                ,v_Delivery_DeliveryParty_PartyName_Name
                ,v_PaymentMeans_PaymentMeansCode
                ,v_PaymentTerms_Note
                ,v_TaxTotal_TaxAmount
                ,v_TaxTotal_TaxAmount__CurrencyID
                ,v_TaxTotal_TaxSubtotal_TaxableAmount
                ,v_TaxTotal_TaxSubtotal_TaxableAmount__CurrencyID
                ,v_TaxTotal_TaxSubtotal_TaxAmount
                ,v_TaxTotal_TaxSubtotal_TaxAmount__CurrencyID
                ,v_TaxTotal_TaxSubtotal_TaxCategory_ID
                ,v_TaxTotal_TaxSubtotal_TaxCategory_Percent
                ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonCode
                ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReasonText
                ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID
                ,v_TaxTotal_TaxAmount__Local
                ,v_TaxTotal_TaxAmount__Local__CurrencyID
                ,v_LegalMonetaryTotal_LineExtensionAmount
                ,v_LegalMonetaryTotal_LineExtensionAmount__CurrencyID
                ,v_LegalMonetaryTotal_TaxExclusiveAmount
                ,v_LegalMonetaryTotal_TaxExclusiveAmount__CurrencyID
                ,v_LegalMonetaryTotal_TaxInclusiveAmount
                ,v_LegalMonetaryTotal_TaxInclusiveAmount__CurrencyID
                ,v_LegalMonetaryTotal_PayableAmount
                ,v_LegalMonetaryTotal_PayableAmount__CurrencyID;

                EXIT WHEN c_header%NOTFOUND;

                v_records_found := TRUE;


                UPDATE
                    proddta.f550301h f550301h
                SET
                     f550301h.ehedsp = 'I'
                    ,f550301h.ehpid  = v_pid
                    ,f550301h.ehjobn = v_jobn
                    ,f550301h.ehuser = v_user
                    ,f550301h.ehupmj = v_upmj
                    ,f550301h.ehupmt = v_upmt
                WHERE
                    TRIM(f550301h.ehtaskID) = TRIM(v_HeaderTaskID);

                COMMIT;

                -----------------------------------------------------------
                -- Credit Notes
                -----------------------------------------------------------
                xml_credit_note_element                                 := dbms_xmldom.createElement(xml_domdoc, 'CreditNote');
                dbms_xmldom.setattribute(xml_credit_note_element, 'xmlns:cac', 'urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2');
                dbms_xmldom.setattribute(xml_credit_note_element, 'xmlns:cbc', 'urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2');
                dbms_xmldom.setattribute(xml_credit_note_element, 'xmlns', 'urn:oasis:names:specification:ubl:schema:xsd:CreditNote-2_JDE');

                xml_credit_note_node                                    := dbms_xmldom.appendChild(xml_credit_notes_node, dbms_xmldom.makeNode(xml_credit_note_element));

                xml_header_id_node                                      := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'JDEHeaderID')));
                xml_header_id_text_node                                 := dbms_xmldom.appendChild(xml_header_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_HeaderTaskID)));

                xml_customization_id_node                               := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CustomizationID')));
                xml_customization_id_text_node                          := dbms_xmldom.appendChild(xml_customization_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CustomizationID)));

                xml_id_node                                             := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                xml_id_text_node                                        := dbms_xmldom.appendChild(xml_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNote_ID)));

                xml_issue_date_node                                     := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IssueDate')));
                xml_issue_date_text_node                                := dbms_xmldom.appendChild(xml_issue_date_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_IssueDate)));

                xml_credit_note_type_code_node                          := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CreditNoteTypeCode')));
                xml_credit_note_type_code_text_node                     := dbms_xmldom.appendChild(xml_credit_note_type_code_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceTypeCode)));

                xml_document_currency_code_node                         := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:DocumentCurrencyCode')));
                xml_document_currency_code_text_node                    := dbms_xmldom.appendChild(xml_document_currency_code_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_DocumentCurrencyCode)));

                -- Remove node completely if value is blank
                IF TRIM(v_TaxCurrencyCode) IS NOT NULL THEN

                    xml_tax_currency_code_node                              := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxCurrencyCode')));
                    xml_tax_currency_code_text_node                         := dbms_xmldom.appendChild(xml_tax_currency_code_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxCurrencyCode)));
                END IF;

                -----------------------------------------------------------
                -- Order Reference
                -----------------------------------------------------------
                -- If both Order Reference ID and Sales Order ID are not populated
                -- then do not include the wrapper Order Reference node either

                IF
                    TRIM(v_OrderReference_ID) IS NULL
                    AND
                    (
                        v_SalesOrder_ID = 0
                        OR v_SalesOrder_ID IS NULL
                    )
                THEN
                    -- No value for Order Reference ID and Sales Order ID - Do nothing
                    NULL;
                ELSE
                    -- Create wrapper Order Reference node
                    xml_order_reference_node                                := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:OrderReference')));

                    -- If we are in this section, at least one of the two nodes below will have a value

                    -- Do not display node if value is blank/null
                    IF TRIM(v_OrderReference_ID) IS NOT NULL THEN

                        xml_order_reference_id_node                             := dbms_xmldom.appendChild(xml_order_reference_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                        xml_order_reference_id_text_node                        := dbms_xmldom.appendChild(xml_order_reference_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_OrderReference_ID)));
                    END IF;


                    -- Do not display node if value is zero/null
                    IF
                        v_SalesOrder_ID <> 0
                        AND v_SalesOrder_ID IS NOT NULL
                    THEN
                        xml_sales_order_id_node                                 := dbms_xmldom.appendChild(xml_order_reference_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:SalesOrderID')));
                        xml_sales_order_id_text_node                            := dbms_xmldom.appendChild(xml_sales_order_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_SalesOrder_ID)));
                    END IF;

                END IF;

                -----------------------------------------------------------
                -- Billing Reference
                -----------------------------------------------------------
                xml_billing_ref_node                                    := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:BillingReference')));

                xml_invoice_doc_ref_node                                := dbms_xmldom.appendChild(xml_billing_ref_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:InvoiceDocumentReference')));

                xml_invoice_doc_ref_id_node                             := dbms_xmldom.appendChild(xml_invoice_doc_ref_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                xml_invoice_doc_ref_id_text_node                        := dbms_xmldom.appendChild(xml_invoice_doc_ref_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceDocumentRef_ID)));

                xml_invoice_doc_ref_issue_date_node                     := dbms_xmldom.appendChild(xml_invoice_doc_ref_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IssueDate')));
                xml_invoice_doc_ref_issue_date_text_node                := dbms_xmldom.appendChild(xml_invoice_doc_ref_issue_date_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceDocumentRef_IssueDate)));

                -----------------------------------------------------------
                -- Accounting Supplier Party
                -----------------------------------------------------------
                xml_asp_node                                            := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:AccountingSupplierParty')));

                -----------------------------------------------------------
                -- Party
                -----------------------------------------------------------
                xml_asp_party_node                                      := dbms_xmldom.appendChild(xml_asp_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Party')));

                -----------------------------------------------------------
                -- Postal Address
                -----------------------------------------------------------
                xml_asp_postal_address_node                             := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PostalAddress')));

                xml_asp_street_name_node                                := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:StreetName')));
                xml_asp_street_name_text_node                           := dbms_xmldom.appendChild(xml_asp_street_name_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_StreetName)));

                xml_asp_city_name_node                                  := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CityName')));
                xml_asp_city_name_text_node                             := dbms_xmldom.appendChild(xml_asp_city_name_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_CityName)));

                -- Do not display node if value is blank/null
                IF TRIM(v_ASP_Party_PostalAddress_PostalZone) IS NOT NULL THEN

                    xml_asp_postal_zone_node                            := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:PostalZone')));
                    xml_asp_postal_zone_text_node                       := dbms_xmldom.appendChild(xml_asp_postal_zone_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_PostalZone)));
                END IF;

                -- Do not display node if value is blank/null
                IF TRIM(v_ASP_Party_PostalAddress_CountrySubentity) IS NOT NULL THEN

                xml_asp_country_subentity_node                          := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CountrySubentity')));
                xml_asp_country_subentity_text_node                     := dbms_xmldom.appendChild(xml_asp_country_subentity_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_CountrySubentity)));

                END IF;

                -----------------------------------------------------------
                -- Country
                -----------------------------------------------------------
                xml_asp_country_node                                    := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Country')));

                xml_asp_identification_code_node                        := dbms_xmldom.appendChild(xml_asp_country_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IdentificationCode')));
                xml_asp_identification_code_text_node                   := dbms_xmldom.appendChild(xml_asp_identification_code_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_Country_IdentificationCode)));

                -----------------------------------------------------------
                -- Party Tax Scheme
                -----------------------------------------------------------
                xml_asp_party_tax_scheme_node                           := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PartyTaxScheme')));

                xml_asp_company_id_node                                 := dbms_xmldom.appendChild(xml_asp_party_tax_scheme_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CompanyID')));
                xml_asp_company_id_text_node                            := dbms_xmldom.appendChild(xml_asp_company_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyTaxScheme_CompanyID)));

                -----------------------------------------------------------
                -- Tax Scheme
                -----------------------------------------------------------
                xml_asp_tax_scheme_node                                 := dbms_xmldom.appendChild(xml_asp_party_tax_scheme_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxScheme')));

                xml_asp_tax_scheme_id_node                              := dbms_xmldom.appendChild(xml_asp_tax_scheme_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                xml_asp_tax_scheme_id_text_node                         := dbms_xmldom.appendChild(xml_asp_tax_scheme_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyTaxScheme_TaxScheme_ID)));

                -----------------------------------------------------------
                -- Party Legal Entity
                -----------------------------------------------------------
                xml_asp_party_legal_entity_node                         := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PartyLegalEntity')));

                xml_asp_registration_name_node                          := dbms_xmldom.appendChild(xml_asp_party_legal_entity_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:RegistrationName')));
                xml_asp_registration_name_text_node                     := dbms_xmldom.appendChild(xml_asp_registration_name_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyLegalEntity_RegistrationName)));

                xml_asp_legal_company_id_node                           := dbms_xmldom.appendChild(xml_asp_party_legal_entity_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CompanyID')));
                xml_asp_legal_company_id_text_node                      := dbms_xmldom.appendChild(xml_asp_legal_company_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyLegalEntity_CompanyID)));

                -----------------------------------------------------------
