                        ,v_CreditNoteLine_Item_BuyerItemId
                        ,v_CreditNoteLine_Item_SellerItemId
                        ,v_CreditNoteLine_Item_OriginCountryCode
                        ,v_CreditNoteLine_Item_ClassifiedTaxCategory_ID
                        ,v_CreditNoteLine_Item_ClassifiedTaxCategory_Percent
                        ,v_CreditNoteLine_Item_ClassifiedTaxCategory_TaxScheme_ID
                        ,v_CreditNoteLine_Price_PriceAmount
                        ,v_CreditNoteLine_Price_PriceAmount__CurrencyID;

                    EXIT WHEN c_detail%NOTFOUND;

                    -----------------------------------------------------------
                    -- Credit Note Line
                    -----------------------------------------------------------
                    xml_creditnote_line_node                            := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:CreditNoteLine')));

                    xml_cn_line_id_node                                 := dbms_xmldom.appendChild(xml_creditnote_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_cn_line_id_text_node                            := dbms_xmldom.appendChild(xml_cn_line_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_ID)));

                    xml_cn_line_inv_qty_element                         := dbms_xmldom.createElement(xml_domdoc, 'cbc:CreditedQuantity');
                    dbms_xmldom.setAttribute(xml_cn_line_inv_qty_element, 'unitCode', v_CreditNoteLine_CreditedQuantity__UnitCode);

                    xml_cn_line_inv_qty_node                            := dbms_xmldom.appendChild(xml_creditnote_line_node,
                                                                            dbms_xmldom.makeNode(xml_cn_line_inv_qty_element));
                    xml_cn_line_inv_qty_text_node                       := dbms_xmldom.appendChild(xml_cn_line_inv_qty_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_CreditedQuantity)));

                    xml_cn_line_line_ext_amt_element                    := dbms_xmldom.createElement(xml_domdoc, 'cbc:LineExtensionAmount');
                    dbms_xmldom.setAttribute(xml_cn_line_line_ext_amt_element, 'currencyID', v_CreditNoteLine_LineExtentionAmount__CurrencyID);

                    xml_cn_line_line_ext_amt_node                       := dbms_xmldom.appendChild(xml_creditnote_line_node,
                                                                            dbms_xmldom.makeNode(xml_cn_line_line_ext_amt_element));
                    xml_cn_line_line_ext_amt_text_node                  := dbms_xmldom.appendChild(xml_cn_line_line_ext_amt_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_LineExtentionAmount)));

                    -----------------------------------------------------------
                    -- Order Line Reference
                    -----------------------------------------------------------
                    -- Do not display wrapper or LineID nodes if LineID is blank/null
                    IF TRIM(v_CreditNote_OrderLineRef_LineID) IS NOT NULL THEN

                        xml_cn_line_order_line_ref_node                  := dbms_xmldom.appendChild(xml_creditnote_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:OrderLineReference')));

                        xml_cn_line_order_line_ref_line_id_node          := dbms_xmldom.appendChild(xml_cn_line_order_line_ref_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:LineID')));
                        xml_cn_line_order_line_ref_line_id_text_node     := dbms_xmldom.appendChild(xml_cn_line_order_line_ref_line_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNote_OrderLineRef_LineID )));
                    END IF;

                    -----------------------------------------------------------
                    -- Item
                    -----------------------------------------------------------
                    xml_cn_line_item_node                               := dbms_xmldom.appendChild(xml_creditnote_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Item')));

                    xml_cn_line_item_name_node                          := dbms_xmldom.appendChild(xml_cn_line_item_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Name')));
                    xml_cn_line_item_name_text_node                     := dbms_xmldom.appendChild(xml_cn_line_item_name_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_Name)));

                    -- Do not display nodes if value is blank/null
                    IF TRIM(v_CreditNoteLine_Item_BuyerItemId) IS NOT NULL THEN

                        xml_cn_line_item_buyer_item_ident_node                 := dbms_xmldom.appendChild(xml_cn_line_item_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:BuyersItemIdentification')));

                        xml_cn_line_item_buyer_item_ident_id_node              := dbms_xmldom.appendChild(xml_cn_line_item_buyer_item_ident_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                        xml_cn_line_item_buyer_item_ident_id_text_node         := dbms_xmldom.appendChild(xml_cn_line_item_buyer_item_ident_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_BuyerItemId)));
                    END IF;

                    -- Do not display nodes if value is blank/null
                    IF TRIM(v_CreditNoteLine_Item_SellerItemId) IS NOT NULL THEN

                        xml_cn_line_item_seller_item_ident_node                := dbms_xmldom.appendChild(xml_cn_line_item_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:SellersItemIdentification')));

                        xml_cn_line_item_seller_item_ident_id_node             := dbms_xmldom.appendChild(xml_cn_line_item_seller_item_ident_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                        xml_cn_line_item_seller_item_ident_id_text_node        := dbms_xmldom.appendChild(xml_cn_line_item_seller_item_ident_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_SellerItemId)));
                    END IF;


--                    xml_cn_line_item_origin_country_node                   := dbms_xmldom.appendChild(xml_cn_line_item_node,
--                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:OriginCountry')));
--
--                    xml_cn_line_item_origin_country_code_node              := dbms_xmldom.appendChild(xml_cn_line_item_origin_country_node,
--                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IdentificationCode')));
--                    xml_cn_line_item_origin_country_code_text_node         := dbms_xmldom.appendChild(xml_cn_line_item_origin_country_code_node,
--                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_OriginCountryCode)));

                    -----------------------------------------------------------
                    -- Classified Tax Category
                    -----------------------------------------------------------
                    xml_cn_line_classified_tax_cat_node                 := dbms_xmldom.appendChild(xml_cn_line_item_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:ClassifiedTaxCategory')));

                    xml_cn_line_class_tax_cat_id_node                   := dbms_xmldom.appendChild(xml_cn_line_classified_tax_cat_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_cn_line_class_tax_cat_id_text_node              := dbms_xmldom.appendChild(xml_cn_line_class_tax_cat_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_ClassifiedTaxCategory_ID)));

                    xml_cn_line_class_tax_id_percent_node               := dbms_xmldom.appendChild(xml_cn_line_classified_tax_cat_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Percent')));
                    xml_cn_line_class_tax_id_percent_text_node          := dbms_xmldom.appendChild(xml_cn_line_class_tax_id_percent_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_ClassifiedTaxCategory_Percent)));

                    -----------------------------------------------------------
                    -- Credit Note Line Tax Scheme
                    -----------------------------------------------------------
                    xml_cn_line_tax_scheme_node                         := dbms_xmldom.appendChild(xml_cn_line_classified_tax_cat_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxScheme')));

                    xml_cn_line_tax_scheme_id_node                      := dbms_xmldom.appendChild(xml_cn_line_tax_scheme_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_cn_line_tax_scheme_id_text_node                 := dbms_xmldom.appendChild(xml_cn_line_tax_scheme_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_ClassifiedTaxCategory_TaxScheme_ID)));

                    -----------------------------------------------------------
                    -- Credit Note Line Price
                    -----------------------------------------------------------
                    xml_cn_line_price_node                              := dbms_xmldom.appendChild(xml_creditnote_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Price')));

                    xml_cn_line_price_amt_element                       := dbms_xmldom.createElement(xml_domdoc, 'cbc:PriceAmount');
                    dbms_xmldom.setAttribute(xml_cn_line_price_amt_element, 'currencyID', v_CreditNoteLine_Price_PriceAmount__CurrencyID);

                    xml_cn_line_price_amt_node                          := dbms_xmldom.appendChild(xml_cn_line_price_node,
                                                                            dbms_xmldom.makeNode(xml_cn_line_price_amt_element));
                    xml_cn_line_price_amt_text_node                     := dbms_xmldom.appendChild(xml_cn_line_price_amt_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Price_PriceAmount)));

                END LOOP;

                CLOSE c_detail;

            END LOOP;

            CLOSE c_header;

            xml_xmltype     := dbms_xmldom.getXmlType(xml_domdoc);
            dbms_xmldom.freeDocument(xml_domdoc);

            IF v_records_found = TRUE THEN

                o_xml_clob      := xml_xmltype.getClobVal;

            ELSE

                o_xml_clob      := TO_CLOB('No Data Found');

            END IF;

        EXCEPTION
            WHEN OTHERS THEN

                v_err_nbr := SQLCODE;
                v_err_msg := v_err_job_name || ' - '||SQLERRM;

                ------------------------------------------------------
                -- Rollback changes
                ------------------------------------------------------
                ROLLBACK;

                ------------------------------------------------------
                -- Insert record into PL/SQL logging table
                ------------------------------------------------------
                INSERT INTO
                    commobj.joberr
                    (
                        job_name,
                        err#,
                        err_msg,
                        TIMESTAMP
                    )
                    VALUES
                    (
                        v_err_job_name,
                        v_err_nbr,
                        v_err_msg,
                        SYSDATE
                    );

                COMMIT;

                o_return_message := 'FAILURE: ' || SQLERRM;

    END USP_RO_CREDIT_NOTE_XML_SELECT;



