        -----------------------------------------------------------
        -- Declare Cursor Variables
        -----------------------------------------------------------
         CURSOR c_driver IS
            SELECT
                 ehurab
                ,ehdl01
            FROM
                proddta.f550301h
            WHERE
                ehev01 = 'I'
                AND ehev02 = 'M'
                AND
                (
                    f550301h.ehedsp = 'N'
                    OR
                    (
                        ehedsp IN ('I', 'P')
                        AND
                        (
                            24 *
                            (
                                SYSDATE
                                -
                                TO_DATE
                                (
                                    TO_CHAR(TO_DATE(TO_CHAR(f550301h.ehupmj+1900000),'YYYYDDD'),'yyyy-mm-dd')
                                    || ' ' || LPAD(TO_CHAR(f550301h.ehupmt), 6, '0' ),
                                    'yyyy-mm-dd hh24miss'
                                )
                            )
                            >= 24
                        )
                    )
                )
            FETCH FIRST 10 ROWS ONLY;

        CURSOR c_detail IS
            SELECT
                TRIM(f550301h.ehtaskid)                                                     AS HeaderTaskID
                ,SO_Detail.sddoc                                                            AS Invoice_ID           -- 3 THIS MEETS MY APPENDIX 1 FIELD 20 REQUIREMENT
                ,NVL(TO_CHAR(sys_extract_utc(SYSTIMESTAMP), 'yyyy-mm-dd'),' ')              AS IssueDate             -- 5 THIS MEETS MY APPENDIX 1 FIELD 22 REQUIREMENT
                ,TO_CHAR(sys_extract_utc(SYSTIMESTAMP) - INTERVAL '1' MINUTE, 'HH24:MI:SS') || 'Z' AS IssueTime            -- 6 THIS MEETS MY APPENDIX 1 FIELD 22 REQUIREMENT
                ,NVL(TO_CHAR(TO_DATE(TO_CHAR(
                    AR_Detail.rpddj+1900000),
                    'YYYYDDD'),'yyyy-mm-dd'),' ')                                           AS DueDate              -- 7 THIS MEETS PEPPOL REQUIREMENT
                ,CASE
                    WHEN
                        AR_Detail.RPDCT = 'RI'
                    THEN
                        '01'
                    ELSE
                        '03'
                END                                                                         AS InvoiceTypeCode      -- 8 THIS MEETS MY APPENDIX 1 FIELD 19 REQUIREMENT
                ,(
                    SELECT
                        TRIM(DRDL01)
                    FROM
                        PRODCTL.F0005
                    WHERE
                        DRSY = '55'
                        AND DRRT = 'MV'
                        AND TRIM(DRKY) = '1'
                )                                                                           AS InvoiceTypeCode__ListVersionID                           -- THIS MEETS MY APPENDIX 1 FIELD 18 REQUIREMENT
                ,NVL(CASE
                    WHEN
                        AR_Detail.rpcrrm = 'F'
                    THEN
                        TRIM(AR_Detail.rpcrcd)
                    ELSE
                        TRIM(AR_Detail.rpbcrc)
                    END,' ')                                                                AS DocumentCurrencyCode                                 -- 11 THIS MEETS MY APPENDIX 1 FIELD 24 REQUIREMENT
                ,'MYR'                                                                      AS TaxCurrencyCode
                ,CASE
                    WHEN
                        AR_Detail.RPDCT = 'RL'
                    THEN
                        TRIM(TO_CHAR(SO_Detail.sdodoc))
                    ELSE
                        ' '
                END                                                                         AS BillingReference_InvoiceDocumentReference_ID         -- 20.1.1 THIS MEETS MY APPENDIX 1 FIELD 23 REQUIREMENT
                ,'NA'                                                                       AS BillingReference_InvoiceDocumentReference_UUID       -- 20.1.2 THIS MEETS MY APPENDIX 1 FIELD 23 REQUIREMENT
                ,'26109'                                                                    AS ASP_Party_IndustryClassificationCode                 -- 27.1.1.2 THIS MEETS MY APPENDIX 1 FIELD 8 REQUIREMENT
                ,'Manufacture of other components for electronic applications'              AS ASP_Party_IndustryClassificationCode__Name           -- 27.1.1.1.2 THIS MEETS MY APPENDIX 1 FIELD 9 REQUIREMENT
                ,'C5892425060'                                                              AS ASP_Party_PartyIdentification_ID1                    -- 27.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 3 REQUIREMENT -- THIS IS TIN, SUPPLIER REG NUMBER WILL REPEAT IN SAME NODE FORMAT. THESE ARE THE TWO FIELDS RIGHT BELOW WITH THE NAMES.
                ,'TIN'                                                                      AS ASP_Party_PartyIdentification_ID1__SchemeID          -- 27.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 3 REQUIREMENT -- THIS IS TIN, SUPPLIER REG NUMBER WILL REPEAT IN SAME NODE FORMAT. THESE ARE THE TWO FIELDS RIGHT BELOW WITH THE NAMES.
                ,'199601026784'                                                             AS ASP_Party_PartyIdentification_ID2                    -- 27.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT -- THIS IS SUPPLIER REG, SAME NODE REPEATED AS TIN ABOVE
                ,'BRN'                                                                      AS ASP_Party_PartyIdentification_ID2__SchemeID          -- 27.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT -- THIS IS SUPPLIER REG, SAME NODE REPEATED AS SST ABOVE
                ,'NA'                                                                       AS ASP_Party_PartyIdentification_ID3                    -- 27.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT -- THIS IS SUPPLIER REG, SAME NODE REPEATED AS SST ABOVE
                ,'SST'                                                                      AS ASP_Party_PartyIdentification_ID3__SchemeID          -- 27.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT -- THIS IS SUPPLIER REG, SAME NODE REPEATED AS SST ABOVE
                ,'PLEXUS MANUFACTURING SDN. BHD.'                                           AS ASP_PartyName_Name                                   -- 27.1.3.1 THIS MEETS MY APPENDIX 1 FIELD 1 REQUIREMENT -- CAN WE CHANGE OUR REGISTRANTION NAME TO THIS
                ,TRIM(
                    TRIM(Seller_Detail.aladd2)     || ' ' ||
                    TRIM(Seller_Detail.aladd3)  || ' ' ||
                    TRIM(Seller_Detail.aladd4)
                )                                                                           AS ASP_Party_PostalAddress_StreetName                               -- 27.1.4.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT -- NEED TO GET ZIP AND CITY OUT
                ,TRIM(Seller_Detail.aladd1)                                                 AS ASP_Party_PostalAddress_AdditionalStreetName                     -- 27.1.4.2 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,TRIM(Seller_Detail.alcty1)                                                 AS ASP_Party_PostalAddress_CityName                                 -- 27.1.4.6 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT -- NEED TO FORMAT AS WE HAVE PENANG HERE. NEEDS TO BE BAYAN LEPAS
                ,TRIM(Seller_Detail.aladdz)                                                 AS ASP_Party_PostalAddress_PostalZone                               -- 27.1.4.7 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,'07'                                                                       AS ASP_Party_PostalAddress_CountrySubentityCode                     -- 27.1.4.8 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT -- NEED TO SET UP UDC FOR COUNTRY SUBENTITY
                ,'MY'                                                                       AS ASP_Party_PostalAddress_Country_IdentificationCode               -- 27.1.4.10.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,'ISO3166-1'                                                                AS ASP_Party_PostalAddress_Country_IdentificationCode__ListID       -- 27.1.4.10.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT -- NEED TO SET UP UDC FOR COUNTRY
                ,'6'                                                                        AS ASP_Party_PostalAddress_Country_IdentificationCode__ListAgencyID -- 27.1.4.10.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,'PLEXUS MANUFACTURING SDN. BHD.'                                           AS ASP_Party_PartyLegalEntity_RegistrationName                      -- 27.1.6.1 THIS MEETS MY APPENDIX 1 FIELD 1 REQUIREMENT -- CAN WE CHANGE OUR REGISTRANTION NAME TO THIS
                ,'+6046321000'                                                              AS ASP_Party_Contact_Telephone                                      -- 27.1.7.2 THIS MEETS MY APPENDIX 1 FIELD 16 REQUIREMENT
                ,'ARINQUIRIES@PLEXUS.COM'                                                   AS ASP_Party_Contact_ElectronicMail                                 -- 27.1.7.3 THIS MEETS MY APPENDIX 1 FIELD 7 REQUIREMENT -- ADD TO ELECTRONIC EMAIL
                ,CASE
                    WHEN
                        TRIM(Buyer_Detail.abmcu) = '39'
                        AND TRIM(Buyer_Detail.alctr) = 'MY'
                        AND TRIM(Buyer_Detail.abtax) IS NOT NULL
                    THEN
                        TRIM(Buyer_Detail.abtax)
                    WHEN
                        TRIM(Buyer_Detail.abmcu) = '39'
                        AND TRIM(Buyer_Detail.alctr) = 'MY'
                        AND TRIM(Buyer_Detail.abtax) IS NULL
                    THEN
                        'MY BUYER - NEED TIN ENTERED'
                    ELSE
                        'EI00000000020'
                END                                                                         AS ACP_Party_PartyIdentification_ID1            -- 28.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 10 REQUIREMENT. THIS IS TIN AND TIN, SST, BUYER REG NUMBER WILL REPEAT SAME WAT WITHIN NODE. MANAGEMENT NEEDS TO CLEAN.
                ,'TIN'                                                                      AS ACP_Party_PartyIdentification_ID1__SchemeID  -- 28.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 10 REQUIREMENT THIS IS TIN AND TIN, SST, BUYER REG NUMBER WILL REPEAT SAME WAT WITHIN NODE. MANAGEMENT NEEDS TO CLEAN.
                ,CASE
                    WHEN
                        TRIM(Buyer_Detail.abmcu) = '39'
                        AND TRIM(Buyer_Detail.alctr) = 'MY'
                        AND TRIM(Buyer_Detail.wwslnm) IS NOT NULL
                    THEN
                        TRIM(Buyer_Detail.wwslnm)
                    WHEN
                        TRIM(Buyer_Detail.abmcu) = '39'
                        AND TRIM(Buyer_Detail.alctr) = 'MY'
                        AND TRIM(Buyer_Detail.wwslnm) IS NULL
                    THEN
                        'MY BUYER - NEED BRN ENTERED'
                    ELSE
                        'NA'
