                        ) * (Tax_Rate.tatxr1 * .001)
                 END                                                                        AS InvoiceLine_TaxTotal_TaxSubTotal_TaxAmount                                   -- 40.11.3.2 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 33
                ,'MYR'                                                                      AS InvoiceLine_TaxTotal_TaxSubTotal_TaxAmount__CurrencyID                       -- 40.11.3.2.1 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 33
                ,Tax_Rate.tatxr1 * .001                                                     AS InvoiceLine_TaxTotal_TaxSubTotal_Percent                                     -- 40.11.3.2.2 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 32
                ,'06'                                                                       AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_ID                              -- 40.11.3.3.1 THIS MEETS MY APPENDIX 1 FIELD 31 REQUIREMENT -- NEED TO MAP OUT IN CASE STATEMENT 01;Sales Tax /02;Service Tax /03;Tourism Tax /04;High-Value Goods Tax /05;Sales Tax on Low Value Goods /06;Not Applicable / E; Exempt from tax (in case of exempion only )
                ,'NA'                                                                       AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxExemptionReason              -- 40.11.3.3.6"
                ,'OTH'                                                                      AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID                    -- 40.11.3.3.7 THIS MEETS MY APPENDIX 1 FIELD 34 REQUIREMENT -- RETURN IF ONLY EXEMPT
                ,'UN/ECE 5153'                                                              AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeID          -- 40.11.3.3.7 THIS MEETS MY APPENDIX 1 FIELD 34 REQUIREMENT -- RETURN IF ONLY EXEMPT
                ,'6'                                                                        AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeAgencyID    -- 40.11.3.3.7 THIS MEETS MY APPENDIX 1 FIELD 34 REQUIREMENT -- RETURN IF ONLY EXEMPT
                ,CASE
                    WHEN
                        TRIM(SO_Detail.sdlitm) IS NULL
                    THEN
                        CONCAT(TRIM(SO_Detail.sddsc1), CONCAT(' ', TRIM(SO_Detail.sddsc2)))
                    ELSE
                        TRIM(SO_Detail.sdlitm)
                END                                                                         AS InvoiceLine_Item_Description                                                 -- 40.12.1 THIS MEETS MY APPENDIX 1 FIELD 29 REQUIREMENT
                ,'MY'                                                                       AS InvoiceLine_Item_OriginCountry_IdentificationCode                            -- 40.12.6.1 THIS MEETS MY APPENDIX 2 FIELD 5 REQUIREMENT
                ,'022'                                                                      AS InvoiceLine_Item_CommodityClassification_ItemClassificationCode              -- 40.12.7.1 THIS MEETS MY APPENDIX 1 FIELD 28 REQUIREMENT
                ,'CLASS'                                                                    AS InvoiceLine_Item_CommodityClassification_ItemClassificationCode__ListID      -- 40.12.7.1 THIS MEETS MY APPENDIX 1 FIELD 28 REQUIREMENT
                ,CASE
                    WHEN
                        SO_Header.shcrrm = 'F'
                    THEN
                        SO_Detail.sdfup * .0001
                    ELSE
                        SO_Detail.sduprc * .0001
                END                                                                         AS InvoiceLine_Price_PriceAmount                                                -- 40.13.1 THIS MEETS MY APPENDIX 1 FIELD 30 REQUIREMENT
                ,TRIM(SO_Detail.sdcrcd)                                                     AS InvoiceLine_Price_PriceAmount__CurrencyID                                    -- 40.13.1.1 THIS MEETS MY APPENDIX 1 FIELD 30 REQUIREMENT
                ,CASE
                    WHEN
                        SO_Header.shcrrm = 'F'
                    THEN
                        SO_Detail.sdfea * F42119_TRANS_CURRENCY.decimal_position
                    ELSE
                        SO_Detail.sdaexp * F42119_TRANS_CURRENCY.decimal_position
                END                                                                         AS InvoiceLine_ItemPriceExtension_Amount                                        -- 40.13.4.1 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 36
                ,TRIM(SO_Detail.sdcrcd)                                                     AS InvoiceLine_ItemPriceExtension_Amount__CurrencyID                            -- 40.13.4.2.1 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 36
            FROM (
                    SELECT
                         f4211.sddoc
                        ,f4211.sdodoc
                        ,f4211.sdlnid
                        ,f4211.sduorg
                        ,f4211.sduom
                        ,f4211.sdfea
                        ,f4211.sdaexp
                        ,f4211.sdcrcd
                        ,f4211.sdlitm
                        ,f4211.sddsc1
                        ,f4211.sddsc2
                        ,f4211.sdfup
                        ,f4211.sduprc
                        ,f4211.sddct
                        ,f4211.sdkco
                        ,f4211.sdtxa1
                        ,f4211.sddoco
                        ,f4211.sddcto
                        ,f4211.sdkcoo
                        ,f4211.sditm
                        ,f4211.sdlttr
                        ,f4211.sdnxtr
                        ,f4211.sdglc
                        ,f4211.sdlnty
                    FROM
                        PRODDTA.F4211
                    WHERE TRIM(sdglc) <> 'NS29'                                         -- To remove DO line types
                    UNION ALL
                    SELECT
                         f42119.sddoc
                        ,f42119.sdodoc
                        ,f42119.sdlnid
                        ,f42119.sduorg
                        ,f42119.sduom
                        ,f42119.sdfea
                        ,f42119.sdaexp
                        ,f42119.sdcrcd
                        ,f42119.sdlitm
                        ,f42119.sddsc1
                        ,f42119.sddsc2
                        ,f42119.sdfup
                        ,f42119.sduprc
                        ,f42119.sddct
                        ,f42119.sdkco
                        ,f42119.sdtxa1
                        ,f42119.sddoco
                        ,f42119.sddcto
                        ,f42119.sdkcoo
                        ,f42119.sditm
                        ,f42119.sdlttr
                        ,f42119.sdnxtr
                        ,f42119.sdglc
                        ,f42119.sdlnty
                    FROM PRODDTA.F42119
                    WHERE TRIM(sdglc) <> 'NS29'                                     -- To remove DO line types
                ) SO_Detail
                LEFT JOIN
                    (
                        SELECT
                            rpdoc
                            ,rpkco
                            ,rpdct
                            ,rpskco
                            ,rpsdct
                            ,rpsdoc
                            ,rpdgj
                            ,rppyr
                            ,rpptc
                            ,rpdivj
                            ,MAX(rpddj) AS rpddj
                            ,rpcrrm
                            ,rpcrcd
                            ,rpbcrc
                            ,rpan8
                            ,SUM(rpctam) AS rpctam
                            ,SUM(rpstam) AS rpstam
                            ,SUM(rpatxa) AS rpatxa
                            ,SUM(rpctxa) AS rpctxa
                            ,SUM(rpatxn) AS rpatxn
                            ,SUM(rpctxn) AS rpctxn
                            ,SUM(rpacr) AS rpacr
                            ,SUM(rpag) AS rpag
                        FROM PRODDTA.F03B11
                        GROUP BY
                            rpdoc
                            ,rpkco
                            ,rpdct
                            ,rpskco
                            ,rpsdct
                            ,rpsdoc
                            ,rpdgj
                            ,rpcrrm
                            ,rpcrcd
                            ,rpbcrc
                            ,rppyr
                            ,rpptc
                            ,rpdivj
                            ,rpddj
                            ,rpan8
                    ) AR_Detail
                        ON  AR_Detail.rpdct = SO_Detail.sddct
                        AND AR_Detail.rpkco = SO_Detail.sdkco
                        AND AR_Detail.rpdoc  = SO_Detail.sddoc
                LEFT JOIN
                    (
                        SELECT
                            *
                        FROM
                            proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111 f0111
                            ON  f0101.aban8     = f0111.wwan8
                            AND f0111.wwidln    = 0
                        LEFT JOIN proddta.f0115 f0115
                            ON  f0101.aban8     = f0115.wpan8
                            AND f0115.wpphtp    = '    '
                    ) Seller_Detail
                        ON Seller_Detail.aban8 = AR_Detail.rpkco
                INNER JOIN
                    (
                        SELECT
                            aban8
                            ,abat1
                            ,abmcu
                            ,abtax
                            ,abtx2
                            ,alctr
                            ,CASE
                                WHEN abat1 = 'IC ' AND alctr = 'MY '
                            THEN 'IC'
                                ELSE 'NIC'
                            END AS IC_FLAG
                            ,aladd1
                            ,aladd2
                            ,aladd3
                            ,aladd4
                            ,alcty1
                            ,aladds
                            ,aladdz
                            ,alcoun
                            ,wwslnm
                            ,wwmlnm
                            ,'+' || TRIM(REGEXP_REPLACE(wpph1,'[^[a-z,A-Z,0-9,.]]*','')) AS wpph1
                        FROM
                            proddta.f0101 f0101
                        INNER JOIN proddta.f0116 f0116
                            ON  f0101.aban8     = f0116.alan8
                            AND f0101.abeftb    = f0116.aleftb
                        INNER JOIN proddta.f0111 f0111
                            ON f0101.aban8      = f0111.wwan8
                            AND f0111.wwidln    = 0
                        LEFT JOIN
                            (
                                SELECT
                                    f0115.wpan8
                                    ,f0115.wpph1
                                FROM
                                    (
                                        SELECT
                                            wpan8
                                            ,wpph1
                                            ,RANK() OVER (PARTITION BY wpan8 ORDER BY wpidln,wprck7 DESC) AS rnk
                                        FROM
                                            PRODDTA.f0115
                                        WHERE
                                            TRIM(wpphtp) IS NULL
                                    ) f0115
                                WHERE f0115.rnk = 1
                            ) Buyer_Phone
                            ON Buyer_Phone.wpan8 = f0101.aban8
                    ) Buyer_Detail
                        ON Buyer_Detail.aban8 = AR_Detail.rpan8
                LEFT JOIN proddta.f0014 f0014
                    ON AR_Detail.rpptc = f0014.pnptc
--                LEFT JOIN
--                    (
--                        SELECT
--                            CXCRCD
--                            ,CXCRDC
--                            ,CXEFT AS START_DATE
--                            ,LAG(CXEFT,1)OVER(ORDER BY CXCRCD,CXCRDC,CXEFT DESC) AS END_DATE
--                            ,CXCRR
--                        FROM PRODDTA.F550015
--                        WHERE CXCRDC = 'MYR'
--                    ) currency_rate_f
--                        ON AR_Detail.rpcrcd = currency_rate_f.cxcrcd
--                        AND AR_Detail.rpdivj BETWEEN currency_rate_f.START_DATE AND currency_rate_f.END_DATE
--                        AND AR_Detail.rpcrrm = 'F'
--                LEFT JOIN
--                    (
--                        SELECT
--                            CXCRCD
--                            ,CXCRDC
--                            ,CXEFT AS START_DATE
--                            ,NVL(LAG(CXEFT-1,1)OVER(ORDER BY CXCRCD,CXCRDC,CXEFT DESC),(select TO_CHAR(SYSDATE,'YYYYDDD')-1900000 FROM dual)+1) AS END_DATE
--                            ,CXCRR
--                        FROM PRODDTA.F550015
--                        WHERE CXCRDC = 'MYR'
--                    ) currency_rate_d
--                        ON AR_Detail.rpbcrc = currency_rate_d.cxcrcd
--                        AND AR_Detail.rpdivj BETWEEN currency_rate_d.START_DATE AND currency_rate_d.END_DATE
--                        AND AR_Detail.rpcrrm = 'D'
                LEFT JOIN
                    (
                        SELECT
                            *
                        FROM
                            proddta.f4008 f4008
                        WHERE
                            TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 <= f4008.taefdj
                            AND TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 >= f4008.taeftj
                            AND f4008.tata1 = 11648878
                    ) Tax_Rate
                    ON Tax_Rate.tatxa1 = SO_Detail.sdtxa1
                LEFT JOIN proddta.f4201 SO_Header
                    ON  SO_Detail.sddoco = SO_Header.shdoco
                    AND SO_Detail.sddcto = SO_Header.shdcto
                    AND SO_Detail.sdkcoo = SO_Header.shkcoo
                LEFT JOIN proddta.f4101 f4101
                    ON f4101.imitm = SO_Detail.sditm
                LEFT JOIN
                    (
                        SELECT
                            CVCRCD
                            , CVCDEC
                            , CASE
                                WHEN CVCDEC = 0 THEN 1
                                WHEN CVCDEC = 1 THEN .1
                                WHEN CVCDEC = 2 THEN .01
                                WHEN CVCDEC = 3 THEN .001
                                WHEN CVCDEC = 4 THEN .0001
                                WHEN CVCDEC = 5 THEN .00001
                                WHEN CVCDEC = 6 THEN .000001
                                WHEN CVCDEC = 7 THEN .0000001
                                WHEN CVCDEC = 8 THEN .00000001
                                WHEN CVCDEC = 9 THEN .000000001
                                ELSE .01
                                END AS DECIMAL_POSITION
                        FROM PRODDTA.F0013
                    ) F03B11_FOREIGN_CURRENCY
                    ON AR_Detail.rpcrcd = F03B11_FOREIGN_CURRENCY.CVCRCD
                LEFT JOIN
                    (
                        SELECT
                            CVCRCD
                            , CVCDEC
                            , CASE
                                WHEN CVCDEC = 0 THEN 1
                                WHEN CVCDEC = 1 THEN .1
                                WHEN CVCDEC = 2 THEN .01
                                WHEN CVCDEC = 3 THEN .001
                                WHEN CVCDEC = 4 THEN .0001
                                WHEN CVCDEC = 5 THEN .00001
                                WHEN CVCDEC = 6 THEN .000001
                                WHEN CVCDEC = 7 THEN .0000001
                                WHEN CVCDEC = 8 THEN .00000001
                                WHEN CVCDEC = 9 THEN .000000001
                                ELSE .01
                                END AS DECIMAL_POSITION
                        FROM PRODDTA.F0013
                    ) F03B11_BASE_CURRENCY
                    ON AR_Detail.rpbcrc = F03B11_BASE_CURRENCY.CVCRCD
                LEFT JOIN
                    (
                        SELECT
                            CVCRCD
                            , CVCDEC
                            , CASE
                                WHEN CVCDEC = 0 THEN 1
                                WHEN CVCDEC = 1 THEN .1
                                WHEN CVCDEC = 2 THEN .01
                                WHEN CVCDEC = 3 THEN .001
                                WHEN CVCDEC = 4 THEN .0001
                                WHEN CVCDEC = 5 THEN .00001
                                WHEN CVCDEC = 6 THEN .000001
                                WHEN CVCDEC = 7 THEN .0000001
                                WHEN CVCDEC = 8 THEN .00000001
                                WHEN CVCDEC = 9 THEN .000000001
                                ELSE .01
                                END AS DECIMAL_POSITION
                        FROM PRODDTA.F0013
                    ) F42119_TRANS_CURRENCY
                    ON SO_DETAIL.sdcrcd = F42119_TRANS_CURRENCY.CVCRCD
                LEFT JOIN prodctl.f0005 UOM
                    ON TRIM(SO_Detail.sduom) = TRIM(UOM.drky)
                    AND UOM.drsy = '55'
                    AND UOM.drrt = 'UM'
                INNER JOIN proddta.f550301h f550301h
                    ON f550301h.ehurab = SO_Detail.sddoc
                INNER JOIN proddta.f550301d f550301d
                    ON  f550301d.eddoc  = AR_Detail.rpdoc
                    AND f550301d.eddct  = AR_Detail.rpdct
                    AND f550301d.edkco  = AR_Detail.rpkco
                    AND f550301d.eddoco = SO_Detail.sddoco
                    AND f550301d.eddcto = SO_Detail.sddcto
                    AND f550301d.edkcoo = SO_Detail.sdkcoo
                    AND f550301d.edlnid = SO_Detail.sdlnid
                    AND f550301d.eddl01 = f550301h.ehdl01
            WHERE
                AR_Detail.rpkco IN ('00037','00039','00048','00071','00083','00084','00092','00096')
                AND
                    (
                        (
                            SO_Detail.sdlttr != '980'
                            AND SO_Detail.sdnxtr = '999'
                        )
                        OR
                        (
                            SO_Detail.sdlttr IS NULL
                            AND SO_Detail.sdnxtr IS NULL
                        )
                    )
                AND AR_Detail.rpdct IN ('RI','RL')
                AND Buyer_Detail.IC_FLAG <> 'IC'
                AND AR_Detail.rpag <> 0
                AND f550301h.ehdl01 = v_driver_dl01
                AND f550301h.ehurab = v_driver_doc_number;

    BEGIN
        o_return_message    := 'SUCCESS';

        -- Create an empty XML document
        xml_domdoc      := dbms_xmldom.newDomDocument;

        -- Create a root node
        xml_root_node   := dbms_xmldom.makeNode(xml_domdoc);

        ------------------------------------------------------
        -- Get Audit Information
        ------------------------------------------------------
        SELECT
             UPPER(SUBSTR(SYS_CONTEXT('USERENV','HOST'), INSTR(SYS_CONTEXT('USERENV','HOST'), '\',1,1)+1,10))
            ,TO_NUMBER(TO_CHAR(SYSDATE,'yyyyddd')) - 1900000
            ,TO_NUMBER(TO_CHAR(SYSDATE,'hh24miss'))
        INTO
             v_jobn
            ,v_upmj
            ,v_upmt
        FROM
            dual;

        -----------------------------------------------------------
        -- Invoices Wrapper Node
        -----------------------------------------------------------
        xml_invoices_element                                     := dbms_xmldom.createElement(xml_domdoc, 'ns0:Invoices');
        dbms_xmldom.setattribute(xml_invoices_element, 'xmlns:ns0', 'http://Plexus.Avalara.JDE_Invoices');

        xml_invoices_node                                        := dbms_xmldom.appendChild(xml_root_node, dbms_xmldom.makeNode(xml_invoices_element));


        OPEN c_driver;

        LOOP

            FETCH
                c_driver
            INTO
                 v_driver_doc_number
                ,v_driver_dl01;

            EXIT WHEN c_driver%NOTFOUND;

            v_records_found := TRUE;

            -- Reset first record flag for this invoice
            v_is_first_record := TRUE;

            OPEN c_detail;

            LOOP

                FETCH
                    c_detail
                INTO
                     v_HeaderTaskID
                    ,v_Invoice_ID
                    ,v_IssueDate
                    ,v_IssueTime
                    ,v_DueDate
                    ,v_InvoiceTypeCode
                    ,v_InvoiceTypeCode__ListVersionId
                    ,v_DocumentCurrencyCode
                    ,v_TaxCurrencyCode
                    ,v_BillingReference_InvoiceDocumentReference_ID
                    ,v_BillingReference_InvoiceDocumentReference_UUID
                    ,v_ASP_Party_IndustryClassificationCode
                    ,v_ASP_Party_IndustryClassificationCode__Name
                    ,v_ASP_Party_PartyIdentification_ID1
                    ,v_ASP_Party_PartyIdentification_ID1__SchemeID
                    ,v_ASP_Party_PartyIdentification_ID2
                    ,v_ASP_Party_PartyIdentification_ID2__SchemeID
                    ,v_ASP_Party_PartyIdentification_ID3
                    ,v_ASP_Party_PartyIdentification_ID3__SchemeID
                    ,v_ASP_Party_PartyName_Name
                    ,v_ASP_Party_PostalAddress_StreetName
                    ,v_ASP_Party_PostalAddress_AdditionalStreetName
                    ,v_ASP_Party_PostalAddress_CityName
                    ,v_ASP_Party_PostalAddress_PostalZone
                    ,v_ASP_Party_PostalAddress_CountrySubentityCode
                    ,v_ASP_Party_PostalAddress_Country_IdentificationCode
                    ,v_ASP_Party_PostalAddress_Country_IdentificationCode__ListID
                    ,v_ASP_Party_PostalAddress_Country_IdentificationCode__ListAgencyID
                    ,v_ASP_Party_PartyLegalEntity_RegistrationName
                    ,v_ASP_Party_Contact_Telephone
                    ,v_ASP_Party_Contact_ElectronicMail
                    ,v_ACP_Party_PartyIdentification_ID1
                    ,v_ACP_Party_PartyIdentification_ID1__SchemeID
                    ,v_ACP_Party_PartyIdentification_ID2
                    ,v_ACP_Party_PartyIdentification_ID2__SchemeID
                    ,v_ACP_Party_PartyIdentification_ID3
                    ,v_ACP_Party_PartyIdentification_ID3__SchemeID
                    ,v_ACP_Party_PartyName_Name
                    ,v_ACP_Party_PostalAddress_StreetName
                    ,v_ACP_Party_PostalAddress_AdditionalStreetName
                    ,v_ACP_Party_PostalAddress_CityName
                    ,v_ACP_Party_PostalAddress_PostalZone
                    ,v_ACP_Party_PostalAddress_CountrySubentityCode
                    ,v_ACP_Party_PostalAddress_Country_IdentificationCode
                    ,v_ACP_Party_PostalAddress_Country_IdentificationCode__ListID
                    ,v_ACP_Party_PostalAddress_Country_IdentificationCode__ListAgencyID
                    ,v_ACP_Party_PartyLegalEntity_RegistrationName
                    ,v_ACP_Party_Contact_Telephone
                    ,v_PaymentTerms_Note
                    ,v_TaxExchangeRate_SourceCurrencyCode
                    ,v_TaxExchangeRate_TargetCurrencyCode
                    ,v_TaxExchangeRate_CalculationRate
                    ,v_TaxTotal_TaxAmount
                    ,v_TaxTotal_TaxAmount__CurrencyID
                    ,v_TaxTotal_TaxSubtotal_TaxableAmount
                    ,v_TaxTotal_TaxSubtotal_TaxableAmount__CurrencyID
                    ,v_TaxTotal_TaxSubtotal_TaxAmount
                    ,v_TaxTotal_TaxSubtotal_TaxAmount__CurrencyID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_ID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID__SchemeID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID__SchemeAgencyID
                    ,v_LegalMonetaryTotal_LineExtensionAmount
                    ,v_LegalMonetaryTotal_LineExtensionAmount__CurrencyID
                    ,v_LegalMonetaryTotal_TaxExclusiveAmount
                    ,v_LegalMonetaryTotal_TaxExclusiveAmount__CurrencyID
                    ,v_LegalMonetaryTotal_TaxInclusiveAmount
                    ,v_LegalMonetaryTotal_TaxInclusiveAmount__CurrencyID
                    ,v_LegalMonetaryTotal_PayableAmount
                    ,v_LegalMonetaryTotal_PayableAmount__CurrencyID
                    ,v_InvoiceLine_ID
                    ,v_InvoiceLine_InvoicedQuantity
                    ,v_InvoiceLine_InvoicedQuantity__UnitCode
                    ,v_InvoiceLine_LineExtentionAmount
                    ,v_InvoiceLine_LineExtentionAmount__CurrencyID
                    ,v_InvoiceLine_TaxTotal_TaxAmount
                    ,v_InvoiceLine_TaxTotal_TaxAmount__CurrencyID
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxableAmount
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxableAmount__CurrencyID
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxAmount
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxAmount__CurrencyID
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_Percent
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_ID
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxExemptionReason
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeID
                    ,v_InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeAgencyID
                    ,v_InvoiceLine_Item_Description
                    ,v_InvoiceLine_Item_OriginCountry_IdentificationCode
                    ,v_InvoiceLine_Item_CommodityClassification_ItemClassificationCode
                    ,v_InvoiceLine_Item_CommodityClassification_ItemClassificationCode__ListID
                    ,v_InvoiceLine_Price_PriceAmount
                    ,v_InvoiceLine_Price_PriceAmount__CurrencyID
                    ,v_InvoiceLine_ItemPriceExtension_Amount
                    ,v_InvoiceLine_ItemPriceExtension_Amount__CurrencyID;

                EXIT WHEN c_detail%NOTFOUND;

                IF v_is_first_record = TRUE THEN

                    v_is_first_record   := FALSE;

                    UPDATE
                        proddta.f550301h f550301h
                    SET
                         f550301h.ehedsp = 'I'
                        ,f550301h.ehpid  = v_pid
                        ,f550301h.ehjobn = v_jobn
                        ,f550301h.ehuser = v_user
                        ,f550301h.ehupmj = v_upmj
                        ,f550301h.ehupmt = v_upmt
                    WHERE
                        TRIM(f550301h.ehtaskID) = TRIM(v_HeaderTaskID);

                    COMMIT;

                    -----------------------------------------------------------
                    -- Invoice
                    -----------------------------------------------------------
                    xml_invoice_element                                     := dbms_xmldom.createElement(xml_domdoc, 'Invoice');
                    dbms_xmldom.setattribute(xml_invoice_element, 'xmlns:cac', 'urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2');
                    dbms_xmldom.setattribute(xml_invoice_element, 'xmlns:cbc', 'urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2');
                    dbms_xmldom.setattribute(xml_invoice_element, 'xmlns', 'urn:oasis:names:specification:ubl:schema:xsd:Invoice-2_JDE');

                    xml_invoice_node                                        := dbms_xmldom.appendChild(xml_invoices_node, dbms_xmldom.makeNode(xml_invoice_element));

                    xml_header_id_node                                      := dbms_xmldom.appendChild(xml_invoice_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'JDEHeaderID')));
                    xml_header_id_text_node                                 := dbms_xmldom.appendChild(xml_header_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_HeaderTaskID)));

                    xml_id_node                                             := dbms_xmldom.appendChild(xml_invoice_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_id_text_node                                        := dbms_xmldom.appendChild(xml_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_Invoice_ID)));

                    xml_issue_date_node                                     := dbms_xmldom.appendChild(xml_invoice_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IssueDate')));
                    xml_issue_date_text_node                                := dbms_xmldom.appendChild(xml_issue_date_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_IssueDate)));

                    xml_issue_time_node                                     := dbms_xmldom.appendChild(xml_invoice_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IssueTime')));
                    xml_issue_time_text_node                                := dbms_xmldom.appendChild(xml_issue_time_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_IssueTime)));

                    xml_due_date_node                                       := dbms_xmldom.appendChild(xml_invoice_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:DueDate')));
