                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_Price_PriceAmount)));

                -----------------------------------------------------------
                -- InvoiceLine / ItemPriceExtension
                -----------------------------------------------------------
                xml_inv_line_item_price_extension_node                  := dbms_xmldom.appendChild(xml_invoice_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:ItemPriceExtension')));

                xml_inv_line_item_price_extension_amount_element        := dbms_xmldom.createElement(xml_domdoc, 'cbc:Amount');
                dbms_xmldom.setAttribute(xml_inv_line_item_price_extension_amount_element, 'currencyID', v_InvoiceLine_ItemPriceExtension_Amount__CurrencyId);

                xml_inv_line_item_price_extension_amount_node           := dbms_xmldom.appendChild(xml_inv_line_item_price_extension_node,
                                                                            dbms_xmldom.makeNode(xml_inv_line_item_price_extension_amount_element));
                xml_inv_line_item_price_extension_amount_text_node      := dbms_xmldom.appendChild(xml_inv_line_item_price_extension_amount_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_InvoiceLine_ItemPriceExtension_Amount)));

            END LOOP;

            CLOSE c_detail;

        END LOOP;

        CLOSE c_driver;

        xml_xmltype     := dbms_xmldom.getXmlType(xml_domdoc);
        dbms_xmldom.freeDocument(xml_domdoc);

        IF v_records_found = TRUE THEN

            o_xml_clob      := xml_xmltype.getClobVal;

        ELSE

            o_xml_clob      := TO_CLOB('No Data Found');

        END IF;

        EXCEPTION
            WHEN OTHERS THEN

                v_err_nbr := SQLCODE;
                v_err_msg := v_err_job_name || ' - '||SQLERRM;

                ------------------------------------------------------
                -- Rollback changes
                ------------------------------------------------------
                ROLLBACK;

                ------------------------------------------------------
                -- Insert record into PL/SQL logging table
                ------------------------------------------------------
                INSERT INTO
                    commobj.joberr
                    (
                        job_name,
                        err#,
                        err_msg,
                        TIMESTAMP
                    )
                    VALUES
                    (
                        v_err_job_name,
                        v_err_nbr,
                        v_err_msg,
                        SYSDATE
                    );

                COMMIT;

                o_return_message := 'FAILURE: ' || SQLERRM;

    END USP_MY_INVOICE_XML_SELECT;



