                                                    MAX(cxeft)
                                                FROM
                                                    PRODDTA.f550015
                                                WHERE
                                                    cxcrcd = AP_Ledger_Line_Detail.rpbcrc
                                                    AND cxcrdc = 'MYR'
                                                    AND cxeft <= AP_Ledger_Line_Detail.rpdgj
                                            )
                                    )
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'D' AND AP_Ledger_Line_Detail.rpbcrc = 'MYR'
                            THEN
                                AP_Ledger_Line_Detail.rpstam *
                                F0411_Base_Currency.Decimal_Position
                        END)
                    WHEN
                        PO_Receiver.prdoc IS NOT NULL
                    THEN
                        (CASE
