                                (NVL(Tax_Rate.F4008_Tax_Rate_1,0) * .001)
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'D'
                                AND PO_Receiver.prbcrc = 'MYR'
                            THEN
                                (PO_Receiver.praptd * F0411_Base_Currency.Decimal_Position) *
                                (NVL(Tax_Rate.F4008_Tax_Rate_1,0) * .001)
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F'
                                AND PO_Receiver.prcrcd <> 'MYR'
                            THEN
                                ((PO_Receiver.prfapt * F0411_Foreign_Currency.Decimal_Position) *
