                                            )
                                    )
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'F' AND AP_Ledger_Line_Detail.rpcrcd = 'MYR'
                            THEN
                                AP_Ledger_Line_Detail.rpctam *
                                F0411_Foreign_Currency.Decimal_Position
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'D' AND AP_Ledger_Line_Detail.rpbcrc <> 'MYR'
                            THEN
                                (AP_Ledger_Line_Detail.rpstam *
                                F0411_Base_Currency.Decimal_Position) *
                                    (
