                        END),4)
                    WHEN
                        PO_Receiver.prdoc IS NOT NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F' AND PO_Receiver.prfrrc = 0
                            THEN
                                PO_Receiver.prfapt * F0411_Foreign_Currency.Decimal_Position
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F' AND PO_Receiver.prfrrc <> 0
                            THEN
                                PO_Receiver.prfrrc * .0001
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'D' AND PO_Receiver.prprrc = 0
                            THEN
                                PO_Receiver.praptd * F0411_Base_Currency.Decimal_Position
                            ELSE
                                PO_Receiver.prprrc * .0001
                        END)
