        -----------------------------------------------------------
        -- Declare Cursor Variables
        -----------------------------------------------------------
         CURSOR c_driver IS
            SELECT
                 ehurab
                ,ehdl01
                ,ehurdt
            FROM
                proddta.f550301h
            WHERE
                ehev01 = 'C'
                AND ehev02 = 'S'
                AND
                (
                    f550301h.ehedsp = 'N'
                    OR
                    (
                        ehedsp IN ('I', 'P')
                        AND
                        (
                            24 *
                            (
                                SYSDATE
                                -
                                TO_DATE
                                (
                                    TO_CHAR(TO_DATE(TO_CHAR(f550301h.ehupmj+1900000),'YYYYDDD'),'yyyy-mm-dd')
                                    || ' ' || LPAD(TO_CHAR(f550301h.ehupmt), 6, '0' ),
                                    'yyyy-mm-dd hh24miss'
                                )
                            )
                            >= 24
                        )
                    )
                )
            FETCH FIRST 10 ROWS ONLY;

        CURSOR c_detail IS
            SELECT
                 TRIM(f550301h.ehtaskid)                                                    AS HeaderTaskID
                ,TRIM(AP_Ledger.F0411_Voucher_Number)                                       AS Invoice_ID                                          -- 3 THIS MEETS MY APPENDIX 1 FIELD 20 REQUIREMENT
                ,NVL(TO_CHAR(sys_extract_utc(SYSTIMESTAMP), 'yyyy-mm-dd'),' ')              AS IssueDate                                            -- 5 THIS MEETS MY APPENDIX 1 FIELD 22 REQUIREMENT
                ,TO_CHAR(sys_extract_utc(SYSTIMESTAMP)
                    - INTERVAL '1' MINUTE, 'HH24:MI:SS') || 'Z'                             AS IssueTime                                            -- 6 THIS MEETS MY APPENDIX 1 FIELD 22 REQUIREMENT
                ,CASE
                    WHEN
                        AP_Ledger.F0411_Base_Gross_Amount < 0
                    THEN
                        '12'
                    ELSE
                        '11'
                END                                                                         AS InvoiceTypeCode                                      -- 8 THIS MEETS MY APPENDIX 1 FIELD 19 REQUIREMENT - 11 SELF BILLED INVOICE / 12 - SELF BILLED CREDIT NOTE / 13 - SELF BILLED DEBIT NOTE / 14 - SELF BILLED REFUND NOTE
                ,CASE
                    WHEN
                        AP_Ledger.F0411_Base_Gross_Amount < 0
                    THEN
                        (
                            SELECT
                                TRIM(DRDL01)
                            FROM
                                PRODCTL.F0005
                            WHERE
                                DRSY = '55'
                                AND DRRT = 'MV'
                                AND TRIM(DRKY) = '2'
                        )
                    ELSE
                        (
                            SELECT
                                TRIM(DRDL01)
                            FROM
                                PRODCTL.F0005
                            WHERE
                                DRSY = '55'
                                AND DRRT = 'MV'
                                AND TRIM(DRKY) = '1'
                        )
                END                                                                         AS InvoiceTypeCode__ListVersionID                       -- THIS MEETS MY APPENDIX 1 FIELD 18 REQUIREMENT
                ,CASE
                    WHEN
                        AP_Ledger.F0411_Currency_Mode = 'F'
                    THEN
                        TRIM(AP_Ledger.F0411_Foreign_Currency)
                    ELSE
                        TRIM(AP_Ledger.F0411_Base_Currency)
                END                                                                         AS DocumentCurrencyCode                                 -- 11 THIS MEETS MY APPENDIX 1 FIELD 24 REQUIREMENT
                ,'MYR'                                                                      AS TaxCurrencyCode                                      -- 12 THIS MEETS PEPPOL REQUIREMENT
                ,CASE
                    WHEN
                        AP_Ledger.F550301h_Voucher_Number IS NULL AND AP_Ledger.F0411_Base_Gross_Amount < 0
                    THEN
                        'NA'
                    WHEN
                        AP_Ledger.F550301h_Voucher_Number IS NOT NULL AND AP_Ledger.F0411_Base_Gross_Amount < 0
                    THEN
                        AP_Ledger.F550301h_Voucher_Number
                    ELSE
                        NULL
                END                                                                         AS BillingReference_InvoiceDocumentReference_ID         -- 20.1.1 THIS MEETS MY APPENDIX 1 FIELD 23 REQUIREMENT
                ,CASE
                    WHEN
                        TRIM(AP_Ledger.F550301h_Voucher_Number) IS NULL AND AP_Ledger.F0411_Base_Gross_Amount < 0
                    THEN
                        'NA'
                    WHEN
                        TRIM(AP_Ledger.F550301h_Voucher_Number) IS NOT NULL AND AP_Ledger.F0411_Base_Gross_Amount < 0
                    THEN
                        AP_Ledger.F550301h_UUID
                    ELSE
                        NULL
                END                                                                         AS BillingReference_InvoiceDocumentReference_UUID       -- 20.1.2 THIS MEETS MY APPENDIX 1 FIELD 23 REQUIREMENT
--                ,CASE
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('S','X','J','JT') AND PO_Receiver.prdcto <> 'OJ' AND Tracking_Number.Tracking_Number_ID IS NOT NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0 AND PO_Receiver.probj <> '121005'
--                    THEN
--                        Tracking_Number.Tracking_Number_ID
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('S') AND PO_Receiver.prdcto <> 'OJ' AND Tracking_Number.Tracking_Number_ID IS NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'NA'
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('S') AND PO_Receiver.prdcto = 'OJ' AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'Consignment'
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('X') AND Tracking_Number.Tracking_Number_ID IS NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'NA'
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('J','JT') AND AP_Ledger.F0411_Base_Amount_Tax >= 0 AND PO_Receiver.probj = '121005' AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'Consignment'
--                    ELSE
--                        ' '
--                END                                                                         AS AdditionalDocumentReference_ID                                   -- 25.1 THIS MEETS MY APPENDIX 2 FIELD 1 REQUIREMENT
--                ,CASE
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('S','X','J','JT') AND PO_Receiver.prdcto <> 'OJ' AND Tracking_Number.Tracking_Number_ID IS NOT NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0 AND PO_Receiver.probj <> '121005'
--                    THEN
--                        'CustomsImportForm'
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('S') AND PO_Receiver.prdcto <> 'OJ' AND Tracking_Number.Tracking_Number_ID IS NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'CustomsImportForm'
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('S') AND PO_Receiver.prdcto = 'OJ' AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'CustomsImportForm'
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('X') AND Tracking_Number.Tracking_Number_ID IS NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'CustomsImportForm'
--                    WHEN
--                        TRIM(PO_Receiver.prlnty) IN ('J','JT') AND AP_Ledger.F0411_Base_Amount_Tax >= 0 AND PO_Receiver.probj = '121005' AND AP_Ledger.F0411_Base_Amount_Tax >= 0
--                    THEN
--                        'CustomsImportForm'
--                    ELSE
--                        ' '
--                END                                                                           AS AdditionalDocumentDocumentReference                              -- 25.2
                ,'00000'                                                                    AS ASP_Party_IndustryClassificationCode                             -- 27.1.1.2 THIS MEETS MY APPENDIX 1 FIELD 8 REQUIREMENT
                ,'NA'                                                                       AS ASP_Party_IndustryClassificationCode__Name                       -- 27.1.1.1.2 THIS MEETS MY APPENDIX 1 FIELD 9 REQUIREMENT
                ,'EI00000000030'                                                            AS ASP_Party_PartyIdentification_ID1                                -- 27.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 3 REQUIREMENT
                ,'TIN'                                                                      AS ASP_Party_PartyIdentification_ID1__SchemeID                      -- 27.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 3 REQUIREMENT
                ,'NA'                                                                       AS ASP_Party_PartyIdentification_ID2                                -- 27.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT
                ,'BRN'                                                                      AS ASP_Party_PartyIdentification_ID2__SchemeID                      -- 27.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT
                ,'NA'                                                                       AS ASP_Party_PartyIdentification_ID3                                -- 27.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT
                ,'SST'                                                                      AS ASP_Party_PartyIdentification_ID3__SchemeID                      -- 27.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 4 REQUIREMENT
                ,TRIM(AP_Ledger.Seller_Name)                                                AS ASP_PartyName_Name                                               -- 27.1.3.1 THIS MEETS MY APPENDIX 1 FIELD 1 REQUIREMENT
                ,TRIM(TRIM(AP_Ledger.Seller_Address_Line_1) || ' ' ||
                                            TRIM(AP_Ledger.Seller_Address_Line_2))          AS ASP_Party_PostalAddress_StreetName                               -- 27.1.4.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,TRIM(TRIM(AP_Ledger.Seller_Address_Line_3) || ' ' ||
                                            TRIM(AP_Ledger.Seller_Address_Line_4))          AS ASP_Party_PostalAddress_AdditionalStreetName                     -- 27.1.4.2 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,CASE
                    WHEN
                        TRIM(AP_Ledger.Seller_City) IS NULL
                    THEN
                        'NA'
                    ELSE
                        TRIM(AP_Ledger.Seller_City)
                END                                                                         AS ASP_Party_PostalAddress_CityName                                 -- 27.1.4.6 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,TRIM(AP_Ledger.Seller_Zip)                                                 AS ASP_Party_PostalAddress_PostalZone                               -- 27.1.4.7 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,'17'                                                                       AS ASP_Party_PostalAddress_CountrySubentityCode                     -- 27.1.4.8 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,CASE
                    WHEN
                        TRIM(AP_Ledger.Seller_Country) = 'KR'
                    THEN
                        'KP'
                    ELSE
                        TRIM(AP_Ledger.Seller_Country)
                END                                                                         AS ASP_Party_PostalAddress_Country_IdentificationCode               -- 27.1.4.10.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,'ISO3166-1'                                                                AS ASP_Party_PostalAddress_Country_IdentificationCode__ListID       -- 27.1.4.10.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,'6'                                                                        AS ASP_Party_PostalAddress_Country_IdentificationCode__ListAgencyID -- 27.1.4.10.1 THIS MEETS MY APPENDIX 1 FIELD 14 REQUIREMENT
                ,TRIM(AP_Ledger.Seller_Name)                                                AS ASP_Party_PartyLegalEntity_RegistrationName                      -- 27.1.6.1 THIS MEETS MY APPENDIX 1 FIELD 1 REQUIREMENT
                ,CASE
                    WHEN
                        TRIM(AP_Ledger.Seller_Phone_Number) =  '+'
                    THEN
                        '+0000000000'
                    ELSE
                        TRIM(AP_Ledger.Seller_Phone_Number)
                END                                                                         AS ASP_Party_Contact_Telephone                                      -- 27.1.7.2 THIS MEETS MY APPENDIX 1 FIELD 16 REQUIREMENT
                ,'C5892425060'                                                              AS ACP_Party_PartyIdentification_ID1                                -- 28.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 10 REQUIREMENT
                ,'TIN'                                                                      AS ACP_Party_PartyIdentification_ID1__SchemeID                      -- 28.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 10 REQUIREMENT
                ,'199601026784'                                                             AS ACP_Party_PartyIdentification_ID2                                -- 28.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 11 REQUIREMENT
                ,'BRN'                                                                      AS ACP_Party_PartyIdentification_ID2__SchemeID                      -- 28.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 11 REQUIREMENT
                ,'NA'                                                                       AS ACP_Party_PartyIdentification_ID3                                -- 28.1.2.1 THIS MEETS MY APPENDIX 1 FIELD 12 REQUIREMENT
                ,'SST'                                                                      AS ACP_Party_PartyIdentification_ID3__SchemeID                      -- 28.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 12 REQUIREMENT
                ,'PLEXUS MANUFACTURING SDN. BHD.'                                           AS ACP_Party_PartyName_Name                                         -- 28.1.2.1.1 THIS MEETS MY APPENDIX 1 FIELD 2 REQUIREMENT
                ,TRIM(
                    TRIM(AP_Ledger.Buyer_Address_Line_2)     || ' ' ||
                    TRIM(AP_Ledger.Buyer_Address_Line_3)  || ' ' ||
                    TRIM(AP_Ledger.Buyer_Address_Line_4)
                )                                                                           AS ACP_Party_PostalAddress_StreetName                               -- 28.1.4.1 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,TRIM(AP_Ledger.Buyer_Address_Line_1)                                       AS ACP_Party_PostalAddress_AdditionalStreetName                     -- 28.1.4.2 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,TRIM(AP_Ledger.Buyer_City)                                                 AS ACP_Party_PostalAddress_CityName                                 -- 28.1.4.6 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,TRIM(AP_Ledger.Buyer_Zip_Code)                                             AS ACP_Party_PostalAddress_PostalZone                               -- 28.1.4.7 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,'07'                                                                       AS ACP_Party_PostalAddress_CountrySubentityCode                     -- 28.1.4.8 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,'MY'                                                                       AS ACP_Party_PostalAddress_Country_IdentificationCode               -- 28.1.4.11.1 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,'ISO3166-1'                                                                AS ACP_Party_PostalAddress_Country_IdentificationCode__listID       -- 28.1.4.11.1 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,'6'                                                                        AS ACP_Party_PostalAddress_Country_IdentificationCode__listAgencyID -- 28.1.4.11.1 THIS MEETS MY APPENDIX 1 FIELD 15 REQUIREMENT
                ,'PLEXUS MANUFACTURING SDN. BHD.'                                           AS ACP_Party_PartyLegalEntity_RegistrationName                      -- 28.1.6.1 THIS MEETS MY APPENDIX 1 FIELD 2 REQUIREMENT
