                                ((PO_Receiver.prfapt * F0411_Foreign_Currency.Decimal_Position) *
                                    (
                                        SELECT
                                            cxcrr
                                        FROM
                                            PRODDTA.f550015
                                        WHERE
                                            cxcrcd = AP_Ledger.F0411_Foreign_Currency
                                            AND cxcrdc = 'MYR'
                                            AND cxeft =
                                            (
                                                SELECT
                                                    MAX(cxeft)
                                                FROM
                                                    PRODDTA.f550015
                                                WHERE
                                                    cxcrcd = AP_Ledger.F0411_Foreign_Currency
                                                    AND cxcrdc = 'MYR'
                                                    AND cxeft <= AP_Ledger.F0411_Voucher_GL_Date
                                            )
                                    )
                                )
                                * (NVL(Tax_Rate.F4008_Tax_Rate_1,0) * .001)
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F'
                                AND PO_Receiver.prcrcd <> 'MYR'
                                AND AP_Ledger.F550301h_Original_Voucher_Date > 0
                            THEN
                                ((PO_Receiver.prfapt * F0411_Foreign_Currency.Decimal_Position) *
                                    (
                                        SELECT
                                            cxcrr
                                        FROM
                                            PRODDTA.f550015
                                        WHERE
                                            cxcrcd = AP_Ledger.F0411_Foreign_Currency
                                            AND cxcrdc = 'MYR'
                                            AND cxeft =
                                            (
                                                SELECT
                                                    MAX(cxeft)
                                                FROM
                                                    PRODDTA.f550015
                                                WHERE
                                                    cxcrcd = AP_Ledger.F0411_Foreign_Currency
                                                    AND cxcrdc = 'MYR'
                                                    AND cxeft <= AP_Ledger.F550301h_Original_Voucher_Date
                                            )
                                    )
                                )
                                * (NVL(Tax_Rate.F4008_Tax_Rate_1,0) * .001)
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'D'
                                AND PO_Receiver.prbcrc <> 'MYR'
                                AND
                                (
                                    AP_Ledger.F550301h_Original_Voucher_Date IS NULL
                                    OR AP_Ledger.F550301h_Original_Voucher_Date = 0
                                )
                            THEN
                                ((PO_Receiver.praptd * F0411_Base_Currency.Decimal_Position) *
                                (
                                    SELECT
                                        cxcrr
                                    FROM
                                        PRODDTA.f550015
                                    WHERE
                                        cxcrcd = AP_Ledger.F0411_Base_Currency
                                        AND cxcrdc = 'MYR'
                                        AND cxeft =
                                        (
                                            SELECT
                                                MAX(cxeft)
                                            FROM
                                                PRODDTA.f550015
                                            WHERE
                                                cxcrcd = AP_Ledger.F0411_Base_Currency
                                                AND cxcrdc = 'MYR'
                                                AND cxeft <= AP_Ledger.F0411_Voucher_GL_Date
                                        )
                                ))
                                * (NVL(Tax_Rate.F4008_Tax_Rate_1,0) * .001)
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'D'
                                AND PO_Receiver.prbcrc <> 'MYR'
                                AND AP_Ledger.F550301h_Original_Voucher_Date > 0
                            THEN
                                ((PO_Receiver.praptd * F0411_Base_Currency.Decimal_Position) *
                                (
                                    SELECT
                                        cxcrr
                                    FROM
                                        PRODDTA.f550015
                                    WHERE
                                        cxcrcd = AP_Ledger.F0411_Base_Currency
                                        AND cxcrdc = 'MYR'
                                        AND cxeft =
                                        (
                                            SELECT
                                                MAX(cxeft)
                                            FROM
                                                PRODDTA.f550015
                                            WHERE
                                                cxcrcd = AP_Ledger.F0411_Base_Currency
                                                AND cxcrdc = 'MYR'
                                                AND cxeft <= AP_Ledger.F550301h_Original_Voucher_Date
                                        )
                                ))
                                * (NVL(Tax_Rate.F4008_Tax_Rate_1,0) * .001)
                        END)
                END                                                                         AS InvoiceLine_TaxTotal_TaxSubTotal_TaxAmount                       -- 40.11.3.2 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 33
                ,'MYR'                                                                      AS InvoiceLine_TaxTotal_TaxSubTotal_TaxAmount__CurrencyID           -- 40.11.3.2.1 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 33
                ,NVL(Tax_Rate.F4008_Tax_Rate_1,0) * .001                                    AS InvoiceLine_TaxTotal_TaxSubTotal_Percent                                     -- 40.11.3.2.2 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 32
                ,'06'                                                                       AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_ID                              -- 40.11.3.3.1 THIS MEETS MY APPENDIX 1 FIELD 31 REQUIREMENT 01;Sales Tax /02;Service Tax /03;Tourism Tax /04;High-Value Goods Tax /05;Sales Tax on Low Value Goods /06;Not Applicable / E; Exempt from tax (in case of exempion only )
                ,'NA'                                                                       AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxExemptionReason              -- 40.11.3.3.6 THIS MEETS MY APPENDIX 1 FIELD 34 REQUIREMENT
                ,'OTH'                                                                      AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID                    -- 40.11.3.3.7 THIS MEETS MY APPENDIX 1 FIELD 34 REQUIREMENT
                ,'UN/ECE 5153'                                                              AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeID          -- 40.11.3.3.7 THIS MEETS MY APPENDIX 1 FIELD 34 REQUIREMENT
                ,'6'                                                                        AS InvoiceLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeAgencyID    -- 40.11.3.3.7 THIS MEETS MY APPENDIX 1 FIELD 34 REQUIREMENT
                ,NVL((CASE
                    WHEN
                        PO_Receiver.prdoc IS NULL
                    THEN
                        TRIM(AP_Ledger_Line_Detail.RPRMK)
                    WHEN
                        PO_Receiver.prdoc IS NOT NULL
                    THEN
                        (CASE
                            WHEN
                                PO_Receiver.prlitm LIKE ('%PO LINE%')
                            THEN
                                CONCAT(TRIM(Purchase_Order_Detail.PDDSC1), CONCAT(' ',TRIM(Purchase_Order_Detail.PDDSC2)))
                            ELSE
                                TRIM(PO_Receiver.prlitm)
                        END)
                END),'LINE')                                                                AS InvoiceLine_Item_Description                                                 -- 40.12.1 THIS MEETS MY APPENDIX 1 FIELD 29 REQUIREMENT
                ,CASE
                    WHEN
                        TRIM(AP_Ledger.Seller_Country) = 'KR'
                    THEN
                        'KP'
                    ELSE
                        TRIM(AP_Ledger.Seller_Country)
                END                                                                         AS InvoiceLine_Item_OriginCountry_IdentificationCode                            -- 40.12.6.1 THIS MEETS MY APPENDIX 2 FIELD 5 REQUIREMENT
                ,CASE
                    WHEN
                        TRIM(PO_Receiver.prlnty) IN ('S','X','J','JT') AND PO_Receiver.prdcto <> 'OJ' AND Tracking_Number.Tracking_Number_ID IS NOT NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0 AND PO_Receiver.probj <> '121005'
                    THEN
                        '034'
                    WHEN
                        TRIM(PO_Receiver.prlnty) IN ('S') AND PO_Receiver.prdcto <> 'OJ' AND Tracking_Number.Tracking_Number_ID IS NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0
                    THEN
                        '034'
                    WHEN
                        TRIM(PO_Receiver.prlnty) IN ('S') AND PO_Receiver.prdcto = 'OJ' AND AP_Ledger.F0411_Base_Amount_Tax >= 0
                    THEN
                        '034'
                    WHEN
                        TRIM(PO_Receiver.prlnty) IN ('X') AND Tracking_Number.Tracking_Number_ID IS NULL AND AP_Ledger.F0411_Base_Amount_Tax >= 0
                    THEN
                        '034'
                    WHEN
                        TRIM(PO_Receiver.prlnty) IN ('J','JT') AND AP_Ledger.F0411_Base_Amount_Tax >= 0 AND PO_Receiver.probj = '121005' AND AP_Ledger.F0411_Base_Amount_Tax >= 0
                    THEN
                        '034'
                    ELSE
                        '035'
                END                                                                         AS InvoiceLine_Item_CommodityClassification_ItemClassificationCode              -- 40.12.7.1 THIS MEETS MY APPENDIX 1 FIELD 28 REQUIREMENT
                ,'CLASS'                                                                    AS InvoiceLine_Item_CommodityClassification_ItemClassificationCode__ListID      -- 40.12.7.1 THIS MEETS MY APPENDIX 1 FIELD 28 REQUIREMENT
                ,CASE
                    WHEN
                        PO_Receiver.prdoc IS NULL AND AP_Ledger_Line_Detail.rpu = 0
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'F'
                            THEN
                                AP_Ledger_Line_Detail.rpacr * F0411_Foreign_Currency.Decimal_Position
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'D'
                            THEN
                                AP_Ledger_Line_Detail.rpag * F0411_Base_Currency.Decimal_Position
                        END)
                    WHEN
                        PO_Receiver.prdoc IS NULL AND AP_Ledger_Line_Detail.rpu <> 0
                    THEN
                        ROUND((CASE
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'F'
                            THEN
                                (AP_Ledger_Line_Detail.rpacr *
                                F0411_Foreign_Currency.Decimal_Position) /
                                (AP_Ledger_Line_Detail.rpu * .01)
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'D'
                            THEN
                                (AP_Ledger_Line_Detail.rpag *
                                F0411_Base_Currency.Decimal_Position) /
                                (AP_Ledger_Line_Detail.rpu * .01)
                        END),4)
                    WHEN
                        PO_Receiver.prdoc IS NOT NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F' AND PO_Receiver.prfrrc = 0
                            THEN
                                PO_Receiver.prfapt * F0411_Foreign_Currency.Decimal_Position
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F' AND PO_Receiver.prfrrc <> 0
                            THEN
                                PO_Receiver.prfrrc * .0001
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'D' AND PO_Receiver.prprrc = 0
                            THEN
                                PO_Receiver.praptd * F0411_Base_Currency.Decimal_Position
                            ELSE
                                PO_Receiver.prprrc * .0001
                        END)
                END                                                                         AS InvoiceLine_Price_PriceAmount                                                -- 40.13.1 THIS MEETS MY APPENDIX 1 FIELD 30 REQUIREMENT
                ,CASE
                    WHEN
                        PO_Receiver.prdoc IS NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'F'
                            THEN
                                AP_Ledger_Line_Detail.rpcrcd
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'D'
                            THEN
                                AP_Ledger_Line_Detail.rpbcrc
                        END)
                    WHEN
                        PO_Receiver.prdoc IS NOT NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F'
                            THEN
                                TRIM(PO_Receiver.prcrcd)
                            ELSE
                                TRIM(PO_Receiver.prbcrc)
                        END)
                END                                                                         AS InvoiceLine_Price_PriceAmount__CurrencyID                                    -- 40.13.1.1 THIS MEETS MY APPENDIX 1 FIELD 30 REQUIREMENT
                ,CASE
                    WHEN
                        PO_Receiver.prdoc IS NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'F'
                            THEN
                                AP_Ledger_Line_Detail.rpacr *
                                F0411_Foreign_Currency.Decimal_Position
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'D'
                            THEN
                                AP_Ledger_Line_Detail.rpag *
                                F0411_Base_Currency.Decimal_Position
                        END)
                    WHEN
                        PO_Receiver.prdoc IS NOT NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F'
                            THEN
                                PO_Receiver.prfapt * F0411_Foreign_Currency.Decimal_Position
                            ELSE
                                PO_Receiver.praptd * F0411_Base_Currency.Decimal_Position
                        END)
                END                                                                         AS InvoiceLine_ItemPriceExtension_Amount                                        -- 40.13.4.1 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 36
                ,CASE
                    WHEN
                        PO_Receiver.prdoc IS NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'F'
                            THEN
                                AP_Ledger_Line_Detail.rpcrcd
                            WHEN
                                AP_Ledger_Line_Detail.rpcrrm = 'D'
                            THEN
                                AP_Ledger_Line_Detail.rpbcrc
                        END)
                    WHEN
                        PO_Receiver.prdoc IS NOT NULL
                    THEN
                        (CASE
                            WHEN
                                AP_Ledger.F0411_Currency_Mode = 'F'
                            THEN
                                TRIM(PO_Receiver.prcrcd)
                            ELSE
                                TRIM(PO_Receiver.prbcrc)
                        END)
                END                                                                         AS InvoiceLine_ItemPriceExtension_Amount__CurrencyID                            -- 40.13.4.2.1 THIS MEETS MY APPENDIX 1 FIELD 40 REQUIREMENT 36
            FROM
                (
                    SELECT
                        rpkco
                        ,rpdoc AS F0411_Voucher_Number
                        ,rpdct
                        ,rpan8
                        ,rpvod
                        ,rpdcta AS F0411_Doc_Type_Adjusting
                        ,rpdgj AS F0411_Voucher_GL_Date
                        ,SUM(rpag) AS F0411_Base_Gross_Amount
                        ,SUM(rpacr) AS F0411_Foreign_Gross_Amount
                        ,SUM(CASE
                                WHEN
                                    rppst = 'P'
                                THEN
                                    rpadsa
                                ELSE
                                    rpadsc
                            END) AS F0411_Base_Discount_Amount
                        ,SUM(CASE
                                WHEN
                                    rppst = 'P'
                                THEN
                                    rpcdsa
                                ELSE
                                    rpcds
                            END) AS F0411_Foreign_Discount_Amount
                        ,SUM(rpstam) AS F0411_Base_Amount_Tax
                        ,SUM(rpctam) AS F0411_Foreign_Amount_Tax
                        ,SUM(rpatxa) AS F0411_Base_Amount_Taxable
                        ,SUM(rpctxa) AS F0411_Foreign_Amount_Taxable
                        ,SUM(rpatxn) AS F0411_Base_Amount_Non_Taxable
                        ,SUM(rpctxn) AS F0411_Foreign_Amount_Non_Taxable
                        ,rpcrrm AS F0411_Currency_Mode
                        ,rpcrcd AS F0411_Foreign_Currency
                        ,rpbcrc AS F0411_Base_Currency
                        ,Void_In_Month_Check.Voucher_GL_Date AS Void_Check_Voucher_GL_Date
                        ,Void_In_Month_Check.F550301h_Voucher_Number AS F550301h_Voucher_Number
                        ,Void_In_Month_Check.F550301h_UUID AS F550301h_UUID
                        ,Void_In_Month_Check.F550301h_Update_Date AS F550301h_Update_Date
                        ,Void_In_Month_Check.Original_Voucher_Date AS F550301h_Original_Voucher_Date
                        ,Seller_Detail.wwmlnm AS Seller_Name
                        ,Seller_Detail.aladd1 AS Seller_Address_Line_1
                        ,Seller_Detail.aladd2 AS Seller_Address_Line_2
                        ,Seller_Detail.aladd3 AS Seller_Address_Line_3
                        ,Seller_Detail.aladd4 AS Seller_Address_Line_4
                        ,Seller_Detail.alcty1 AS Seller_City
                        ,Seller_Detail.aladdz AS Seller_Zip
                        ,Seller_Detail.alctr AS Seller_Country
                        ,Seller_Detail.wpph1 AS Seller_Phone_Number
                        ,Seller_Detail.a6txa2 AS Seller_Tax_Code
                        ,Buyer_Detail.aladd2 AS Buyer_Address_Line_2
                        ,Buyer_Detail.aladd3 AS Buyer_Address_Line_3
                        ,Buyer_Detail.aladd4 AS Buyer_Address_Line_4
                        ,Buyer_Detail.aladd1 AS Buyer_Address_Line_1
                        ,Buyer_Detail.alcty1 AS Buyer_City
                        ,Buyer_Detail.aladdz AS Buyer_Zip_Code
                    FROM PRODDTA.F0411
                    LEFT JOIN
                        (
                            SELECT
                                    rpkco AS Voucher_Company
                                    ,rpdoc AS Voucher_Number
                                    ,rpdct AS Voucher_Doc_Type
                                    ,TRIM(ehurab) AS F550301h_Voucher_Number
                                    ,TRIM(ehconstr1) AS F550301h_UUID
                                    ,ehupmj AS F550301h_Update_Date
                                    ,rpdgj AS Voucher_GL_Date
                                    ,'Void_Does_Match' AS Void_Check
                                    ,ehurdt AS Original_Voucher_Date
                                FROM PRODDTA.f0411
                                INNER JOIN PRODDTA.f550301h
                                    ON TRIM(ehurab) = rpdoc
                                    AND ehev02 = 'S'
                                    AND ehev01 = 'I'
                                    AND ehedsp = 'Y'
                                    AND ehurdt < v_dates_obj.start_date
                                WHERE
                                    rpvod = 'V'
                                    AND TRIM(rpdcta) IS NOT NULL
                                    AND rpdgj BETWEEN v_dates_obj.start_date AND v_dates_obj.end_date
                        ) Void_In_Month_Check
                        ON Void_In_Month_Check.Voucher_Company = rpkco
                        AND Void_In_Month_Check.Voucher_Number = rpdoc
                        AND Void_In_Month_Check.Voucher_Doc_Type = rpdct
                    INNER JOIN
                        (
                            SELECT
                                aban8
                                ,abat1
                                ,abmcu
                                ,abtax
                                ,abtx2
                                ,alctr
                                ,CASE
                                    WHEN TRIM(alctr) = 'MY'
                                THEN 'MY_SELLER'
                                    ELSE 'NON_MY_SELLER'
                                END AS MY_SELLER_FLAG
                                ,aladd1
                                ,aladd2
                                ,aladd3
                                ,aladd4
                                ,alcty1
                                ,aladds
                                ,aladdz
                                ,alcoun
                                ,a6txa2
                                ,wwslnm
                                ,wwmlnm
                                ,'+' || TRIM(REGEXP_REPLACE(wpar1,'[^[0-9]]*','')) || TRIM(REGEXP_REPLACE(wpph1,'[^[0-9]]*','')) AS wpph1
                            FROM
                                proddta.f0101 f0101
                            INNER JOIN proddta.f0116 f0116
                                ON  f0101.aban8     = f0116.alan8
                                AND f0101.abeftb    = f0116.aleftb
                            INNER JOIN proddta.f0111 f0111
                                ON f0101.aban8      = f0111.wwan8
                                AND f0111.wwidln    = 0
                            LEFT JOIN proddta.f0401 f0401
                                ON f0101.aban8 = f0401.a6an8
                            LEFT JOIN
                                (
                                    SELECT
                                        f0115.wpan8
                                        ,f0115.wpph1
                                        ,f0115.wpar1
                                    FROM
                                        (
                                            SELECT
                                                wpan8
                                                ,wpph1
                                                ,wpar1
                                                ,RANK() OVER (PARTITION BY wpan8 ORDER BY wpidln,wprck7 DESC) AS rnk
                                            FROM
                                                PRODDTA.f0115
                                            WHERE
                                                TRIM(wpphtp) IS NULL
                                        ) f0115
                                    WHERE f0115.rnk = 1
                                ) Seller_Phone
                                ON Seller_Phone.wpan8 = f0101.aban8
                        ) Seller_Detail
                        ON Seller_Detail.aban8 = rpan8
                    LEFT JOIN
                        (
                            SELECT
                                aban8
                                ,aladd2
                                ,aladd3
                                ,aladd4
                                ,aladd1
                                ,alcty1
                                ,aladdz
                            FROM
                                proddta.f0101 f0101
                            INNER JOIN proddta.f0116 f0116
                                ON  f0101.aban8     = f0116.alan8
                                AND f0101.abeftb    = f0116.aleftb
                            INNER JOIN proddta.f0111 f0111
                                ON  f0101.aban8     = f0111.wwan8
                                AND f0111.wwidln    = 0
                            LEFT JOIN proddta.f0115 f0115
                                ON  f0101.aban8     = f0115.wpan8
                                AND f0115.wpphtp    = '    '
                            ) Buyer_Detail
                            ON Buyer_Detail.aban8 = rpkco
                       WHERE
                            rpkco IN ('00037','00039','00048','00071','00083','00084','00092','00096')
                            AND
                                CASE
                                    WHEN rpptc IN ('PRE','204','205') AND TRIM(rppo) IS NULL
                                THEN
                                    1
                                ELSE
                                    0
                                END = 0
                            AND
                                CASE
                                    WHEN TRIM(rpvod) = 'V' AND Void_In_Month_Check.Void_Check IS NULL
                                THEN
                                    3
                                ELSE
                                    2
                                END = 2
                            AND rpdgj BETWEEN v_dates_obj.start_date AND v_dates_obj.end_date
                            AND Seller_Detail.MY_SELLER_FLAG = 'NON_MY_SELLER'
                            AND Seller_Detail.abat1 IN ('V','TC','IC','I')
                        GROUP BY rpkco,rpdoc,rpdct,rpan8,rpvod,rpdcta,rpdgj,rpcrrm,rpcrcd,rpbcrc
                                    ,Void_In_Month_Check.Voucher_GL_Date,F550301h_Voucher_Number,Void_In_Month_Check.F550301h_UUID,F550301h_Update_Date, Void_In_Month_Check.Original_Voucher_Date
                                        ,Seller_Detail.wwmlnm,Seller_Detail.aladd1,Seller_Detail.aladd2,Seller_Detail.aladd3,Seller_Detail.aladd4,Seller_Detail.alcty1,Seller_Detail.aladdz,Seller_Detail.alctr,Seller_Detail.a6txa2,Seller_Detail.wpph1
                                            ,Buyer_Detail.aladd2,Buyer_Detail.aladd3,Buyer_Detail.aladd4,Buyer_Detail.aladd1,Buyer_Detail.alcty1,Buyer_Detail.aladdz
                ) AP_Ledger
                LEFT JOIN
                    (
                        SELECT
                            cvcrcd
                            , cvcdec
                            , CASE
                                WHEN cvcdec = 0 THEN 1
                                WHEN cvcdec = 1 THEN .1
                                WHEN cvcdec = 2 THEN .01
                                WHEN cvcdec = 3 THEN .001
                                WHEN cvcdec = 4 THEN .0001
                                WHEN cvcdec = 5 THEN .00001
                                WHEN cvcdec = 6 THEN .000001
                                WHEN cvcdec = 7 THEN .0000001
                                WHEN cvcdec = 8 THEN .00000001
                                WHEN cvcdec = 9 THEN .000000001
                                ELSE .01
                                END AS Decimal_Position
                        FROM PRODDTA.f0013
                    ) F0411_Foreign_Currency
                    ON AP_Ledger.F0411_Foreign_Currency = F0411_Foreign_Currency.cvcrcd
                LEFT JOIN
                    (
                        SELECT
                            cvcrcd
                            , cvcdec
                            , CASE
                                WHEN cvcdec = 0 THEN 1
                                WHEN cvcdec = 1 THEN .1
                                WHEN cvcdec = 2 THEN .01
                                WHEN cvcdec = 3 THEN .001
                                WHEN cvcdec = 4 THEN .0001
                                WHEN cvcdec = 5 THEN .00001
                                WHEN cvcdec = 6 THEN .000001
                                WHEN cvcdec = 7 THEN .0000001
                                WHEN cvcdec = 8 THEN .00000001
                                WHEN cvcdec = 9 THEN .000000001
                                ELSE .01
                                END AS Decimal_Position
                        FROM PRODDTA.f0013
                    ) F0411_Base_Currency
                    ON AP_Ledger.F0411_Base_Currency = F0411_Base_Currency.cvcrcd
                    LEFT JOIN PRODDTA.F43121 PO_Receiver
                        ON PO_Receiver.prkco = AP_Ledger.rpkco
                        AND PO_Receiver.prdoc = AP_Ledger.F0411_Voucher_Number
                        AND PO_Receiver.prdct = AP_Ledger.rpdct
                        AND PO_Receiver.prmatc IN ('2','3')
                    LEFT JOIN
                        (
                            SELECT
                                tatxa1
                                ,tatxr1 F4008_Tax_Rate_1
                            FROM
                                proddta.f4008
                            WHERE
                                TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 <= taefdj
                                AND TO_NUMBER(TO_CHAR(SYSDATE,'YYYYDDD'))-1900000 - 1 >= taeftj
                                AND tata1 = 11648878
                        ) Tax_Rate
                        ON Tax_Rate.tatxa1 = AP_Ledger.Seller_Tax_Code
                    LEFT JOIN proddta.f4311 Purchase_Order_Detail
                        ON Purchase_Order_Detail.pddoco = PO_Receiver.prdoco
                        AND Purchase_Order_Detail.pddcto = PO_Receiver.prdcto
                        AND Purchase_Order_Detail.pdkcoo = PO_Receiver.prkcoo
                        AND Purchase_Order_Detail.pdsfxo = PO_Receiver.prsfxo
                        AND Purchase_Order_Detail.pdlnid = PO_Receiver.prlnid
                LEFT JOIN
                (
                   SELECT
                       DISTINCT
                            --prdoc AS Receipt_Number
                            prdoco AS PO_Number
                            ,prdcto AS PO_Doc_Type
                            ,prlnid AS PO_Line_ID
                            ,prmcu AS Business_Unit
                            ,prnlin AS Number_of_Lines
                            ,LISTAGG(TRIM(REGEXP_REPLACE(crk74cude,'[^[^A-Za-z0-9]',''))) AS Tracking_Number_ID
                    FROM proddta.F43121
                    LEFT JOIN proddta.f5543125
                        ON crdoc = prdoc
                        AND crdoco = prdoco
                        AND crdcto = prdcto
                        AND crlnid = prlnid
                        AND crmcu = prmcu
                        AND prmatc = ('1')
                    WHERE TRIM(crk74cude) <> ' '
                    GROUP BY prdoco,prdcto,prlnid,prmcu,prnlin
                UNION ALL
                    SELECT
                        DISTINCT
                            --prdoc AS Receipt_Number
                            prdoco AS PO_Number
                            ,prdcto AS PO_Doc_Type
                            ,prlnid AS PO_Line_ID
                            ,prmcu AS Business_Unit
                            ,prnlin AS Number_of_Lines
                            ,LISTAGG(TRIM(REGEXP_REPLACE(redl31,'[^A-Za-z0-9]',''))) AS Tracking_Number_ID
                    FROM proddta.f43121
                    INNER JOIN proddta.f574108
                        ON prmcu = remcu
                        AND prlotn = relotn
                        AND pritm = reitm
                    WHERE
                        prmcu = LPAD('920',12)
                        AND prmatc = '1'
                        AND prurec IS NOT NULL
                        AND TRIM(prlotn) <> ' '
                        AND pritm <> 0
                        AND TRIM(redl31) <> ' '
                    GROUP BY prdoco,prdcto,prlnid,prmcu,prnlin
                ) Tracking_Number
                ON PO_receiver.prdoco = Tracking_Number.PO_Number
                  AND PO_receiver.prdcto = Tracking_Number.PO_Doc_Type
                  AND PO_receiver.prlnid = Tracking_Number.PO_Line_ID
                  AND PO_receiver.prnlin = Tracking_Number.Number_of_Lines
                  AND PO_receiver.prmcu = Tracking_Number.Business_Unit
                LEFT JOIN PRODDTA.F0411 AP_Ledger_Line_Detail
                    ON AP_Ledger_Line_Detail.rpdoc = AP_Ledger.F0411_Voucher_Number
                    AND AP_Ledger_Line_Detail.rpkco = AP_Ledger.rpkco
                    AND AP_Ledger_Line_Detail.rpdct = AP_Ledger.rpdct
                    AND PO_receiver.prdoc IS NULL
                LEFT JOIN prodctl.f0005 UDC_f0411
                    ON AP_Ledger_Line_Detail.rpum = TRIM(UDC_f0411.drky)
                    AND UDC_f0411.drsy = '55'
                    AND UDC_f0411.drrt = 'UM'
                LEFT JOIN prodctl.f0005 UDC_f43121
                    ON PO_Receiver.pruom = TRIM(UDC_f43121.drky)
                    AND UDC_f43121.drsy = '55'
                    AND UDC_f43121.drrt = 'UM'
                INNER JOIN proddta.f550301h f550301h
                    ON f550301h.ehurab = AP_Ledger.F0411_Voucher_Number
                    AND f550301h.ehev01 = 'C'
                    AND f550301h.ehev02 = 'S'
            WHERE
                AP_LEDGER.F0411_Base_Gross_Amount < 0
                AND f550301h.ehdl01 = v_driver_dl01
                AND f550301h.ehurab = v_driver_doc_number;

    BEGIN
        o_return_message    := 'SUCCESS';

        ------------------------------------------------------
        -- Call function to get start/end dates from F0008 for this run
        ------------------------------------------------------
--        v_dates_obj := proddta.f_get_f0008_start_end_dates();
--        DBMS_OUTPUT.PUT_LINE('CN START: ' || v_dates_obj.start_date);
--        DBMS_OUTPUT.PUT_LINE('CN END: ' || v_dates_obj.end_date);

        -- Create an empty XML document
        xml_domdoc      := dbms_xmldom.newDomDocument;

        -- Create a root node
        xml_root_node   := dbms_xmldom.makeNode(xml_domdoc);

        ------------------------------------------------------
        -- Get Audit Information
        ------------------------------------------------------
        SELECT
             UPPER(SUBSTR(SYS_CONTEXT('USERENV','HOST'), INSTR(SYS_CONTEXT('USERENV','HOST'), '\',1,1)+1,10))
            ,TO_NUMBER(TO_CHAR(SYSDATE,'yyyyddd')) - 1900000
            ,TO_NUMBER(TO_CHAR(SYSDATE,'hh24miss'))
        INTO
             v_jobn
            ,v_upmj
            ,v_upmt
        FROM
            dual;

        -----------------------------------------------------------
        -- Credit Notes Wrapper Node
        -----------------------------------------------------------
        xml_credit_notes_element                                := dbms_xmldom.createElement(xml_domdoc, 'ns0:CreditNotes');
        dbms_xmldom.setattribute(xml_credit_notes_element, 'xmlns:ns0', 'http://Plexus.Avalara.JDE_CreditNotes');

        xml_credit_notes_node                                    := dbms_xmldom.appendChild(xml_root_node, dbms_xmldom.makeNode(xml_credit_notes_element));

        OPEN c_driver;

        LOOP

            FETCH
                c_driver
            INTO
                 v_driver_doc_number
                ,v_driver_dl01
                ,v_driver_urdt;

--            DBMS_OUTPUT.PUT_LINE(v_driver_doc_number || '   ' || v_driver_dl01);

            EXIT WHEN c_driver%NOTFOUND;

            v_dates_obj := proddta.f_get_f0008_start_end_dates(v_driver_urdt);

            v_records_found := TRUE;

            -- Reset first record flag for this invoice
            v_is_first_record := TRUE;

            OPEN c_detail;

            LOOP

                FETCH
                    c_detail
                INTO
                     v_HeaderTaskID
                    ,v_CreditNote_ID
                    ,v_IssueDate
                    ,v_IssueTime
                    ,v_CreditNoteTypeCode
                    ,v_CreditNoteTypeCode_ListVersionId
                    ,v_DocumentCurrencyCode
                    ,v_TaxCurrencyCode
                    ,v_BillingReference_InvoiceDocumentReference_ID
                    ,v_BillingReference_InvoiceDocumentReference_UUID
                    ,v_ASP_Party_IndustryClassificationCode
                    ,v_ASP_Party_IndustryClassificationCode__Name
                    ,v_ASP_Party_PartyIdentification_ID1
                    ,v_ASP_Party_PartyIdentification_ID1__SchemeID
                    ,v_ASP_Party_PartyIdentification_ID2
                    ,v_ASP_Party_PartyIdentification_ID2__SchemeID
                    ,v_ASP_Party_PartyIdentification_ID3
                    ,v_ASP_Party_PartyIdentification_ID3__SchemeID
                    ,v_ASP_Party_PartyName_Name
                    ,v_ASP_Party_PostalAddress_StreetName
                    ,v_ASP_Party_PostalAddress_AdditionalStreetName
                    ,v_ASP_Party_PostalAddress_CityName
                    ,v_ASP_Party_PostalAddress_PostalZone
                    ,v_ASP_Party_PostalAddress_CountrySubentityCode
                    ,v_ASP_Party_PostalAddress_Country_IdentificationCode
                    ,v_ASP_Party_PostalAddress_Country_IdentificationCode__ListID
                    ,v_ASP_Party_PostalAddress_Country_IdentificationCode__ListAgencyID
                    ,v_ASP_Party_PartyLegalEntity_RegistrationName
                    ,v_ASP_Party_Contact_Telephone
                    --,v_ASP_Party_Contact_ElectronicMail
                    ,v_ACP_Party_PartyIdentification_ID1
                    ,v_ACP_Party_PartyIdentification_ID1__SchemeID
                    ,v_ACP_Party_PartyIdentification_ID2
                    ,v_ACP_Party_PartyIdentification_ID2__SchemeID
                    ,v_ACP_Party_PartyIdentification_ID3
                    ,v_ACP_Party_PartyIdentification_ID3__SchemeID
                    ,v_ACP_Party_PartyName_Name
                    ,v_ACP_Party_PostalAddress_StreetName
                    ,v_ACP_Party_PostalAddress_AdditionalStreetName
                    ,v_ACP_Party_PostalAddress_CityName
                    ,v_ACP_Party_PostalAddress_PostalZone
                    ,v_ACP_Party_PostalAddress_CountrySubentityCode
                    ,v_ACP_Party_PostalAddress_Country_IdentificationCode
                    ,v_ACP_Party_PostalAddress_Country_IdentificationCode__ListID
                    ,v_ACP_Party_PostalAddress_Country_IdentificationCode__ListAgencyID
                    ,v_ACP_Party_PartyLegalEntity_RegistrationName
                    ,v_ACP_Party_Contact_Telephone
                    --,v_AllowanceCharge_ChargeIndicator
                    --,v_AllowanceCharge_AllowanceChargeReason
                    --,v_AllowanceCharge_Amount
                    --,v_AllowanceCharge_Amount__CurrencyID
                    --,v_PaymentTerms_Note
                    ,v_TaxExchangeRate_SourceCurrencyCode
                    ,v_TaxExchangeRate_TargetCurrencyCode
                    ,v_TaxExchangeRate_CalculationRate
                    ,v_TaxTotal_TaxAmount
                    ,v_TaxTotal_TaxAmount__CurrencyID
                    ,v_TaxTotal_TaxSubtotal_TaxableAmount
                    ,v_TaxTotal_TaxSubtotal_TaxableAmount__CurrencyID
                    ,v_TaxTotal_TaxSubtotal_TaxAmount
                    ,v_TaxTotal_TaxSubtotal_TaxAmount__CurrencyID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_ID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID__SchemeID
                    ,v_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID__SchemeAgencyID
                    ,v_LegalMonetaryTotal_LineExtensionAmount
                    ,v_LegalMonetaryTotal_LineExtensionAmount__CurrencyID
                    ,v_LegalMonetaryTotal_TaxExclusiveAmount
                    ,v_LegalMonetaryTotal_TaxExclusiveAmount__CurrencyID
                    ,v_LegalMonetaryTotal_TaxInclusiveAmount
                    ,v_LegalMonetaryTotal_TaxInclusiveAmount__CurrencyID
                    --,v_LegalMonetaryTotal_SumOfAllowancesOnDocumentLevel
                    --,v_LegalMonetaryTotal_SumOfAllowancesOnDocumentLevel__CurrencyID
                    ,v_LegalMonetaryTotal_PayableAmount
                    ,v_LegalMonetaryTotal_PayableAmount__CurrencyID
                    ,v_CreditNoteLine_ID
                    ,v_CreditNoteLine_CreditedQuantity
                    ,v_CreditNoteLine_CreditedQuantity__UnitCode
                    ,v_CreditNoteLine_LineExtentionAmount
                    ,v_CreditNoteLine_LineExtentionAmount__CurrencyID
                    ,v_CreditNoteLine_TaxTotal_TaxAmount
                    ,v_CreditNoteLine_TaxTotal_TaxAmount__CurrencyID
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxableAmount
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxableAmount__CurrencyID
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxAmount
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxAmount__CurrencyID
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_Percent
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxCategory_ID
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxCategory_TaxExemptionReason
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeID
                    ,v_CreditNoteLine_TaxTotal_TaxSubTotal_TaxCategory_TaxScheme_ID__SchemeAgencyID
                    ,v_CreditNoteLine_Item_Description
                    ,v_CreditNoteLine_Item_OriginCountry_IdentificationCode
                    ,v_CreditNoteLine_Item_CommodityClassification_ItemClassificationCode
                    ,v_CreditNoteLine_Item_CommodityClassification_ItemClassificationCode__ListID
                    ,v_CreditNoteLine_Price_PriceAmount
                    ,v_CreditNoteLine_Price_PriceAmount__CurrencyID
                    ,v_CreditNoteLine_ItemPriceExtension_Amount
                    ,v_CreditNoteLine_ItemPriceExtension_Amount__CurrencyID;

                EXIT WHEN c_detail%NOTFOUND;

                IF v_is_first_record = TRUE THEN

                    v_is_first_record := FALSE;

                    UPDATE
                        proddta.f550301h f550301h
                    SET
                         f550301h.ehedsp = 'I'
                        ,f550301h.ehpid  = v_pid
                        ,f550301h.ehjobn = v_jobn
                        ,f550301h.ehuser = v_user
                        ,f550301h.ehupmj = v_upmj
                        ,f550301h.ehupmt = v_upmt
                    WHERE
                        TRIM(f550301h.ehtaskID) = TRIM(v_HeaderTaskID);

                    COMMIT;

                    -----------------------------------------------------------
                    -- Credit Note
                    -----------------------------------------------------------
                    xml_credit_note_element                                     := dbms_xmldom.createElement(xml_domdoc, 'CreditNote');
                    dbms_xmldom.setattribute(xml_credit_note_element, 'xmlns:cac', 'urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2');
                    dbms_xmldom.setattribute(xml_credit_note_element, 'xmlns:cbc', 'urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2');
                    dbms_xmldom.setattribute(xml_credit_note_element, 'xmlns', 'urn:oasis:names:specification:ubl:schema:xsd:CreditNote-2_JDE');

                    xml_credit_note_node                                       := dbms_xmldom.appendChild(xml_credit_notes_node, dbms_xmldom.makeNode(xml_credit_note_element));

                    xml_header_id_node                                      := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'JDEHeaderID')));
                    xml_header_id_text_node                                 := dbms_xmldom.appendChild(xml_header_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_HeaderTaskID)));

                    xml_id_node                                             := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_id_text_node                                        := dbms_xmldom.appendChild(xml_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNote_ID)));

                    xml_issue_date_node                                     := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IssueDate')));
                    xml_issue_date_text_node                                := dbms_xmldom.appendChild(xml_issue_date_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_IssueDate)));

                    xml_issue_time_node                                     := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IssueTime')));
                    xml_issue_time_text_node                                := dbms_xmldom.appendChild(xml_issue_time_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_IssueTime)));

                    xml_credit_note_type_code_element                       := dbms_xmldom.createElement(xml_domdoc, 'cbc:CreditNoteTypeCode');
                    dbms_xmldom.setAttribute(xml_credit_note_type_code_element, 'listVersionID', v_CreditNoteTypeCode_ListVersionId);

                    xml_credit_note_type_code_node                          := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(xml_credit_note_type_code_element));
                    xml_credit_note_type_code_text_node                     := dbms_xmldom.appendChild(xml_credit_note_type_code_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteTypeCode)));

                    xml_document_currency_code_node                         := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:DocumentCurrencyCode')));
                    xml_document_currency_code_text_node                    := dbms_xmldom.appendChild(xml_document_currency_code_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_DocumentCurrencyCode)));

                    xml_tax_currency_code_node                              := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxCurrencyCode')));
                    xml_tax_currency_code_text_node                         := dbms_xmldom.appendChild(xml_tax_currency_code_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_TaxCurrencyCode)));


                    -----------------------------------------------------------
                    -- Credit Note / Billing Reference
                    -----------------------------------------------------------
                    xml_billing_reference_node                              := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:BillingReference')));

                    -----------------------------------------------------------
                    -- Credit Note / Billing Reference / InvoiceDocumentReference
                    -----------------------------------------------------------
                    xml_billing_reference_inv_doc_reference_node            := dbms_xmldom.appendChild(xml_billing_reference_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:InvoiceDocumentReference')));

                    xml_billing_reference_inv_doc_reference_id_node                              := dbms_xmldom.appendChild(xml_billing_reference_inv_doc_reference_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                    xml_billing_reference_inv_doc_reference_id_text_node                         := dbms_xmldom.appendChild(xml_billing_reference_inv_doc_reference_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_BillingReference_InvoiceDocumentReference_ID)));

                    xml_billing_reference_inv_doc_reference_uuid_node                              := dbms_xmldom.appendChild(xml_billing_reference_inv_doc_reference_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:UUID')));
                    xml_billing_reference_inv_doc_reference_uuid_text_node                         := dbms_xmldom.appendChild(xml_billing_reference_inv_doc_reference_uuid_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_BillingReference_InvoiceDocumentReference_UUID)));

                    -----------------------------------------------------------
                    -- Accounting Supplier Party
                    -----------------------------------------------------------
                    xml_asp_node                                            := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:AccountingSupplierParty')));

                    -----------------------------------------------------------
                    -- Party
                    -----------------------------------------------------------
                    xml_asp_party_node                                      := dbms_xmldom.appendChild(xml_asp_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Party')));

                    xml_asp_party_industry_classification_code_element      := dbms_xmldom.createElement(xml_domdoc, 'cbc:IndustryClassificationCode');
                    dbms_xmldom.setAttribute(xml_asp_party_industry_classification_code_element, 'name', v_ASP_Party_IndustryClassificationCode__Name);

                    xml_asp_party_industry_classification_code_node         := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                                dbms_xmldom.makeNode(xml_asp_party_industry_classification_code_element));
                    xml_asp_party_industry_classification_code_text_node    := dbms_xmldom.appendChild(xml_asp_party_industry_classification_code_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_IndustryClassificationCode)));

                    -----------------------------------------------------------
                    -- Party Identification 1
                    -----------------------------------------------------------
                    xml_asp_party_party_identification1_node                := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PartyIdentification')));

                    xml_asp_party_party_identification1_id_element          := dbms_xmldom.createElement(xml_domdoc, 'cbc:ID');
                    dbms_xmldom.setAttribute(xml_asp_party_party_identification1_id_element, 'schemeID', v_ASP_Party_PartyIdentification_ID1__SchemeID);

                    xml_asp_party_party_identification1_id_node             := dbms_xmldom.appendChild(xml_asp_party_party_identification1_node,
                                                                                dbms_xmldom.makeNode(xml_asp_party_party_identification1_id_element));
                    xml_asp_party_party_identification1_id_text_node        := dbms_xmldom.appendChild(xml_asp_party_party_identification1_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyIdentification_ID1)));

                    -----------------------------------------------------------
                    -- Party Identification 2
                    -----------------------------------------------------------
                    xml_asp_party_party_identification2_node                := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PartyIdentification')));

                    xml_asp_party_party_identification2_id_element          := dbms_xmldom.createElement(xml_domdoc, 'cbc:ID');
                    dbms_xmldom.setAttribute(xml_asp_party_party_identification2_id_element, 'schemeID', v_ASP_Party_PartyIdentification_ID2__SchemeID);

                    xml_asp_party_party_identification2_id_node             := dbms_xmldom.appendChild(xml_asp_party_party_identification2_node,
                                                                                dbms_xmldom.makeNode(xml_asp_party_party_identification2_id_element));
                    xml_asp_party_party_identification2_id_text_node        := dbms_xmldom.appendChild(xml_asp_party_party_identification2_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyIdentification_ID2)));

                    -----------------------------------------------------------
                    -- Party Identification 3
                    -----------------------------------------------------------
                    xml_asp_party_party_identification3_node                := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PartyIdentification')));

                    xml_asp_party_party_identification3_id_element          := dbms_xmldom.createElement(xml_domdoc, 'cbc:ID');
                    dbms_xmldom.setAttribute(xml_asp_party_party_identification3_id_element, 'schemeID', v_ASP_Party_PartyIdentification_ID3__SchemeID);

                    xml_asp_party_party_identification3_id_node             := dbms_xmldom.appendChild(xml_asp_party_party_identification3_node,
                                                                                dbms_xmldom.makeNode(xml_asp_party_party_identification3_id_element));
                    xml_asp_party_party_identification3_id_text_node        := dbms_xmldom.appendChild(xml_asp_party_party_identification3_id_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyIdentification_ID3)));

                    -----------------------------------------------------------
                    -- Party Name
                    -----------------------------------------------------------
                    xml_asp_party_name_node                                 := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PartyName')));

                    xml_asp_party_name_name_node                            := dbms_xmldom.appendChild(xml_asp_party_name_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Name')));
                    xml_asp_party_name_name_text_node                       := dbms_xmldom.appendChild(xml_asp_party_name_name_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PartyName_Name)));

                    -----------------------------------------------------------
                    -- Postal Address
                    -----------------------------------------------------------
                    xml_asp_postal_address_node                             := dbms_xmldom.appendChild(xml_asp_party_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:PostalAddress')));

                    xml_asp_street_name_node                                := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:StreetName')));
                    xml_asp_street_name_text_node                           := dbms_xmldom.appendChild(xml_asp_street_name_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_StreetName)));

                    xml_asp_additional_street_name_node                     := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:AdditionalStreetName')));
                    xml_asp_additional_street_name_text_node                := dbms_xmldom.appendChild(xml_asp_additional_street_name_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_AdditionalStreetName)));

                    xml_asp_city_name_node                                  := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CityName')));
                    xml_asp_city_name_text_node                             := dbms_xmldom.appendChild(xml_asp_city_name_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_CityName)));

                    xml_asp_postal_zone_node                                := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:PostalZone')));
                    xml_asp_postal_zone_text_node                           := dbms_xmldom.appendChild(xml_asp_postal_zone_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_PostalZone)));

                    xml_asp_country_subentity_code_node                     := dbms_xmldom.appendChild(xml_asp_postal_address_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:CountrySubentityCode')));
                    xml_asp_country_subentity_code_text_node                := dbms_xmldom.appendChild(xml_asp_country_subentity_code_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_ASP_Party_PostalAddress_CountrySubentityCode)));

                    -----------------------------------------------------------
                    -- Country
                    -----------------------------------------------------------
                    xml_asp_country_node                                    := dbms_xmldom.appendChild(xml_asp_postal_address_node,
