                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_TaxExclusiveAmount)));

                    xml_lmt_tax_incl_amt_element                            := dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxInclusiveAmount');
                    dbms_xmldom.setAttribute(xml_lmt_tax_incl_amt_element, 'currencyID', v_LegalMonetaryTotal_TaxInclusiveAmount__CurrencyID);

                    xml_lmt_tax_incl_amt_node                               := dbms_xmldom.appendChild(xml_legal_monetary_total_node,
                                                                                dbms_xmldom.makeNode(xml_lmt_tax_incl_amt_element));
                    xml_lmt_tax_incl_amt_text_node                          := dbms_xmldom.appendChild(xml_lmt_tax_incl_amt_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_TaxInclusiveAmount)));

                    --xml_lmt_sum_allowance_element                             := dbms_xmldom.createElement(xml_domdoc, 'cbc:SumOfAllowancesOnDocumentLevel');
                    --dbms_xmldom.setAttribute(xml_lmt_sum_allowance_element, 'currencyID', v_LegalMonetaryTotal_SumOfAllowancesOnDocumentLevel__CurrencyID);
                    --
                    --xml_lmt_sum_allowance_node                               := dbms_xmldom.appendChild(xml_legal_monetary_total_node,
                    --                                                            dbms_xmldom.makeNode(xml_lmt_sum_allowance_element));
                    --xml_lmt_sum_allowance_text_node                           := dbms_xmldom.appendChild(xml_lmt_sum_allowance_node,
                    --                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_SumOfAllowancesOnDocumentLevel)));
                    --
                    xml_lmt_payable_amt_element                             := dbms_xmldom.createElement(xml_domdoc, 'cbc:PayableAmount');
                    dbms_xmldom.setAttribute(xml_lmt_payable_amt_element, 'currencyID', v_LegalMonetaryTotal_PayableAmount__CurrencyID);

                    xml_lmt_payable_amt_node                               := dbms_xmldom.appendChild(xml_legal_monetary_total_node,
                                                                                dbms_xmldom.makeNode(xml_lmt_payable_amt_element));
                    xml_lmt_payable_amt_text_node                           := dbms_xmldom.appendChild(xml_lmt_payable_amt_node,
                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_LegalMonetaryTotal_PayableAmount)));

                END IF;

                -----------------------------------------------------------
                -- Credit Note Line
                -----------------------------------------------------------
                xml_cn_line_node                                   := dbms_xmldom.appendChild(xml_credit_note_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:CreditNoteLine')));

                xml_cn_line_id_node                                    := dbms_xmldom.appendChild(xml_cn_line_node,
