                xml_cn_line_id_text_node                                := dbms_xmldom.appendChild(xml_cn_line_id_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_ID )));

                xml_cn_line_cred_qty_element                            := dbms_xmldom.createElement(xml_domdoc, 'cbc:CreditedQuantity ');
                dbms_xmldom.setAttribute(xml_cn_line_cred_qty_element, 'unitCode', v_CreditNoteLine_CreditedQuantity__UnitCode);
                xml_cn_line_cred_qty_node                               := dbms_xmldom.appendChild(xml_cn_line_node,
                                                                            dbms_xmldom.makeNode(xml_cn_line_cred_qty_element));
