                xml_cn_line_tax_total_amount_element                           := dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxAmount');
                dbms_xmldom.setAttribute(xml_cn_line_tax_total_amount_element, 'currencyID', v_CreditNoteLine_TaxTotal_TaxAmount__CurrencyID);

                xml_cn_line_tax_total_amount_node                              := dbms_xmldom.appendChild(xml_cn_line_tax_total_node,
                                                                                    dbms_xmldom.makeNode(xml_cn_line_tax_total_amount_element));
                xml_cn_line_tax_total_amount_text_node                         := dbms_xmldom.appendChild(xml_cn_line_tax_total_amount_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_TaxTotal_TaxAmount)));

                -----------------------------------------------------------
                -- Credit Note Line / Tax Subtotal
                -----------------------------------------------------------
                xml_cn_line_tax_total_tax_subtotal_node                        := dbms_xmldom.appendChild(xml_cn_line_tax_total_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxSubtotal')));

                xml_cn_line_tax_total_tax_subtotal_taxable_amount_element      := dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxableAmount');
                dbms_xmldom.setAttribute(xml_cn_line_tax_total_tax_subtotal_taxable_amount_element, 'currencyID', v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxableAmount__CurrencyID);

                xml_cn_line_tax_total_tax_subtotal_taxable_amount_node         := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_node,
