                xml_cn_line_tax_total_tax_subtotal_taxable_amount_text_node    := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_taxable_amount_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxableAmount)));

                xml_cn_line_tax_total_tax_subtotal_tax_amount_element          := dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxAmount');
