                xml_cn_line_tax_total_tax_subtotal_tax_amount_text_node        := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_amount_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxAmount)));

                xml_cn_line_tax_total_tax_subtotal_percent_node                := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Percent')));
                xml_cn_line_tax_total_tax_subtotal_percent_text_node           := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_percent_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_TaxTotal_TaxSubTotal_Percent)));

                -----------------------------------------------------------
                -- Credit Note Line / Tax Total / Tax Subtotal / Tax Category
                -----------------------------------------------------------
                xml_cn_line_tax_total_tax_subtotal_tax_category_node           := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxCategory')));

                xml_cn_line_tax_total_tax_subtotal_tax_category_id_node        := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_category_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:ID')));
                xml_cn_line_tax_total_tax_subtotal_tax_category_id_text_node   := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_category_id_node,
                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxCategory_ID)));

                xml_cn_line_tax_total_tax_subtotal_tax_category_tax_exemption_reason_node      := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_category_node,
                                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:TaxExemptionReason')));
                xml_cn_line_tax_total_tax_subtotal_tax_category_tax_exemption_reason_text_node := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_category_tax_exemption_reason_node,
                                                                                                    dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxCategory_TaxExemptionReason)));


                -----------------------------------------------------------
                -- Credit Note Line / Tax Total / Tax Subtotal / Tax Category / Tax Scheme
                -----------------------------------------------------------
                xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_node             := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_category_node,
                                                                                                dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:TaxScheme')));

                xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_id_element       := dbms_xmldom.createElement(xml_domdoc, 'cbc:ID');
                dbms_xmldom.setAttribute(xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_id_element, 'schemeID', v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID__SchemeID);
                dbms_xmldom.setAttribute(xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_id_element, 'schemeAgencyID', v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID__SchemeAgencyID);

                xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_id_node          := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_node,
                                                                                                dbms_xmldom.makeNode(xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_id_element));
                xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_id_text_node     := dbms_xmldom.appendChild(xml_cn_line_tax_total_tax_subtotal_tax_category_tax_scheme_id_node,
                                                                                                dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_TaxTotal_TaxSubtotal_TaxCategory_TaxScheme_ID)));

                -----------------------------------------------------------
                -- Credit Note Line / Item
                -----------------------------------------------------------
                xml_cn_line_item_node                                  := dbms_xmldom.appendChild(xml_cn_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Item')));

                xml_cn_line_item_description_node                      := dbms_xmldom.appendChild(xml_cn_line_item_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:Description')));
                xml_cn_line_item_description_text_node                  := dbms_xmldom.appendChild(xml_cn_line_item_description_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_Description)));

                -----------------------------------------------------------
                -- InvoiceLine / Item / OriginCountry
                -----------------------------------------------------------
                xml_cn_line_item_origin_country_node                   := dbms_xmldom.appendChild(xml_cn_line_item_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:OriginCountry')));

                xml_cn_line_item_org_cou_identification_code_node      := dbms_xmldom.appendChild(xml_cn_line_item_origin_country_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cbc:IdentificationCode')));
                xml_cn_line_item_org_cou_identification_code_text_node := dbms_xmldom.appendChild(xml_cn_line_item_org_cou_identification_code_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_OriginCountry_IdentificationCode)));

                -----------------------------------------------------------
                -- InvoiceLine / Item / CommodityClassification
                -----------------------------------------------------------
                xml_cn_line_item_comm_class_node                       := dbms_xmldom.appendChild(xml_cn_line_item_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:CommodityClassification')));

                xml_cn_line_item_classification_code_element           := dbms_xmldom.createElement(xml_domdoc, 'cbc:ItemClassificationCode');
                dbms_xmldom.setAttribute(xml_cn_line_item_classification_code_element, 'listID', v_CreditNoteLine_Item_CommodityClassification_ItemClassificationCode__ListId);

                xml_cn_line_item_classification_code_node              := dbms_xmldom.appendChild(xml_cn_line_item_comm_class_node,
                                                                            dbms_xmldom.makeNode(xml_cn_line_item_classification_code_element));
                xml_cn_line_item_classification_code_text_node         := dbms_xmldom.appendChild(xml_cn_line_item_classification_code_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Item_CommodityClassification_ItemClassificationCode)));

                -----------------------------------------------------------
                -- InvoiceLine / Price
                -----------------------------------------------------------
                xml_cn_line_price_node                                 := dbms_xmldom.appendChild(xml_cn_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:Price')));

                xml_cn_line_price_price_amount_element                 := dbms_xmldom.createElement(xml_domdoc, 'cbc:PriceAmount');
                dbms_xmldom.setAttribute(xml_cn_line_price_price_amount_element, 'currencyID', v_CreditNoteLine_Price_PriceAmount__CurrencyId);

                xml_cn_line_price_price_amount_node                    := dbms_xmldom.appendChild(xml_cn_line_price_node,
                                                                            dbms_xmldom.makeNode(xml_cn_line_price_price_amount_element));
                xml_cn_line_price_price_amount_text_node               := dbms_xmldom.appendChild(xml_cn_line_price_price_amount_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_Price_PriceAmount)));

                -----------------------------------------------------------
                -- InvoiceLine / ItemPriceExtension
                -----------------------------------------------------------
                xml_cn_line_item_price_extension_node                  := dbms_xmldom.appendChild(xml_cn_line_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'cac:ItemPriceExtension')));

                xml_cn_line_item_price_extension_amount_element        := dbms_xmldom.createElement(xml_domdoc, 'cbc:Amount');
                dbms_xmldom.setAttribute(xml_cn_line_item_price_extension_amount_element, 'currencyID', v_CreditNoteLine_ItemPriceExtension_Amount__CurrencyId);

                xml_cn_line_item_price_extension_amount_node           := dbms_xmldom.appendChild(xml_cn_line_item_price_extension_node,
                                                                            dbms_xmldom.makeNode(xml_cn_line_item_price_extension_amount_element));
                xml_cn_line_item_price_extension_amount_text_node      := dbms_xmldom.appendChild(xml_cn_line_item_price_extension_amount_node,
                                                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, v_CreditNoteLine_ItemPriceExtension_Amount)));

            END LOOP;

            CLOSE c_detail;

        END LOOP;

        CLOSE c_driver;

        xml_xmltype     := dbms_xmldom.getXmlType(xml_domdoc);
        dbms_xmldom.freeDocument(xml_domdoc);

        IF v_records_found = TRUE THEN

            o_xml_clob      := xml_xmltype.getClobVal;

        ELSE

            o_xml_clob      := TO_CLOB('No Data Found');

        END IF;

        EXCEPTION
            WHEN OTHERS THEN

                v_err_nbr := SQLCODE;
                v_err_msg := v_err_job_name || ' - '||SQLERRM;

                ------------------------------------------------------
                -- Rollback changes
                ------------------------------------------------------
                ROLLBACK;

                ------------------------------------------------------
                -- Insert record into PL/SQL logging table
                ------------------------------------------------------
                INSERT INTO
                    commobj.joberr
                    (
                        job_name,
                        err#,
                        err_msg,
                        TIMESTAMP
                    )
                    VALUES
                    (
                        v_err_job_name,
                        v_err_nbr,
                        v_err_msg,
                        SYSDATE
                    );

                COMMIT;

                o_return_message := 'FAILURE: ' || SQLERRM;

    END USP_MY_CN_SELFBILL_XML_SELECT;





    /***********************************************************************************************************
    ***********************************************************************************************************/
    -- USP_MY_DOC_STATUS_SELECT
    /***********************************************************************************************************
    ***********************************************************************************************************/

    PROCEDURE USP_MY_DOC_STATUS_SELECT
    (
         o_xml_clob         OUT    NOCOPY CLOB
        ,o_return_message   OUT    VARCHAR2
    )
    IS

        -----------------------------------------------------------
        -- Declare Exception Variables
        -----------------------------------------------------------
        v_err_job_name  VARCHAR2(30)        := 'USP_MY_DOC_STATUS_SELECT';
        v_err_nbr       VARCHAR2(10)        := ' ';
        v_err_msg       VARCHAR2(2000)      := ' ';

         ----------------------------------------------------------
        -- Declare Cursor Variables
        -----------------------------------------------------------
        v_task_id       CHAR(36 BYTE)   := ' ';
        v_avalara_id    CHAR(80 BYTE)   := ' ';

        ----------------------------------------------------------
        -- Declare Other Variables
        -----------------------------------------------------------
        v_records_found BOOLEAN         := FALSE;
        v_retry_count   NUMBER          := 0;

        ----------------------------------------------------------
        -- Declare Cursors
        -----------------------------------------------------------
        CURSOR c_records IS
            SELECT
                 ehtaskid   -- F550301H unique ID (system guid)
                ,ehds80     -- Avalara ID
            FROM
                proddta.f550301h
            WHERE
                ehedsp = 'Y'
                AND ehev02 IN ('M', 'S')
                AND
                (
                    TRIM(ehev03) IS NULL
                    OR ehev03 IN ('E', 'P')
                )
                AND
                (
                    ehrltm IS NULL
                    OR ehrltm <= 5
                )
            ORDER BY ehupmj DESC
            FETCH FIRST 50 ROWS ONLY;

        /*

            Sample XML Output

            <?xml version="1.0"?>
            <ns0:Records xmlns:ns0="http://Plexus.Avalara.Records">
                <Record xmlns="http://Plexus.Avalara.Record">
                    <AvalaraId>ed028a89-e8cb-4dc4-bfd0-ca572c0d01b0</AvalaraId>
                    <JDEHeaderId>1E641F7D0516CC84E063215AFA0AC3A0</JDEHeaderId>
                </Record>
                <Record xmlns="http://Plexus.Avalara.Record">
                    <AvalaraId>2f80a421-6ca6-4d79-909b-5ed5409b004b</AvalaraId>
                    <JDEHeaderId>1E641F7D04EECC84E063215AFA0AC3A0</JDEHeaderId>
                </Record>
            </ns0:Records>

        */

        -----------------------------------------------------------
        -- Declare XML Variables
        -----------------------------------------------------------
        xml_xmltype     XMLTYPE;
        xml_domdoc      dbms_xmldom.DOMDocument;
        xml_root_node   dbms_xmldom.DOMNode;

        -----------------------------------------------------------
        -- Records
        -----------------------------------------------------------
        xml_records_element         dbms_xmldom.DOMElement;
        xml_records_node            dbms_xmldom.DOMNode;

        -----------------------------------------------------------
        -- Record
        -----------------------------------------------------------
        xml_record_element          dbms_xmldom.DOMElement;
        xml_record_node             dbms_xmldom.DOMNode;

        xml_AvalaraId_node          dbms_xmldom.DOMNode;
        xml_AvalaraId_text_node     dbms_xmldom.DOMNode;

        xml_JDEHeaderId_node        dbms_xmldom.DOMNode;
        xml_JDEHeaderId_text_node   dbms_xmldom.DOMNode;

    BEGIN

        o_return_message    := 'SUCCESS';

        -- Create an empty XML document
        xml_domdoc      := dbms_xmldom.newDomDocument;

        -- Create a root node
        xml_root_node   := dbms_xmldom.makeNode(xml_domdoc);

        -----------------------------------------------------------
        -- Create Records wrapper node
        -----------------------------------------------------------
        xml_records_element     := dbms_xmldom.createElement(xml_domdoc, 'ns0:Records');
        dbms_xmldom.setattribute(xml_records_element, 'xmlns:ns0', 'http://Plexus.Avalara.Records');

        xml_records_node   := dbms_xmldom.appendChild(xml_root_node, dbms_xmldom.makeNode(xml_records_element));

        OPEN c_records;

        LOOP

            FETCH
                c_records
            INTO
                 v_task_id
                ,v_avalara_id;

            EXIT WHEN c_records%NOTFOUND;

            v_records_found := TRUE;


            -- Get current retry count to see if it is null
            SELECT
                ehrltm
            INTO
                v_retry_count
            FROM
                proddta.f550301h
            WHERE
                ehtaskid = v_task_id;

            -- Update counter for number of times this record
            -- has tried to be processed
            -- If null, need to set to 1, else increment
            IF v_retry_count IS NULL THEN

                UPDATE
                    proddta.f550301h
                SET
                    ehrltm = 1
                WHERE
                    ehtaskid = v_task_id;

            ELSE

                UPDATE
                    proddta.f550301h
                SET
                    ehrltm = ehrltm + 1
                WHERE
                    ehtaskid = v_task_id;

            END IF;

            COMMIT;

            -----------------------------------------------------------
            -- Create Record node
            -----------------------------------------------------------
            xml_record_element     := dbms_xmldom.createElement(xml_domdoc, 'Record');
            dbms_xmldom.setattribute(xml_record_element, 'xmlns', 'http://Plexus.Avalara.Record');

            xml_record_node   := dbms_xmldom.appendChild(xml_records_node, dbms_xmldom.makeNode(xml_record_element));

            -----------------------------------------------------------
            -- Create AvalaraId node
            -----------------------------------------------------------
            xml_AvalaraId_node          := dbms_xmldom.appendChild(xml_record_node,
                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'AvalaraId')));
            xml_AvalaraId_text_node     := dbms_xmldom.appendChild(xml_AvalaraId_node,
                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, TRIM(v_avalara_id))));

            -----------------------------------------------------------
            -- Create JDEHeaderID node
            -----------------------------------------------------------
            xml_JDEHeaderId_node        := dbms_xmldom.appendChild(xml_record_node,
                                            dbms_xmldom.makeNode(dbms_xmldom.createElement(xml_domdoc, 'JDEHeaderId')));
            xml_JDEHeaderId_text_node   := dbms_xmldom.appendChild(xml_JDEHeaderId_node,
                                            dbms_xmldom.makeNode(dbms_xmldom.createTextNode(xml_domdoc, TRIM(v_task_id))));

        END LOOP;

        CLOSE c_records;

        xml_xmltype     := dbms_xmldom.getXmlType(xml_domdoc);
        dbms_xmldom.freeDocument(xml_domdoc);

        IF v_records_found = TRUE THEN

            o_xml_clob      := xml_xmltype.getClobVal;

        ELSE

            o_xml_clob      := TO_CLOB('No Data Found');

        END IF;

    END USP_MY_DOC_STATUS_SELECT;





    /***********************************************************************************************************
    ***********************************************************************************************************/
    -- USP_HEADER_STATUS_UPDATE
    /***********************************************************************************************************
    ***********************************************************************************************************/

    -- Update status of specific f550301h record.  Used to update to complete or error (Y, E)

    PROCEDURE USP_HEADER_STATUS_UPDATE
    (
         i_task_id          IN     VARCHAR2
        ,i_new_status       IN     VARCHAR2
        ,o_return_message   OUT    VARCHAR2
    )
    IS

        ------------------------------------------------------
        -- Declare Exception Variables
        ------------------------------------------------------
        v_err_job_name          VARCHAR2(30)        := 'USP_HEADER_STATUS_UPDATE';
        v_err_nbr               VARCHAR2(10)        := ' ';
        v_err_msg               VARCHAR2(2000)      := ' ';

        ------------------------------------------------------
        -- Declare Audit Variables
        ------------------------------------------------------
        v_pid                   VARCHAR2(10)        := SUBSTR('PKG_E_INVOICING',5,10);
        v_jobn                  VARCHAR2(10)        := '';
        v_user                  VARCHAR2(10)        := 'BIZTALK';
        v_upmj                  NUMBER(6)           := 0;
        v_upmt                  NUMBER(6)           := 0;

        ------------------------------------------------------
        -- Declare Other Variables
        ------------------------------------------------------
        v_record_count          NUMBER              := 0;

    BEGIN

        ------------------------------------------------------
        -- Initialize Variables
        ------------------------------------------------------
        o_return_message    := 'SUCCESS';

        ------------------------------------------------------
        -- Get Audit Information
        ------------------------------------------------------
        SELECT
             UPPER(SUBSTR(SYS_CONTEXT('USERENV','HOST'), INSTR(SYS_CONTEXT('USERENV','HOST'), '\',1,1)+1,10))
            ,TO_NUMBER(TO_CHAR(SYSDATE,'yyyyddd')) - 1900000
            ,TO_NUMBER(TO_CHAR(SYSDATE,'hh24miss'))
        INTO
             v_jobn
            ,v_upmj
            ,v_upmt
        FROM
            dual;

        ------------------------------------------------------
        -- Update header table
        ------------------------------------------------------
        UPDATE
            proddta.f550301h
        SET
             ehedsp = TRIM(i_new_status)
            ,ehpid  = v_pid
            ,ehjobn = v_jobn
            ,ehuser = v_user
            ,ehupmj = v_upmj
            ,ehupmt = v_upmt
        WHERE
            TRIM(ehtaskid) = TRIM(i_task_id);

        v_record_count := SQL%rowcount;

        ------------------------------------------------------
        -- If one record updated, commit, else fail and rollback
        ------------------------------------------------------
        IF v_record_count <> 1 THEN
            o_return_message := 'FAILURE: Records updated did not equal 1';
            ROLLBACK;
        ELSE
            COMMIT;
        END IF;

        EXCEPTION
            WHEN OTHERS THEN

                v_err_nbr := SQLCODE;
                v_err_msg := v_err_job_name || ' - '||SQLERRM;

                ------------------------------------------------------
                -- Rollback changes
                ------------------------------------------------------
                ROLLBACK;

                ------------------------------------------------------
                -- Insert record into PL/SQL logging table
                ------------------------------------------------------
                INSERT INTO
                    commobj.joberr
                    (
                        job_name,
                        err#,
                        err_msg,
                        TIMESTAMP
                    )
                    VALUES
                    (
                        v_err_job_name,
                        v_err_nbr,
                        v_err_msg,
                        SYSDATE
                    );

                COMMIT;

                o_return_message := 'FAILURE: ' || SQLERRM;

    END USP_HEADER_STATUS_UPDATE;


