        EXCEPTION
            WHEN OTHERS THEN

                v_err_nbr := SQLCODE;
                v_err_msg := v_err_job_name || ' - '||SQLERRM;

                ------------------------------------------------------
                -- Rollback changes
                ------------------------------------------------------
                ROLLBACK;

                ------------------------------------------------------
                -- Insert record into PL/SQL logging table
                ------------------------------------------------------
                INSERT INTO
                    commobj.joberr
                    (
                        job_name,
                        err#,
                        err_msg,
                        TIMESTAMP
