    /***********************************************************************************************************
    ***********************************************************************************************************/
    -- USP_DOC_STATUS_UPDATE
    /***********************************************************************************************************
    ***********************************************************************************************************/

    -- Update f550301h by task id with information from the Get Document Details API
    -- Some of this information will be used to form the QR code

    PROCEDURE USP_DOC_STATUS_UPDATE
    (
         i_task_id              IN     VARCHAR2
        ,i_status               IN     VARCHAR2
        ,i_uuid                 IN     VARCHAR2 DEFAULT ' '
        ,i_longid               IN     VARCHAR2 DEFAULT ' '
        ,i_date_time_validated  IN     VARCHAR2 DEFAULT ' '
        ,o_return_message       OUT    VARCHAR2
    )
    IS

        ------------------------------------------------------
        -- Declare Exception Variables
        ------------------------------------------------------
        v_err_job_name          VARCHAR2(30)        := 'USP_DOC_STATUS_UPDATE';
        v_err_nbr               VARCHAR2(10)        := ' ';
        v_err_msg               VARCHAR2(2000)      := ' ';

        ------------------------------------------------------
        -- Declare Audit Variables
        ------------------------------------------------------
        v_pid                   VARCHAR2(10)        := 'DOC_ST_UPD';
        v_jobn                  VARCHAR2(10)        := '';
        v_user                  VARCHAR2(10)        := 'BIZTALK';
        v_upmj                  NUMBER(6)           := 0;
        v_upmt                  NUMBER(6)           := 0;

        ------------------------------------------------------
        -- Declare Other Variables
        ------------------------------------------------------
        v_record_count          NUMBER              := 0;
        v_status                CHAR(1)             := NULL;
        v_uuid                  VARCHAR2(500)       := ' ';
        v_longid                VARCHAR2(500)       := ' ';
        v_date_time_validated   VARCHAR2(500)       := ' ';
        v_ev04_check            CHAR(1)             := ' ';
        v_ev02_check            CHAR(1)             := ' ';
        v_ev01_check            CHAR(1)             := ' ';
        v_ev04_check_count      CHAR(1)             := ' ';

    BEGIN

        ------------------------------------------------------
        -- Initialize Variables
        ------------------------------------------------------
        o_return_message        := 'SUCCESS';
        v_uuid                  := i_uuid;
        v_longid                := i_longid;
        v_date_time_validated   := i_date_time_validated;

        ------------------------------------------------------
        -- Get Audit Information
        ------------------------------------------------------
        SELECT
             UPPER(SUBSTR(SYS_CONTEXT('USERENV','HOST'), INSTR(SYS_CONTEXT('USERENV','HOST'), '\',1,1)+1,10))
            ,TO_NUMBER(TO_CHAR(SYSDATE,'yyyyddd')) - 1900000
            ,TO_NUMBER(TO_CHAR(SYSDATE,'hh24miss'))
        INTO
             v_jobn
            ,v_upmj
            ,v_upmt
        FROM
            dual;

        -- Make sure task id exists
        SELECT
            COUNT(1)
        INTO
            v_ev04_check_count
        FROM
            proddta.f550301h
        WHERE
            TRIM(ehtaskid) = TRIM(i_task_id);

        IF v_ev04_check_count = 1 THEN

            SELECT
                ehev04,
                ehev02,
                ehev01
            INTO
                 v_ev04_check
                ,v_ev02_check
                ,v_ev01_check
            FROM
                proddta.f550301h
            WHERE
                TRIM(ehtaskid) = TRIM(i_task_id);

            /*
                - DL011 (100) - Date/Time Stamp
                - CONSTR1 (256) - UUID
                - CONSTR2 (256) - LongID
            */

            -- For all of these, setting v_status (F550301H.EV03) to N will trigger
            -- QR Code UBE to pick up record.  Setting v_status to Z will
            -- prevent QR Code UBE from picking up.

            IF -- Malaysia AR Inv/CN, Malaysia Buyer (Send QR Code)
                UPPER(i_status) = 'COMPLETE'
                AND v_ev04_check IS NULL
                AND v_ev02_check = 'M'
            THEN
                v_status := 'N';
            ELSIF -- Malaysia AR Inv/CN Non-Malaysia Buyer (Do NOT send QR Code)
                UPPER(i_status) = 'COMPLETE'
                AND v_ev04_check = 'X'
                AND v_ev02_check = 'M'
            THEN
                v_status := 'Z';
            ELSIF -- Self Bill (Malaysia Only) (Do NOT send QR Code)
                UPPER(i_status) = 'COMPLETE'
                AND v_ev02_check = 'S'
            THEN
                v_status := 'Z';
            ELSIF UPPER(i_status) = 'PENDING' THEN
                v_status := 'P';
                IF TRIM(i_uuid) IS NULL THEN v_uuid := 'PENDING'; END IF;
                IF TRIM(i_longid) IS NULL THEN v_longid := 'PENDING'; END IF;
                IF TRIM(i_date_time_validated) IS NULL THEN v_date_time_validated := 'PENDING'; END IF;
            ELSIF UPPER(i_status) = 'ERROR' THEN
                v_status := 'E';
                IF TRIM(i_uuid) IS NULL THEN v_uuid := 'ERROR'; END IF;
                IF TRIM(i_longid) IS NULL THEN v_longid := 'ERROR'; END IF;
                IF TRIM(i_date_time_validated) IS NULL THEN v_date_time_validated := 'ERROR'; END IF;
            ELSE
                v_status    := NULL;
                v_uuid      := NULL;
                v_longid    := NULL;
                v_date_time_validated := NULL;
            END IF;

            ------------------------------------------------------
            -- Update header table
            ------------------------------------------------------
            UPDATE
                proddta.f550301h
            SET
                 ehdl011    = v_date_time_validated
                ,ehconstr1  = v_uuid
                ,ehconstr2  = v_longid
                ,ehev03     = v_status
                ,ehpid      = v_pid
                ,ehjobn     = v_jobn
                ,ehuser     = v_user
                ,ehupmj     = v_upmj
                ,ehupmt     = v_upmt
            WHERE
                TRIM(ehtaskid) = TRIM(i_task_id);

            v_record_count := SQL%rowcount;

            ------------------------------------------------------
            -- If one record updated, commit, else fail and rollback
            ------------------------------------------------------
            IF v_record_count <> 1 THEN
                o_return_message := 'FAILURE: Records updated did not equal 1';
                ROLLBACK;
            ELSE
                COMMIT;
            END IF;

        ELSE

            o_return_message := 'FAILURE: Task ID ' || i_task_id || ' was not found in F550301H';

        END IF;

        EXCEPTION
            WHEN OTHERS THEN

                v_err_nbr := SQLCODE;
                v_err_msg := v_err_job_name || ' - F550301H.EHTASKID: '||
                                TRIM(i_task_id) || ' - ' || SQLERRM;

                ------------------------------------------------------
                -- Rollback changes
                ------------------------------------------------------
                ROLLBACK;

                ------------------------------------------------------
                -- Insert record into PL/SQL logging table
                ------------------------------------------------------
                INSERT INTO
                    commobj.joberr
                    (
                        job_name,
                        err#,
                        err_msg,
                        TIMESTAMP
                    )
                    VALUES
                    (
                        v_err_job_name,
                        v_err_nbr,
                        v_err_msg,
                        SYSDATE
                    );

                COMMIT;

                o_return_message := 'FAILURE: ' || v_err_msg;

    END USP_DOC_STATUS_UPDATE;






    /***********************************************************************************************************
    ***********************************************************************************************************/
    -- FN_RO_INVOICE_POLLING
    /***********************************************************************************************************
    ***********************************************************************************************************/

    -- Return 1 if there are invoice records to process

    FUNCTION FN_RO_INVOICE_POLLING RETURN NUMBER AS

        ncount NUMBER;

    BEGIN
        ------------------------------------------------------
        -- Fetch Count
        ------------------------------------------------------
        SELECT
            COUNT(1)
        INTO
            ncount
        FROM
            proddta.f550301h
        WHERE
            ehev01 = 'I'
            AND ehev02 = 'R'
            AND
            (
                ehedsp = 'N'
                OR
                (
                    ehedsp IN ('I', 'P')
                    AND
                    (
                        24 *
                        (
                            SYSDATE
                            -
                            TO_DATE
                            (
                                TO_CHAR(TO_DATE(TO_CHAR(f550301h.ehupmj+1900000),'YYYYDDD'),'yyyy-mm-dd')
                                || ' ' || LPAD(TO_CHAR(f550301h.ehupmt), 6, '0' ),
                                'yyyy-mm-dd hh24miss'
                            )
                        )
                        >= 24
                    )
                )
            )
            AND ROWNUM = 1;

        RETURN ncount;

    END FN_RO_INVOICE_POLLING;





