    /***********************************************************************************************************
    ***********************************************************************************************************/
    -- FN_MY_DOC_STATUS_POLLING
    /***********************************************************************************************************
    ***********************************************************************************************************/

    -- Return 1 if there are records to process for the QR code integration

    FUNCTION FN_MY_DOC_STATUS_POLLING RETURN NUMBER AS

        ncount NUMBER;

    BEGIN
        ------------------------------------------------------
        -- Fetch Count
        ------------------------------------------------------
        SELECT
            COUNT(1)
        INTO
            ncount
        FROM
            proddta.f550301h
        WHERE
            ehedsp = 'Y'
            AND ehev02 IN ('M', 'S')
            AND
            (
                TRIM(ehev03) IS NULL
                OR ehev03 IN ('E', 'P')
            )
            AND
            (
                ehrltm IS NULL
                OR ehrltm <= 5
            )
            AND ROWNUM = 1;

        RETURN ncount;

    END FN_MY_DOC_STATUS_POLLING;



